import React, { useState, useMemo } from 'react';
import { useMutation, useQueryClient } from 'react-query';
import { useDispatch, useSelector } from 'react-redux';
import { Button, message, Modal, Checkbox } from 'antd';
import styled from 'styled-components';

import { fetchPlanHatApi } from 'redux/actions/common';
import SettingApi from 'services/settingApi';
import { DeleteIconSvg } from '../SvgIcon';
import { useSettingPage } from '../context';

const { confirm } = Modal;

const { Group } = Checkbox;

const StyledDiv = styled.div`
  color: #161e35;
  font-weight: 500;
  font-size: 18px;
  line-height: 21px;
  align-items: center;
  p {
    font-weight: 400;
    font-size: 14px;
    line-height: 16px;
    color: #5b6d89;
    margin-top: 10px;
    font-style: normal;
  }
`;
const CircleButton = styled(Button)`
  margin: 0 8px;
  color: #5d97ff;
  border-color: #dee8ff;
  height: 41px;
  width: 42px;
}
  svg {
    margin: 2px 6px;
  }
`;
const ModalWrap = styled(Modal)`
  .ant-modal-content {
    border-radius: 8px;
    padding: 12px;
    width: 415px;
  }
  .ant-modal-footer {
    border-top: none;
    padding: 0;
  }
`;

const StyledButton = styled(Button)`
  padding: 10px 48px;
  height: 47px;
  margin-left: 30px;
  border-radius: 4px;
  font-weight: 400;
  font-size: 16px;
`;
const DeleteButton = styled(Button)`
  border: 1px solid #5d97ff;
  width: 200px;
  border-radius: 4px;
  color: #5d97ff;
  font-size: 12px;
  font-weight: 400;
  height: 36px;
  display: flex;
  align-items: center;
  svg {
    margin: 4px 6px;
  }
`;

const StyledCheckBoxGroup = styled(Group)`
  padding: 8px 0;
  display: inline-grid;
  max-width: 200px;
  overflow-y: auto;
  .ant-checkbox-group-item {
    padding: 4px 0px;
  }
`;

const StyledModalTitle = styled.div`
  color: #161e35;
  font-weight: 500;
  font-size: 18px;
  margin-top: 12px;
`;
const StyledModalSubTitle = styled.div`
  color: #5b6d89;
  font-weight: 400;
  font-size: 14px;
  margin-bottom: 12px;
`;
const ButtonFooter = styled.div`
  display: flex;
  justify-content: flex-end;
`;

const TeammateDeleteButton = (props) => {
  const dispatch = useDispatch();
  const {
    name,
    email,
    totalSelectedMember,
    type,
    selectedTeamList,
    currentAppList,
    accessApps,
    accessLevel,
  } = props;
  const queryClient = useQueryClient();
  const { setSelectedTeamList } = useSettingPage();

  const [visible, setVisible] = useState(false);
  const [selectedApp, setSelectedApp] = useState([]);

  const onChange = (checkedValues) => {
    setSelectedApp(checkedValues);
  };
  const {
    currentOrgReducer: { orgId },
  } = useSelector((state) => state);

  const accessApplist = useMemo(
    () =>
      currentAppList &&
      currentAppList.map((app) => {
        if (
          app?.role === 'admin' &&
          accessApps?.length &&
          accessApps?.some((obj) => obj?.id === app?.id)
        ) {
          const temp = { label: app?.name, value: app?.id };
          return temp;
        }
      }),
    [currentAppList]
  );

  const checkboxOption =
    accessApplist && accessApplist.filter((app) => app?.label);

  const teamQueryKey = useMemo(() => `teamList${orgId}`, [orgId]);

  const { mutate: deleteTeamMember } = useMutation(
    (payload) => SettingApi.deleteTeammates(payload),
    {
      onSuccess: () => {
        const successMessage = totalSelectedMember
          ? `${totalSelectedMember} teammate${totalSelectedMember ? 's' : ''}`
          : `${name || email || 'Teammate'}`;
        setSelectedTeamList([]);
        message.success(`${successMessage} deleted successfully.`);
        if (email) {
          dispatch(
            fetchPlanHatApi({
              action: `Teammate deleted on setting page`,
              info: {
                page: 'setting',
                data: {
                  level: accessLevel?.toLowerCase(),
                  deletedMemberName: name || '',
                  deletedMemberEmail: email,
                },
              },
            })
          );
        }
        !email &&
          selectedTeamList?.length > 0 &&
          selectedTeamList.map((teammate) =>
            dispatch(
              fetchPlanHatApi({
                action: `Teammate deleted on setting page`,
                info: {
                  page: 'setting',
                  data: {
                    level: teammate?.accessLevel,
                    deletedMemberName: teammate?.name || '',
                    deletedMemberEmail: teammate?.email,
                  },
                },
              })
            )
          );

        queryClient.invalidateQueries(teamQueryKey);
      },
    }
  );

  const singleDisplay = useMemo(
    () => (
      <StyledDiv>
        {`Remove ${name || email}?`}
        <p>The person will lose access to all apps.</p>
      </StyledDiv>
    ),
    [name, email]
  );

  const displayMessage = (
    <StyledDiv>
      {`Remove ${totalSelectedMember} user${
        totalSelectedMember > 1 ? 's' : ''
      }?`}
      <p>{`The removed ${totalSelectedMember} user${
        totalSelectedMember > 1 ? 's' : ''
      } will loose access to all apps.`}</p>
    </StyledDiv>
  );

  const selectedTeammates =
    selectedTeamList?.length &&
    selectedTeamList.map((teammate) => teammate?.email);
  const emailList = email ? [email] : selectedTeammates;

  const confirmDeleteUser = () => {
    confirm({
      title: '',
      content: type === 'multiple' ? displayMessage : singleDisplay,
      okText: 'Remove',
      okType: 'primary',
      cancelText: 'Cancel',
      icon: <></>,
      className: 'teammates-remove-box',
      onOk() {
        deleteTeamMember({
          data: {
            emails: emailList,
          },
          orgId,
        });
      },
    });
  };

  const buttonMessage = `Remove ${totalSelectedMember} user${
    totalSelectedMember > 1 ? 's' : ''
  }`;
  const handleCancel = () => setVisible(false);

  const handleModalClose = () => {
    setSelectedApp([]);
  };

  return (
    <>
      {email ? (
        <CircleButton
          shape="circle"
          icon={<DeleteIconSvg />}
          onClick={() =>
            accessLevel === 'Application'
              ? setVisible(true)
              : confirmDeleteUser()
          }
        />
      ) : (
        <DeleteButton
          onClick={() => confirmDeleteUser()}
          icon={<DeleteIconSvg />}
        >
          {buttonMessage}
        </DeleteButton>
      )}
      <ModalWrap
        title=""
        visible={visible}
        onCancel={handleCancel}
        destroyOnClose={handleModalClose}
        footer={[null]}
        closable={false}
      >
        <StyledModalTitle>{`Remove ${name || email}?`}</StyledModalTitle>
        <StyledModalSubTitle>
          Select apps to remove this user from.
        </StyledModalSubTitle>

        <StyledCheckBoxGroup options={checkboxOption} onChange={onChange} />

        <ButtonFooter>
          <StyledButton onClick={() => setVisible(false)}>Cancel</StyledButton>
          <StyledButton
            type='primary'
            danger
            disabled={!selectedApp?.length}
            onClick={() =>
              deleteTeamMember({
                data: {
                  emails: emailList,
                  apps: selectedApp,
                },
                orgId,
              })
            }
          >
            Remove
          </StyledButton>
        </ButtonFooter>
      </ModalWrap>
    </>
  );
};

export default TeammateDeleteButton;
