/* eslint-disable no-nested-ternary */
import React, {useState, useMemo, useEffect } from 'react';
import SubscriptionApi from 'services/subscriptionApi';
import { Button, Table, Tag, Modal } from 'antd';
import { useQuery } from 'react-query';
import { useSelector } from 'react-redux';
import styled from 'styled-components';
import { theme } from 'theme';

import NewInvoice from './NewInvoice';

const PaymentTableWrapper = styled.div`
  border: 1px solid #c0cad9;
  border-radius: 5px;
  padding: 20px 20px 0 20px;

  .ant-table-thead > tr > th {
    background: none;
    &::before {
      display: none;
    }
  }
  .ant-table-thead > tr > th,
  .ant-table-tbody > tr > td,
  .ant-table tfoot > tr > th,
  .ant-table tfoot > tr > td {
    padding: 10px 0;
  }

  .ant-table-pagination.ant-pagination {
    font-size: 14px;
    .ant-pagination-item {
      min-width: 25px;
      height: 25px;
      text-align: center;
      background: #fff;
      line-height: 23px;
      a {
        color: #161e35;
      }
    }
    .ant-pagination-item:focus a {
      color: #868ea1 !important;
  }
  }
  .ant-pagination-item-active {
    border-color: #5d97ff !important;
    a {
      color: #5d97ff !important;
    }
  }

  .ant-pagination-item-link {
    border: 0;
    font-size: 13px;
  }
`;

const PaymentTableHeader = styled.h3`
  font-size: ${ theme.fontSize( 1.8 ) };
  line-height: ${ theme.fontSize( 2.8 ) };
  color: ${ theme.colors.primaryMidnight.toString() };
  font-weight: 500;
  white-space: wrap;
`;

const ViewButton = styled(Button)`
  color: #5d97ff !important;
  border-color: #5d97ff !important;
  border-radius: 4px;
  font-size: 12px;
  padding: 6px 8px;
  width: 120px;
`;

const TagText = styled(Tag)`
  color: ${({ status }) => (status === 'Paid' ? '#00C58C' : '#F4584C')};
  background: rgba(0, 197, 140, 0.05);
  height: 25px;
  width: fit-content;
  display: flex;
  align-items: center;
`;

const PaymentTable = () => {
  const {
    currentOrgReducer: { orgId },
  } = useSelector((state) => state);
  const [invoiceModal, setInvoiceModal] = useState(false);
  const [invoiceId, setInvoiceId] = useState();
  const [invoiceData, setInvoiceData] = useState({});
  // const queryClient = useQueryClient();

  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 4,
    position: ['bottomCenter'],
  });

  const queryKey = useMemo(
    () => [`payhistory ${orgId}`, pagination?.current],
    [orgId, pagination]
  );
  const invoiceQueryKey = useMemo(
    () => `invoice ${orgId} ${invoiceId}`,
    [orgId, invoiceId]
  );

  const downloadInvoiceQueryKey = useMemo(
    () => `downloadInvoice ${orgId} ${invoiceId}`,
    [orgId, invoiceId]
  );

  const {
    data,
    isLoading: payHistoryLoading,
  } = useQuery(queryKey, () => SubscriptionApi.getPaymentHistory(orgId, pagination?.current));
  const { paymentHistory, pagination: responsePagination } = data?.data?.data || {};

  const newPagination = useMemo(()=> responsePagination &&  ({
    current:responsePagination?.current,
    pageSize: responsePagination?.limit,
    total: responsePagination?.total,
    position: ['bottomCenter'],
  }), [responsePagination])

  // const currentSubscriptionKey = useMemo(
  //   () => `currentSubscription${orgId}`,
  //   [orgId]
  // );
  // // const currentSubscription = queryClient.getQueryData(currentSubscriptionKey);

  const {
    data: downloadableInvoice,
    isLoading: idInvoiceDownload,
    error,
  } = useQuery(
    downloadInvoiceQueryKey,
    () => SubscriptionApi.getDownloadableInvoice(orgId, invoiceId),
    {
      enabled: !!invoiceId,
      retry: false,
    }
  );

  const { data: response, isLoading: loader } = useQuery(
    invoiceQueryKey,
    () =>
      invoiceId && SubscriptionApi.getInvoice(orgId, invoiceId),
    {
      enabled: error?.response?.status === 404,
      retry: false,
    }
  );

  const handleInvoice = () => {
    setInvoiceId(null);
    setInvoiceModal(!invoiceModal);
  }
  const cancelInvoice = () => {
    setInvoiceId(null);
    setInvoiceModal(false);
  }

  const showInvoice = (id) => {
    setInvoiceId(id);
  };

  const columns = [
    {
      title: 'Date',
      key: 'date',
      dataIndex: 'date',
    },
    {
      title: 'Amount',
      key: 'amount',
      dataIndex: 'amount',
      render: (text) => <span>{`USD $${text}`}</span>,
    },
    {
      title: '',
      key: 'status',
      dataIndex: 'status',
      render: (text) => (
        <TagText status={text}>
          {text}
        </TagText>
      ),
    },
    {
      title: '',
      key: 'action',
      render: (record) => (
            <ViewButton
              ghost
              loading={idInvoiceDownload && (invoiceId === record?.id || invoiceId === record?.transactionId)}
              onClick={(e) => { 
                e.stopPropagation();
                e.preventDefault();
                showInvoice(record?.id)
              }}
            >
              Download
            </ViewButton>
          )
    },
  ];

  const handleTableChange = ({ current }) => {
    setPagination({
      ...pagination,
      current,
    });
  };

  useEffect(()=>{
    newPagination && setPagination(newPagination) 
  }, [newPagination])

  useEffect(() => {
    error?.response?.status === 404 && setInvoiceModal(true);
    setInvoiceData(response?.data?.data);
  }, [error?.response?.status, response?.data?.data]);


  useEffect(() => {
    downloadableInvoice && window.open(downloadableInvoice?.data?.data.pdf, '_blank', 'noopener,noreferrer');
  }, [downloadableInvoice]);

  return (
    <PaymentTableWrapper>
      <PaymentTableHeader>Billing history</PaymentTableHeader>
      <Table
        rowKey={(record)=>record?.id}
        columns={columns}
        dataSource={paymentHistory}
        pagination={pagination}
        onChange={handleTableChange}
        loading={payHistoryLoading}
      />
      <Modal
        title=""
        visible={invoiceModal}
        onOk={handleInvoice}
        width={700}
        footer={null}
        onCancel={cancelInvoice}
      >
        <NewInvoice invoiceReceipt={invoiceData} loading={loader} />
      </Modal>
    </PaymentTableWrapper>
  );
};

export default PaymentTable;
