import React from 'react'
import { useFormContext } from 'react-hook-form'
import styled from 'styled-components';
import { theme } from 'theme';
import { Button, UFCInput } from 'uxcam-frontend-components';
import ChevronDown from 'public/static/page-definition/chevron-down.svg';
import SuccessIcon from 'public/static/page-definition/success.svg';
import ErrorIcon from 'public/static/page-definition/error.svg';
import { useDispatch } from 'react-redux';
import { trackPageViews } from 'redux/actions/trackingReport';
import { PageRuleFormProps } from '../RuleBuilder';
import { processPatternToMatch } from '../utils';

const Container = styled.div`
	display: flex;
	flex-direction: column;
	border: 1px solid ${ theme.colors.surface10.toString() };
	border-radius: 4px;
	padding: ${ theme.spacing( 1, 1.25 ) };
	gap: ${ theme.spacing( 1.25 ) };
`

const Title = styled.div`
	font-size: ${ theme.fontSize( 1.2 ) };
	font-weight: 500;
	line-height: ${ theme.fontSize( 1.4 ) };
	color: ${ theme.colors.surface500.toString() };
`

const Content = styled.div`
	display: none;
	flex-direction: column;
	gap: ${ theme.spacing( 1.25 ) };
	&[data-open="true"] {
		display: flex;
	}
`

const Header = styled.div`
	display: flex;
	gap: ${ theme.spacing( 2 ) };
	justify-content: space-between;
	align-items: center;
	cursor: pointer;
	i {
		transform: rotate(180deg);
		transition: transform 0.3s;
	}
	&[data-open="true"] {
		i {
			transform: rotate(0deg);
		}
	}
`

const P = styled.p`
	margin: 0;
	font-size: ${ theme.fontSize( 1 ) };
	line-height: ${ theme.fontSize( 1.6 ) };
	color: ${ theme.colors.surface400.toString() };
`

const ResultLabel = styled.div`
	display: flex;
	gap: ${ theme.spacing( 1.25 ) };
	align-items: center;
	font-size: ${ theme.fontSize( 1 ) };
	line-height: ${ theme.fontSize( 1.2 ) };
	color: ${ theme.colors.surface300.toString() };
`

const InputContainer = styled.div`
	display: flex;
	align-items: center;
	gap: ${ theme.spacing( 1.25 ) };
`

const StyledButton = styled(Button)`
	&[data-size="large"] {
		height: 28px;
		width: 86px;
		min-width: 86px;
	}
`

const RuleTester = ({
	isEdit
}:{
	isEdit: boolean
}) => {

	const [ result, setResult ] = React.useState<'success' | 'error' | 'invalidUrl' >()
	const { watch } = useFormContext<PageRuleFormProps>()
	const pattern = watch( 'pattern' )

	const [ url, setUrl ] = React.useState( '' )
	
	const urlRef = React.useRef( url )
	React.useEffect( () => {
		urlRef.current = url
	}, [ url ] )

	const [ open, setOpen ] = React.useState( false )

	React.useEffect( () => {
		if ( !pattern ) {
			setOpen( false )
		}
	}, [ pattern ] )

	const handleInputChange = React.useCallback( ( e: React.ChangeEvent<HTMLInputElement> ) => {
		setUrl( e.target.value )
	}, [] )

	const handleHeaderClick = React.useCallback( () => {
		// eslint-disable-next-line no-shadow
		setOpen( ( open ) => !open )
	}, [] )
	const dispatch = useDispatch()

	const handleTest = React.useCallback( () => {
		dispatch(trackPageViews(null, {
					eventName: 'wa_page_definitions_test_rule',
					track_type: 'event',
					eventProperty: {
						position: isEdit ? 'edit_rule_modal' : 'create_rule_modal',
					}
		}))
		if ( !urlRef.current ) {
			return setResult( 'invalidUrl' )
		}
		try {
			// eslint-disable-next-line no-new
			new URL( urlRef.current )

			const compiledPattern = processPatternToMatch( pattern )

			if ( compiledPattern( urlRef.current ) ) {
				return setResult( 'success' )
			}

			return setResult( 'error' )


		} catch ( e ) {
			return setResult( 'invalidUrl' )
		}
	}, [ dispatch, isEdit, pattern ] )


	return (
		<Container>
			<Header
				data-open={ open }
				onClick={ handleHeaderClick }
			>
				<Title>Test rules (optional)</Title>
				<i>
					<ChevronDown />
				</i>
			</Header>
			<Content
				data-open={ open }
			>
				<P>
					Enter a URL to evaluate against the rules. The results will indicate if the URL matches or not. You can test as many URLs as you want.
				</P>
				<InputContainer>
					<UFCInput
						onChange={ handleInputChange }
						value={ url }
						placeholder="Enter URL to evaluate against rules"
					/>
					<StyledButton
						variant="secondary"
						type="button"
						size="large"
						inline
						onClick={ handleTest }
					>
						Test
					</StyledButton>
				</InputContainer>
				{
					result === 'invalidUrl' ? (
						<ResultLabel>
							<ErrorIcon />
							Invalid URL. Please enter a valid URL.
						</ResultLabel>
					) : null
				}
				{
					result === 'error' ? (
						<ResultLabel>
							<ErrorIcon />
							This URL does not match your rule. It will not be grouped under this page name.
						</ResultLabel>
					) : null
				}
				{
					result === 'success' ? (
						<ResultLabel>
							<SuccessIcon />
							This URL matches your rule. It will be grouped under this page name.
						</ResultLabel>
					) : null
				}
			</Content>
		</Container>
	)

}

export default React.memo( RuleTester );