import React from 'react'
import styled from 'styled-components'
import { theme } from 'theme'
import { UFC_Dropdown as Dropdown, DropdownOverlay } from 'uxcam-frontend-components'
import CheckCircle from 'public/static/page-definition/check-circle.svg'

const PathItemButton = styled.button`
	appearance: none;
	background: none;
	display: flex;
	border-radius: 6px;
	align-items: center;
	position: relative;
	border: 1px solid ${ theme.colors.surface10.toString() };
	padding: ${ theme.spacing( 0.25, 1 ) };
	white-space: break-spaces;
	min-height: 28px;
	white-space: nowrap;
	font-weight: 400;
	font-size: ${ theme.fontSize( 1.2 ) };
	color: ${ theme.colors.surface300.toString() };
	cursor: pointer;
	transition: background-color 0.2s;
	&:after {
		content: attr(data-separator);
		display: flex;
		align-items: center;
		justify-content: center;
		position: absolute;
		left: 100%;
		top: 0;
		width: ${ theme.spacing( 3 ) };
		font-size: ${ theme.fontSize( 2.4 ) };
		color: ${ theme.colors.surface10.toString() };
		height: 100%;
	}
	&[data-is-last="true"]:after {
		content: none;
	}
	&[data-separator*="#"] {
		margin-right: ${ theme.spacing( 2 ) };
	}
	&[data-separator*="#"]:after {
		width: ${ theme.spacing( 5 ) };
	}
	&[data-selected='true'] {
		background: ${ theme.colors.primary10.toString() };
		border-color: ${ theme.colors.primary10.toString() };
	}
	&:disabled {
		pointer-events: none;
		background: ${ theme.colors.surface10.toString() };
	}
`

const Separator = styled.div`
	width: 100%;
	height: 1px;
	background: ${ theme.colors.surface10.toString() };
`

const Placeholder = styled.div`
	font-size: ${ theme.fontSize( 1.2 ) };
	line-height: ${ theme.fontSize( 2.4 ) };
	color: ${ theme.colors.surface200.toString() };
`

const SearchInput = styled.input`
	appearance: none;
	border: none;
	background: #F3F4F5;
	border-radius: 6px;
	font-size: ${ theme.fontSize( 1.2 ) };
	height: 24px;
	padding: ${ theme.spacing( 0.25, 1 ) };
	width: 100%;
`

const DropdownContent = styled.div`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 1.25 ) };
	width: 326px;
`

const CreateLabel = styled.div`
	flex-wrap: wrap;
	font-size: ${ theme.fontSize( 1.2 ) };
	line-height: ${ theme.fontSize( 2.4 ) };
	i {
		font-size: ${ theme.fontSize( 1 ) };
		font-style: normal;
		color: ${ theme.colors.surface200.toString() };
	}
	b {
		font-weight: 700;
	}
`

const ResultItem = styled.button`
	display: flex;
	gap: ${ theme.spacing( 1 ) };
	align-items: center;
	justify-content: space-between;
	border: none;
	background: transparent;
	border-radius: 6px;
	padding: ${ theme.spacing( 0.25, 1 ) };
	font-size: ${ theme.fontSize( 1.2 ) };
	color: ${ theme.colors.surface500.toString() };
	font-weight: 400;
	cursor: pointer;
	&:hover {
		background: ${ theme.colors.primary05.toString() };
	}
	&[aria-selected='true'] {
		background: ${ theme.colors.primary05.toString() };
	}
`

const ResultList = styled.div`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 0.5 ) };
`

const WildCardLabel = styled.label`
	display: flex;
	gap: ${ theme.spacing( 0.5 ) };
	font-size: ${ theme.fontSize( 1.2 ) };
	color: ${ theme.colors.surface500.toString() };
	align-items: center;
	cursor: pointer;
	input {
		display: none;
	}
	&[aria-disabled='true'] {
		color: ${ theme.colors.surface200.toString() };
		pointer-events: none;
	}
	span:before {
		content: '';
		display: flex;
		width: 14px;
		height: 14px;
		border-radius: 50%;
		border: 1px solid ${ theme.colors.surface200.toString() };
	}
	input:checked + span:before {
		border-color: ${ theme.colors.primary500.toString() };
		border-width: 4px;
	}
`

const PathItem: React.FC<{
	getPopupContainer: () => HTMLElement,
	disabled: boolean,
	isHash: boolean,
	patternPart: string,
	part: string,
	index: number,
	handlePartChange: ( index: number, newValue?: string ) => void,
	allParameters: string[],
	isLast: boolean,
	separator: string,
}> = ( {
	getPopupContainer,
	disabled,
	isHash,
	patternPart: rawPatternPart,
	part,
	index,
	handlePartChange,
	allParameters,
	isLast,
	separator,
} ) => {

	const patternPart = React.useMemo( () => {
		return rawPatternPart.replace( /:/g, '' )
	}, [ rawPatternPart ] )

	const selected = React.useMemo( () => {
		return rawPatternPart === '*' || rawPatternPart.startsWith( ':' ) || rawPatternPart === '***'
	}, [ rawPatternPart ] )

	const isAsterisk = patternPart === '*' || rawPatternPart === '***'

	const [ inputValue, setInputValue ] = React.useState( '' )
	const [ visible, setVisible ] = React.useState( false )

	React.useEffect( () => {
		setInputValue( '' )
	}, [ visible ] )

	const handleInputChange = React.useCallback( ( event: React.ChangeEvent<HTMLInputElement> ) => {
		setInputValue( event.target.value.replace( /[^a-zA-Z0-9]/g, '' ) )
	}, [] )

	const displayResults = React.useMemo( () => {
		const lower = inputValue.toLowerCase()
		return lower.trim() ? allParameters.filter( rule => rule.toLowerCase().includes( lower ) ) : []
	}, [ inputValue, allParameters ] )

	const displayCurrent = React.useMemo( () => {
		return !inputValue.trim() && rawPatternPart.startsWith( ':' ) && !displayResults.length
	}, [ inputValue, rawPatternPart, displayResults ] )


	const handleUseAsterisk = React.useCallback( ( e: React.ChangeEvent<HTMLInputElement> ) => {
		if ( e.target.checked ) {
			handlePartChange( index, '*' )
			setVisible( false )
			return
		}
		handlePartChange( index )
	}, [ handlePartChange, index ] )

	const handleKeyDown = React.useCallback( ( e: React.KeyboardEvent<HTMLInputElement> ) => {
		const newValue = e.currentTarget.value.replace( /[^a-zA-Z0-9]/g, '' )
		if ( !newValue ) {
			return
		}
		if ( e.key === 'Enter' ) {
			e.preventDefault()
			e.currentTarget.value = ''
			handlePartChange( index, `:${ newValue }` )
		}
	}, [ handlePartChange, index ] )

	const displayCreate = React.useMemo( () => {
		return inputValue.trim() && allParameters.every( rule => rule !== inputValue )
	}, [ inputValue, allParameters ] )

	const wildcardDisabled = React.useMemo( () => {
		return !!inputValue.trim()
	}, [ inputValue ] )

	return (
		<Dropdown
			destroyPopupOnHide
			onVisibleChange={ setVisible }
			visible={ visible }
			placement="bottomCenter"
			trigger={ ['click'] }
			getPopupContainer={ getPopupContainer }
			overlay={ (
				<DropdownOverlay>
					<DropdownContent>
						<SearchInput
							type="text"
							disabled={ isAsterisk }
							value={ inputValue }
							onChange={ handleInputChange }
							placeholder="Type to create"
							onKeyDown={ handleKeyDown }
						/>
						{
							displayResults.length || displayCurrent ? (
								<ResultList>
									{ displayResults.map( ( result, ruleIndex ) => {
										const selected = result === patternPart
										return (
											<ResultItem
												aria-selected={ selected }
												key={ ruleIndex }
												onClick={ () => handlePartChange( index, `:${ result }` ) }
												type="button"
											>
												{ result }
												{
													selected ? (
														<CheckCircle />
													) : null
												}
											</ResultItem>
										)
									} ) }
									{ displayCurrent ? (
										<ResultItem
											aria-selected
											onClick={ () => handlePartChange( index ) }
											type="button"
										>
											{ patternPart }
											<CheckCircle />
										</ResultItem>
									) : null }
								</ResultList>
							) : null
						}
						{
							!allParameters.length && !inputValue ? (
								<Placeholder>
									You haven’t created any parameter yet.
									<br />
									Enter a name to save and reuse later (e.g. productID).
								</Placeholder>
							) : null
						}
						{
							!inputValue && !selected ? (
								<Placeholder>
									Start typing to create a new parameter or find one you’ve already saved (e.g., productID).
								</Placeholder>
							) : null
						}
						{
							displayCreate ? (
								<CreateLabel>
									Create parameter <b>“{ inputValue }”</b> <i>Press enter</i>
								</CreateLabel>
							) : null
						}
						<Separator />
						<WildCardLabel
							aria-disabled={ wildcardDisabled }
						>
							<input
								type="checkbox"
								checked={ isAsterisk }
								onChange={ handleUseAsterisk }
							/>
							<span />
							Use a wildcard (*) instead of naming this parameter
						</WildCardLabel>
					</DropdownContent>
				</DropdownOverlay>
			) }
		>
			<PathItemButton
				// eslint-disable-next-line react/no-array-index-key
				type="button"
				data-selected={ selected }
				disabled={ disabled }
				data-is-hash={ isHash }
				data-is-last={ isLast }
				data-separator={ separator }
			>
				{ part }
			</PathItemButton>
		</Dropdown>
	)
}

export default React.memo( PathItem )
