import { useRouter } from 'next/router'
import React from 'react'

interface IPageDefinitionNavContext {
	getEditLink: ( id: string ) => {
		href: {
			pathname: string;
			query: Record<string, string>;
		};
		asUrl: string;
	},
	handleArchiveRule: ( id: string, name: string ) => () => void;
	status: 'active' | 'archive';
	isManager: boolean;
}

const PageDefinitionNavContext = React.createContext<IPageDefinitionNavContext>( {
	getEditLink: () => {
		return {
			href: {
				pathname: '',
				query: {},
			},
			asUrl: '',
		}
	},
	handleArchiveRule: () => () => null,
	status: 'active',
	isManager: false,
} )

export const PageDefinitionNavContextProvider: React.FC<{
	children: React.ReactNode;
	status: 'active' | 'archive';
	isManager: boolean;
	onArchive: React.Dispatch<React.SetStateAction<{ id: string; name: string } | null | undefined>>;
}> = React.memo( ( {
	children,
	status,
	onArchive,
	isManager,
} ) => {

	const {
		pathname,
		query,
	} = useRouter()

	const getEditLink = React.useCallback( ( id: string ) => {
		const orgId = query.org as string
		const appId = query.app as string
		const asUrl = `settings/app/${ orgId }/${ appId }/page_definition?rule_id=${ id }#rule-builder`

		const href = {
			pathname,
			query: {
				...query,
				rule_id: id,
			},
		}

		return {
			asUrl,
			href,
		}
	}, [ pathname, query ] )

	const handleArchiveRule = React.useCallback( ( id: string, name: string ) => {
		return () => {
			onArchive( {
				id,
				name,
			} )
		}
	}, [ onArchive ] )

	const contextValue = React.useMemo( () => {
		return {
			getEditLink,
			handleArchiveRule,
			status,
			isManager
		}
	}, [ getEditLink, handleArchiveRule, status, isManager ] )

	return (
		<PageDefinitionNavContext.Provider value={ contextValue }>
			{ children }
		</PageDefinitionNavContext.Provider>
	)
} )

export const usePageDefinitionNavContext = () => {
	return React.useContext( PageDefinitionNavContext )
}