/* eslint-disable no-shadow */
/* eslint-disable react/no-array-index-key */
import { Modal } from 'antd';
import { useRouter } from 'next/router';
import React from 'react'
import { useQuery } from 'react-query';
import styled from 'styled-components';
import { theme } from 'theme';
import { Button } from 'uxcam-frontend-components';
import { displayPattern } from './utils';

interface IChangelog {
	_id: string;
	appId: string;
	pageDefinitionSettingId: string;
	originalUrl: string;
	patternUrl: string;
	pageName: string;
	isArchived: boolean;
	actionPerformed: string;
	actionBy: string;
	actionByEmail: string;
	patternUrlOld: string | null;
	pageNameOld: string | null;
	actionOn: string;
}

const ModalHeaderWrap = styled.div`
  display: flex;
  justify-content: space-between;
`;

const TextTitle = styled.div`
  font-size: 18px;
  font-weight: 500;
`;

const Content = styled.div`
	background: ${ theme.colors.surface05.toString() };
	padding: ${ theme.spacing( 1.5 ) };
	margin: ${ theme.spacing( 2, 0, 4 ) };
`

const ChangelogContainer = styled.div`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 1 ) };
`

const UL = styled.ul`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 1 ) };
	padding: ${ theme.spacing( 0, 0, 0, 4 ) };
	> li {
		position: relative;
		line-height: ${ theme.fontSize( 1.4 ) };
		font-size: ${ theme.fontSize( 1.2 ) };
		&:before {
			content: '';
			position: absolute;
			top: 50%;
			left: ${ theme.spacing( -2 ) };
			width: 4px;
			height: 4px;
			background: ${ theme.colors.surface300.toString() };
			border-radius: 50%;
			transform: translateY( -50% );
		}
	}
`

const DateContainer = styled.div`
	display: flex;
	font-size: ${ theme.fontSize( 1.2 ) };
	position: relative;
	&:before {
		content: '';
		position: absolute;
		width: 8px;
		height: 8px;
		background: ${ theme.colors.surface200.toString() };
		border-radius: 50%;
		top: 50%;
		transform: translateY( -50% );
		left: -14px;
	}
`

const Inner = styled.div`
	display: flex;
	flex-direction: column;
	position: relative;
	padding: ${ theme.spacing( 0, 0, 0, 1.75 ) };
	max-height: 396px;
	overflow-y: auto;
`

const InnerWrapper = styled.div`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 3 ) };
	position: relative;
	color: ${ theme.colors.surface300.toString() };
	&:before {
		content: '';
		position: absolute;
		top: 6px;
		left: -11px;
		width: 2px;
		height: calc( 100% - 6px );
		background: ${ theme.colors.surface10.toString() };
	}
`

const ChangesContainer = styled.div`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 1 ) };
	padding: ${ theme.spacing( 1.5, 0 ) };
	border-top: 1px solid ${ theme.colors.surface10.toString() };
	&:first-child {
		padding-top: 0;
		border-top: none;
	}
`

const ModalWrap = styled(Modal)`
	.ant-modal-body {
		padding: ${ theme.spacing( 4 ) };
	}
	.ant-modal-content {
		border-radius: 8px;
	}
	.ant-modal-footer {
		border-top: none;
		padding: 0;
	}
`;

const Footer = styled.div`
	display: flex;
	justify-content: flex-end;
`

const Changelog: React.FC<{
	open: boolean;
	onClose: () => void;
}> = ( {
	open,
	onClose,
} ) => {

	const { query } = useRouter();

	const fetchFn = React.useCallback( () => {
		const { app } = query;
		return fetch( `${ process.env.SUBSCRIPTION_URL }/app/${ app }/page-definition-setting/logs/`, {
			credentials: 'include',
		} )
			.then( ( res ) => res.json() as Promise<{
				success: boolean;
				message: string;
				data: IChangelog[]
			}> )
	}, [ query ] );

	const result = useQuery( 'changelog', {
		queryFn: fetchFn,
		suspense: true,
		staleTime: Infinity,
	} );

	// trigger a refetch when the modal is opened
	React.useEffect( () => {
		if ( open ) {
			result.refetch();
		}
	}, [ open, result ] );

	// group results into a map with actionOn as key
	const groupedData = React.useMemo( () => {
		const data = result.data?.data || [];
		const grouped = data.reduce( ( acc, item ) => {
			const key = new Date( item.actionOn ).toLocaleString( 'en-US', {
				year: 'numeric',
				month: 'short',
				day: 'numeric',
			} )
			if ( !acc[ key ] ) {
				acc[ key ] = [];
			}
			acc[ key ].push( item );
			return acc;
		}, {} as Record<string, IChangelog[]> );

		return Object.entries( grouped )
	}, [ result.data ] );

	const getChangeText = React.useCallback( ( action: string ) => {
		switch ( action ) {
			case 'created':
				return 'Created';
			case 'updated':
				return 'Updated';
			case 'archived':
				return 'Archived';
			default:
				return 'Unknown';
		}
	}, [] );

	return (
		<ModalWrap
			visible={ open }
			footer={ null }
			onCancel={ onClose }
			width={ 700 }
			centered
			closable={ false }
		>
			<ModalHeaderWrap>
				<TextTitle>Page definition Changelog</TextTitle>
			</ModalHeaderWrap>
			<Content>
				<Inner>
					<InnerWrapper>
					{
						groupedData.map( ( [ dateStr, changes ], index ) => {

							return (
								<ChangelogContainer key={ index }>
									<DateContainer>{ dateStr }</DateContainer>
									<div>
										{
											changes.map( ( change, index ) => {
												const isArchived = change.actionPerformed === 'archived';
												const isCreate = change.actionPerformed === 'created';
												const hasPatternChanged = !isArchived && change.patternUrlOld && change.patternUrlOld !== change.patternUrl;
												const hasPageNameChanged = !isArchived && change.pageNameOld && change.pageNameOld !== change.pageName;
												const showPattern = isCreate || isArchived
												const showPageName = isCreate || isArchived

												return (
													<ChangesContainer
														key={ index }
													>
														<div>
															{ getChangeText( change.actionPerformed ) } Page definition rule | { change.actionByEmail }
														</div>
														<UL>
															{
																showPattern ? (
																	<li>
																		Pattern: <b>{ displayPattern( change.patternUrl, false ) }</b>
																	</li>
																) : null
															}
															{
																hasPatternChanged ? (
																	<li>
																		Pattern changed from: <b>{ displayPattern( change.patternUrlOld!, false ) }</b> to <b>{ displayPattern( change.patternUrl, false ) }</b>
																	</li>
																) : null
															}
															{
																showPageName ? (
																	<li>
																		Page Name: <b>{ change.pageName }</b>
																	</li>
																) : null
															}
															{
																hasPageNameChanged ? (
																	<li>
																		Page Name changed from: <b>{ change.pageNameOld }</b> to <b>{ change.pageName }</b>
																	</li>
																) : null
															}
														</UL>
													</ChangesContainer>
												)

											} )
										}
									</div>
								</ChangelogContainer>
							)
						} )
					}
					</InnerWrapper>
				</Inner>
			</Content>
			<Footer>
				<Button
					type="button"
					variant="ghost"
					size="large"
					onClick={ onClose }
				>
					Close
				</Button>
			</Footer>
		</ModalWrap>
	)
}

export const ChangelogLoader: React.FC<{
	open: boolean;
	onClose: () => void;
}> = React.memo( ( {
	open,
	onClose,
} ) => {

	return (
		<React.Suspense fallback={ null }>
			<Changelog
				open={ open }
				onClose={ onClose }
			/>
		</React.Suspense>
	)
} )

export default React.memo( Changelog );