/* eslint-disable no-nested-ternary */
import React, { useCallback, useEffect, useMemo } from 'react';

import { useRouter } from 'next/router';
import styled from 'styled-components';
import { useSelector } from 'react-redux';
import { startOfDay, endOfDay, format } from 'date-fns';

import ReactLoader from 'components/common/reactLoading';

import {
  useFetchAppSetting,
  useFetchScreenName,
  useFetchRenameScreens,
  useFetchAndroidSDKVersion,
  useFetchIosSDKVersion,
} from 'components/features/setting/useSettingPage';
import { subtractMonths } from 'components/features/setting/commonUtils';

import { useFeatureFlag } from 'uxcam-frontend-components';
import NewSection from './RecordingForm';
import { useSessionRecordingCustomHooks } from './Hooks/SessionRecordingFilter';
import { handleIsOfOrNonOf, extraField } from './common/commonVariables';
import originalData from './common/ruleFileMenu.json';

export const StyledLoader = styled.div`
  inset: 0;
  margin: auto;
  position: absolute;
`;
const isoDateFormat = "yyyy-MM-dd'T'HH:mm:ss'Z'";

const AppSetting = () => {
  const urlQuery = useSelector((state) => state.urlReducer);
  const activeSubscription = useSelector((state) => state.currentOrgReducer);
  const { currentOrgReducer: {orgId} } = useSelector((state) => state);
  const router = useRouter();

  const dataRetentionMonths = activeSubscription?.planLimit?.dataRetentionTime;
  const fromDate = useMemo(() => {
    const currentDate = new Date();
    return format(
      startOfDay(subtractMonths(dataRetentionMonths, currentDate)),
      isoDateFormat
    );
  }, [dataRetentionMonths]);
  const toDate = format(endOfDay(new Date()), isoDateFormat);
  const dateRange = { from: fromDate, to: toDate };

  const appId = urlQuery?.app || urlQuery?.appId;

  const { setInitialSessionData, setInitialVideoData, setFilterData } =
    useSessionRecordingCustomHooks();

  const appSettingQueryKey = [`appSetting`, appId];
  // const screenQueryKey = useMemo(() =>['screen', appId], [appId]);
  const androidSDKQueryKey = useMemo(() => ['androidSDK', appId], [appId]);
  const iosSDKQueryKey = useMemo(() => ['iosSDK', appId], [appId]);

  const renameScreenQueryKey = useMemo(() => `rename-screen-${appId}`, [appId]);

  // const payloadForScreen = {
  //   attribute: 'session_screen_list',
  //   dateRange,
  //   dropdownLimit: 10000,
  //   table: 'session',
  //   search: '',
  //   appid: appId,
  // };

  const environmentEnabled = useFeatureFlag( 'app-setting-env' )

  const filteredOriginalData = useMemo(
    () =>
      environmentEnabled
        ? originalData
        : originalData.filter((data) => data?.attribute !== 'environment'),
    [environmentEnabled]
  );

  // const { refetch: fetchScreenList, data: screenName } = useFetchScreenName(
  //   screenQueryKey,
  //   payloadForScreen
  // );
  const { refetch: fetchRenameScreen, data: renameScreen } =
    useFetchRenameScreens(renameScreenQueryKey, appId);
  // const ruleUpdatedScreenName = useMemo(
  //   () =>
  //     screenName?.length
  //       ? screenName.map((screen) => ({
  //           key: screen?.value,
  //           val:
  //             renameScreen && renameScreen[screen?.label]
  //               ? renameScreen[screen?.label]
  //               : screen?.label,
  //         }))
  //       : [],
  //   [screenName, renameScreen]
  // );

  const dataField = {
    attribute: 'sdk_version',
    search: '',
    table: 'session',
    dropdownLimit: 501,
    appid: appId,
    dateRange,
    filter: [
      {
        attribute: 'device_platform',
        operator: 'equal',
        value: 1,
        table: 'session',
      },
    ],
  };
  const androidRequest = {
    ...dataField,
    filter: [
      {
        attribute: 'device_platform',
        operator: 'equal',
        value: 1,
        table: 'session',
      },
    ],
  };

  const iosRequest = {
    ...dataField,
    filter: [
      {
        attribute: 'device_platform',
        operator: 'equal',
        value: 2,
        table: 'session',
      },
    ],
  };

  const { data: androidSDK, refetch: fetchIosSDKVersion } =
   useFetchAndroidSDKVersion(androidSDKQueryKey, androidRequest);
  const { data: iosSDK, refetch: fetchAndroidSDKVersion } =
  useFetchIosSDKVersion(iosSDKQueryKey, iosRequest);
  const handleConcatArray = useCallback(() => {
    const firstData = iosSDK?.length ? iosSDK : [];
    const secondData = androidSDK?.length ? androidSDK : [];
    return [...firstData, ...secondData];
  }, [iosSDK, androidSDK]);

  const ruleSdkVersionList = useMemo(
    () => handleConcatArray(),
    [handleConcatArray]
  );

  const {
    data: recordingData,
    refetch: fetchSettingData,
    isLoading: recordingLoading,
  } = useFetchAppSetting(appSettingQueryKey, appId);

  if(recordingData?.status === 404) {
    router.push(`/error?errorStatus=${recordingData.status}&errorMessage=${
      recordingData.message
    }`)
  }

  const handleDataKeyFormat = useCallback(
    () =>
    filteredOriginalData.map((data) => ({
        ...data,
        key: extraField.includes(data?.attribute)
          ? `${data?.attribute}-${
              handleIsOfOrNonOf(data?.title) ? 'is' : 'isNot'
            }`
          : `${data?.attribute}`,
        possibleValue:
          data?.attribute === 'sdkVersion'
            ? ruleSdkVersionList
            : data?.attribute === 'screen'
            ? [] // ruleUpdatedScreenName removed to make select searchable
            : data?.possibleValue,
      })),
    [ruleSdkVersionList, filteredOriginalData]
  );

  const originalFilterDataKey = useMemo(
    () => handleDataKeyFormat(),
    [handleDataKeyFormat]
  );

  useEffect(() => {
    setFilterData(originalFilterDataKey);
  }, [originalFilterDataKey, setFilterData]);

  useEffect(() => {
    setInitialSessionData(recordingData?.filtersDataSession || []);
    setInitialVideoData(recordingData?.filter || []);
  }, [recordingData]);

  useEffect(() => {
    if (appId) {
      fetchRenameScreen();
      // fetchScreenList();
      fetchSettingData();
      fetchAndroidSDKVersion();
      fetchIosSDKVersion();
    }
  }, [appId]);

  return (
    <>
      {!recordingLoading && <NewSection />}
      {recordingLoading && (
        <StyledLoader>
          <ReactLoader />
        </StyledLoader>
      )}
    </>
  );
};

export default AppSetting;
