import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { Tabs, Breadcrumb } from 'antd';
import { useSelector, useDispatch } from 'react-redux';
import styled from 'styled-components';
import Router, { useRouter } from 'next/router';
import { theme } from 'theme';

import { settingTabToogle } from 'redux/actions/common';
import { apiPlanError } from 'Utils/constants/index';
import ProfileImageOrText from 'components/features/setting/ProfileImageOrText';
import BackToIntegratePage from 'components/shared/BackToIntegratePage';
import { trackPageViews } from 'redux/actions/trackingReport';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { trackOrgSettingScreenVisit } from 'components/features/aiSessions/components/utils';
import OrgProfile from './OrgProfileSection/OrgProfile';
import Subscription from './Subscription';
import TeamSection from './TeamSection';
import AppSection from './AppSection';
import TeamExtraContent from './TeamSection/TeamExtraContent';
import AppExtraContent from './AppSection/AppExtraContent';
import { SettingProvider, useSettingPage } from './context';
import SSOConfig from './SingleSignOn';
import {
  useFetchNewProfile,
  useFetchRolesAndPermission,
  useFetchAIUsageOverview,
} from '../useSettingPage';
import RoleBasedError from '../RoleBasedError';
import { authorizeOrgManagerPermission } from '../commonUtils';
import FilterAI from './FilterAi';
import TaraAI from './TaraAI';


const BreadcrumbItem = Breadcrumb.Item;

const { TabPane } = Tabs;

const SubscriptionView = ['subscription.view'];

const MainTab = styled.div`
  background: #ffffff;
  padding: 16px;
  min-height: calc(100% - 40px);
  .ant-tabs-extra-content{
    flex-basis: 50%;
  }
  .ant-tabs-nav {
    .ant-tabs-tab {
      margin-top: 12px !important;
      margin-bottom: 12px !important;
      margin-right: 40px !important;
      padding-left: 3px;
      padding-right: 0;
      color: #161e35;
    }
    .ant-tabs-tab-btn {
      font-weight: 400;
      font-size: 14px;
      line-height: 16px;
    }
  }
`;
const StyledMainHeaderPart = styled.div`
display: flex;
justify-content: space-between;
`;
const StyledBreadcrumbMain = styled(BreadcrumbItem)`
  color: #4f4f4f;
  font-weight: 500;
  font-size: 16px;
  display: inline-flex;
  line-height: 20px;
  white-space: pre-wrap;
  .ant-avatar {
    margin-right: 4px;
  }
`;

const StyledBreadcrumbItem = styled(BreadcrumbItem)`
  color: #333333;
  font-weight: 300;
  font-size: 16px;
  line-height: 20px;
`;

const BreadcrumbInfo = {
  plan: 'Manage subscription',
  team: 'Manage team',
  apps: 'Manage apps',
  'single-sign-on': 'Manage single sign on',
  profile: 'Organization profile',
  'ai-filter': 'UXCam AI',
  'tara-ai': 'Tara AI',
};

const NewPill = styled.div`
  height: 18px;
  padding: 0 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  background: #FFDC62;
  color: ${theme.colors.surface500.toString()};
  font-size: 12px;
`

const LabelContainer = styled.span`
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
`


const NewAppSetting = () => {
  const dispatch = useDispatch();
  const [selectedTab, setSelectedTab] = useState();
  const { setSearchAppName, setSearchValue } = useSettingPage();
  const enableAiFilter = useFeatureFlag('ai-filter');
  const restrictionContext = useRestrictionContext();
  const planFeatureAiSessions = !!restrictionContext?.planFeatureAiSessions;

  const router = useRouter();

  const {
    currentOrgReducer: { orgId, organizationName, organizationIcon, planFeature },
    ssoInfo: { ssoEnabled },
    currentAppReducer: {isIntegrated, _id: appId },
  } = useSelector((state) => state);

  const { data: aiUsageData } = useFetchAIUsageOverview(orgId, planFeatureAiSessions);

  const handleCallBack = (value) => {
    setSelectedTab(value);
    dispatch(settingTabToogle(value));
    setSearchValue();
    setSearchAppName();
    const orgUrlQuery = `org=${orgId}&parentType=settings&setting=org_setting&org_tab=${
      value || selectedTab
    }`;

    const orgUrl = `/settings/org/${orgId}/${value || selectedTab}`;

    Router.push(`/integration?${orgUrlQuery}`, `${orgUrl}`);
  };

  const separator = (
    <img src="/static/settings-new-icon/breadcrumb.svg" alt="" />
  );

  const routerQuery = router?.query;
  const { data: newProfile } = useFetchNewProfile(`profileInfo`);
  const { data: definedRoles, isLoading } =
    useFetchRolesAndPermission('roles_permission');

  const isAppIntegrated = useMemo(() => !isIntegrated, [isIntegrated])
  const isTaraEnabled = useMemo(() => planFeature?.tara, [planFeature?.tara])
  const AIFilterLabel = useMemo(() => (
    <LabelContainer>
      UXCam AI
      <NewPill>Beta</NewPill>
    </LabelContainer>
  ), [])

  const validatePermission = useCallback(
    (permissionCode) =>
      newProfile &&
      authorizeOrgManagerPermission(
        permissionCode,
        definedRoles,
        newProfile?.organization,
        orgId
      ),
    [newProfile, definedRoles, orgId]
  );

  useEffect(() => {
    setSelectedTab(routerQuery?.org_tab);
  }, [routerQuery]);

  useEffect(() => {
    if (selectedTab && newProfile) {
      const tabToFeatureMap = {
        'plan': 'subscription',
        'team': 'team',
        'tara-ai': 'tara-ai',
        'apps': 'apps',
        'single-sign-on': 'sso',
        'profile': 'profile',
      };

      const feature = tabToFeatureMap[selectedTab];
      if (!feature) return;

      const organizationRole = newProfile?.organization?.find(org => org.orgId === orgId)?.organizationRole;
      const isAdmin = organizationRole === 'owner' || organizationRole === 'manager';

      const autoAnalysisStatus = aiUsageData?.monthly_auto_analysis_tara_credit > 0;
      const customAnalysisStatus = aiUsageData?.monthly_tara_credit > 0;

      dispatch(trackOrgSettingScreenVisit({
        feature,
        isAdmin,
        autoAnalysisStatus,
        customAnalysisStatus,
      }))
    }
  }, [selectedTab, newProfile, orgId, aiUsageData, dispatch]);

  useEffect(() => {
    // Get the current URL
    const url = new URL(window.location.href);

    // Check if the "referer" query parameter is present
    if (url.searchParams.has('referer')) {
      // send event instrumentaion for invitaion accept
      dispatch(trackPageViews(null, {
        eventName: 'wa_invite_everyone_button_clicked',
        track_type: 'event',
      }));

      // Remove the "referer" parameter from the URL
      url.searchParams.delete('referer');

      // Replace the current URL without the "referer" parameter
      const newUrl = url.toString();
      window.history.replaceState({}, '', newUrl);
    }
  }, []);

  return (
    <SettingProvider>
      <MainTab>
        <StyledMainHeaderPart>
          <Breadcrumb separator={separator}>
            <StyledBreadcrumbMain>
              <ProfileImageOrText
                picture={organizationIcon}
                nameInfo={organizationName}
                size={16}
                shape="square"
              />
              {organizationName}
            </StyledBreadcrumbMain>
            <StyledBreadcrumbItem href="#">
              {`${BreadcrumbInfo[selectedTab]}`}
            </StyledBreadcrumbItem>
          </Breadcrumb>
          {isAppIntegrated && appId && <BackToIntegratePage />}
        </StyledMainHeaderPart>

        <Tabs
          activeKey={selectedTab}
          onChange={handleCallBack}
          tabBarExtraContent={
            selectedTab === 'team' ? (
              <TeamExtraContent />
            ) : (
              selectedTab === 'apps' && <AppExtraContent />
            )
          }
        >
          {validatePermission(SubscriptionView) && (
            <TabPane tab="Subscription" key="plan">
              <Subscription />
            </TabPane>
          )}

          {isTaraEnabled && (
            <TabPane tab="Tara AI" key="tara-ai">
              <TaraAI />
            </TabPane>
          )}

          <TabPane tab="Team" key="team">
            <TeamSection />
          </TabPane>
          <TabPane tab="Apps" key="apps">
              <AppSection />
          </TabPane>

          {validatePermission(['organization.update']) && (
            <TabPane tab="Single Sign On" key="single-sign-on">
              {ssoEnabled ? (
                <SSOConfig />
              ) : (
                <RoleBasedError message={apiPlanError} feature />
              )}
            </TabPane>
          )}

          {validatePermission(['organization.update', 'organization.view']) && (
            <TabPane tab="Profile" key="profile">
              <OrgProfile />
            </TabPane>
          )}

          {newProfile && !validatePermission(SubscriptionView) && !isLoading && (
            <TabPane key="plan">
              <RoleBasedError message="The Subscription page is only available to the organization owner and organization managers." />
            </TabPane>
          )}
          {newProfile &&
            !validatePermission(['organization.view']) &&
            !isLoading && (
              <TabPane key="profile">
                <RoleBasedError message="The organization profile page is only available to the organization owner and organization managers." />
              </TabPane>
            )}
          {
            validatePermission(['organization.update']) && enableAiFilter ? (
              <TabPane tab={AIFilterLabel} key="ai-filter">
                <FilterAI />
              </TabPane>
            ) : null
          }
        </Tabs>
      </MainTab>
    </SettingProvider>
  );
};
export default NewAppSetting;
