import React, { useMemo, useCallback, useEffect } from 'react';
import { useQueryClient } from 'react-query';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';
import { Skeleton } from 'antd';
import {
  updateCurrentSubscription,
  getActiveSubscription
} from 'redux/actions/subscription';
import { useFetchCurrentSubscription, useFetchUnpaidInvoicePaymentLink } from 'components/features/setting/useSettingPage';
import useIsLoggedInAdmin from 'hooks/useIsLoggedInAdmin';
import ContactBox from './ContactBox';
import CancelSubscription from './CancelSubscription';
import LimitSection from './LimitSection';
import PaymentTable from './PaymentTable';
import BillingInfo from './BillingInfo';
import SessionUsageAlert from './SessionUsageAlert';
import SubscriptionPlanDetail from './SubscriptionPLanDetail';
import PaymentInfo from './PaymentInfo';
import { authorizeOrgManagerPermission } from '../../commonUtils';
import PaymentDue from './PaymentDue';

const PaymentView = [
  'organization.payment.view',
  'organization.payment.update',
  'organization.payment.create',
];
const SubscriptionView = ['subscription.view'];

const SubscriptionWrapper = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  width: 100%;
  height: 100%;
  display: border-box;
`;
const SubscriptionFirstRow = styled.div`
  width: calc(50% - 10px);
`;
const SubscriptionSecondRow = styled.div`
  width: calc(50% - 10px);
`;

const Subscription = () => {
  const dispatch = useDispatch();
  const queryClient = useQueryClient();
  const {
    currentOrgReducer: {
      orgId, planType,
    },
    applicationReducer,
  } = useSelector((state) => state);

  const profileQueryKey = `profileInfo`;
  const newProfile = queryClient.getQueryData(profileQueryKey);
  const definedRoles = queryClient.getQueryData('roles_permission');

  const queryKey = useMemo(() => `currentSubscription${orgId}`, [orgId]);


  const { isLoading, data: currentSubscription } = useFetchCurrentSubscription({
    queryKey,
    orgId,
    chargebeeData: true,
  });

  const {data: paymentLinkRes,isLoading: isPaymentLinkLoading} = useFetchUnpaidInvoicePaymentLink(orgId);

  const { isLoggedInFromAdmin } = useIsLoggedInAdmin();
  const isSelfCheckoutPlan = !!currentSubscription?.subscription?.isSelfCheckout;
  const isOwner = useMemo(
    () => !!applicationReducer?.find((org) => org.orgId === orgId)?.isOwner,
    [applicationReducer, orgId]
  );
  const showSelfServeCancel = isSelfCheckoutPlan && !isLoggedInFromAdmin;

  const validatePermission = useCallback(
    (permissionCode) =>
      newProfile &&
      authorizeOrgManagerPermission(
        permissionCode,
        definedRoles,
        newProfile?.organization,
        orgId
      ),
    [newProfile, definedRoles, orgId]
  );

  useEffect(() => {
    dispatch(updateCurrentSubscription(currentSubscription));
  }, [currentSubscription , dispatch]);


  useEffect(() => {
    dispatch(getActiveSubscription(orgId))
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [orgId, dispatch]);

  return (
    <Skeleton loading={isLoading} active paragraph={{ rows: 8 }}>
    <SubscriptionWrapper>
      <SubscriptionFirstRow>
        {validatePermission(PaymentView) && (
          <>
            <SubscriptionPlanDetail />
            {/* <NewPlanDetail /> */}
          </>
        )}

        {validatePermission(SubscriptionView) && (
          <>
            <LimitSection hasPermission={validatePermission} />
            <SessionUsageAlert />
          </>
        )}
      </SubscriptionFirstRow>
      {validatePermission(PaymentView) && (
        <SubscriptionSecondRow>
          {!isPaymentLinkLoading && paymentLinkRes?.payment_link && (
              <PaymentDue paymentLink={paymentLinkRes?.payment_link} />
          )}
          <PaymentInfo />
          <PaymentTable />
          { ( planType !== 'free' && planType !== 'trial' ) && <BillingInfo /> }
          <ContactBox>
            {showSelfServeCancel && (
              <CancelSubscription
                orgId={orgId}
                queryKey={queryKey}
                isOwner={isOwner}
              />
            )}
          </ContactBox>
        </SubscriptionSecondRow>
      )}
    </SubscriptionWrapper>
    </Skeleton>
  )
};

export default Subscription;
