import React, {
  Fragment,
  useMemo,
  useId,
  useState,
  useCallback,
  memo,
} from 'react';

import { Tooltip } from 'antd';
import { useSessionRecordingCustomHooks } from './Hooks/SessionRecordingFilter';
import { StyledMenu, StyledPopover, StyledRuleButton } from './RecordingSettingStyles';
import { handleIsOfOrNonOf } from './common/commonVariables'
import  originalData from './common/ruleFileMenu.json'

const RuleTitleInfo = {
  isCrashed: 'Crashed',
  country: 'Country',
  deviceModel: 'Device model',
  date: 'Recording Date',
  duration: 'Session duration',
  appVersion: 'App version',
  sdkVersion: 'UXCam SDK version',
  osVersion: 'OS version',
  noOfInteraction: 'Number of gestures',
  environment: 'Environment',
};
const sessionProperties = [
  'isCrashed',
  'country',
  'date',
  'duration',
  'noOfInteraction',
  'environment',
];
const envTooltip = 'Build type based on the stage of the app release life cycle.'
const versions = ['appVersion', 'sdkVersion'];
const deviceProperties = ['osVersion', 'deviceModel'];

const RecordingFilter = ({
  addRules,
  validateFields,
  commonField,
  defaultSelected,
  setSelectedFilter,
  setFields,
  rulePosition,
  fieldsLength,
  disablefield,
  environmentEnabled,
}) => {
  const { filterData } = useSessionRecordingCustomHooks();

  const [visible, setVisible] = useState(false);
  const uniqueKey = useId();

  const filteredOriginalData = useMemo(
    () =>
      environmentEnabled
        ? originalData
        : originalData.filter((data) => data?.attribute !== 'environment'),
    [environmentEnabled]
  );

  const findAttribute = useCallback(
    (item) => filterData.find((rule) => rule?.key === item),
    [filterData]
  );

  const handleRuleSelectChange = (item) => {
    const selecltedRule = findAttribute(item);

    setFields([
      {
        name: [`${commonField}`, rulePosition, 'attribute'],
        value: selecltedRule?.attribute,
      },
      { name: [`${commonField}`, rulePosition, 'unit'], value: null },
      { name: [`${commonField}`, rulePosition, 'title'], value: selecltedRule?.title },

      {
        name: [`${commonField}`, rulePosition, 'operator'],
        value: selecltedRule?.operator[0]?.val,
      },
    ]);
    selecltedRule?.attribute === 'isCrashed' &&
      setFields([
        {
          name: [`${commonField}`, rulePosition, 'value'],
          value: true,
        },
      ]);
  };

  const handleClick = async (item) => {
    const values = await validateFields([
      [commonField, fieldsLength, 'value'],
      [commonField, fieldsLength, 'value', 'ios'],
      [commonField, fieldsLength, 'value', 'android'],
      [commonField, fieldsLength, 'value', 0],
      [commonField, fieldsLength, 'value', 1],
    ]);
    if (values) {
      let filterValue = [...defaultSelected];
      if (!defaultSelected?.includes(item.key)) {
        filterValue.push(item.key);
        addRules();
        handleRuleSelectChange(item.key);
      } else {
        filterValue = defaultSelected.filter((key) => key !== item?.key);
      }
      setSelectedFilter(filterValue);
    }

    setVisible(false);
  };

  const handleDisabled = useCallback(
    (data) =>
      defaultSelected?.length &&
      defaultSelected?.includes(`${data?.attribute}`),
    [defaultSelected]
  );

  const handleDisabledScreen = useCallback(
    (data) =>
      (defaultSelected?.length > 0 &&
        defaultSelected?.includes(
          `${data?.attribute}-${
            handleIsOfOrNonOf(data?.title) ? 'is' : 'isNot'
          }`
        )) ||
      (defaultSelected?.length > 0 &&
        defaultSelected?.includes(
          `${data?.attribute}-${
            !handleIsOfOrNonOf(data?.title) ? 'is' : 'isNot'
          }`
        )),
    [defaultSelected]
  );

  const filterFormatItems = useMemo(() => {
    let filterField = [];
    const screenVisitedChildern = [];
    const eventsChildern = [];
    const sessionChildern = [];
    const versionChildern = [];
    const deviceChildren = [];

    filteredOriginalData?.length &&
      filteredOriginalData.map((data) => {
        if (['screen'].includes(data?.attribute)) {
          screenVisitedChildern.push({
            label: data?.title,
            key: `${data?.attribute}-${
              handleIsOfOrNonOf(data?.title) ? 'is' : 'isNot'
            }`,
            disabled: handleDisabledScreen(data),
          });
        }
        if (['event'].includes(data?.attribute)) {
          eventsChildern.push({
            label: data?.title,
            key: `${data?.attribute}-${
              handleIsOfOrNonOf(data?.title) ? 'is' : 'isNot'
            }`,
            disabled: handleDisabledScreen(data),
          });
        }
        if (sessionProperties?.includes(data.attribute)) {
          sessionChildern.push({
            label: RuleTitleInfo[data?.attribute] || data?.title,
            key: `${data?.attribute}`,
            disabled: handleDisabled(data),
          });
        }
        if (versions?.includes(data.attribute)) {
          versionChildern.push({
            label: RuleTitleInfo[data?.attribute] || data?.title,
            key: `${data?.attribute}`,
            disabled: handleDisabled(data),
          });
        }
        if (deviceProperties?.includes(data.attribute)) {
          deviceChildren.push({
            label: RuleTitleInfo[data?.attribute] || data?.title,
            key: `${data?.attribute}`,
            disabled: handleDisabled(data),
          });
        }
      });

      const screenDataField = {
        label: 'Visited screens:',
        type: 'group',
        children: screenVisitedChildern,
      };
      const eventsDataField = {
        label: 'Events:',
        type: 'group',
        children: eventsChildern,
      };

    const sessionDataField = {
      label: 'Session properties:',
      type: 'group',
      children: sessionChildern.map((child) => {
        if (child.key === 'environment') {
          return {
            ...child,
            label: <Tooltip title={envTooltip} placement='right'>{child.label}</Tooltip>,
          };
        }
        return child;
      }),
    };
    const versionsDataField = {
      label: 'Versions:',
      type: 'group',
      children: versionChildern,
    };
    const deviceDataField = {
      label: 'Device properties:',
      type: 'group',
      children: deviceChildren,
    };
    filterField = [...filterField, screenDataField,eventsDataField, sessionDataField, versionsDataField, deviceDataField]

    return filterField;
  }, [filteredOriginalData, handleDisabled, handleDisabledScreen]);

  const handleVisibleChange = async (value) => {
    const values = await validateFields([
      [commonField, fieldsLength, 'value'],
      [commonField, fieldsLength, 'value', 'ios'],
      [commonField, fieldsLength, 'value', 'android'],
      [commonField, fieldsLength, 'value', 0],
      [commonField, fieldsLength, 'value', 1],
    ]);
    if (values) setVisible(value);
  };

  const menu = (
    <StyledMenu
      onClick={handleClick}
      items={filterFormatItems}
      selectedKeys={defaultSelected}
    />
  );

  return (
    <Fragment key={`${uniqueKey}_${commonField}`}>
      <StyledPopover
        placement="right"
        visible={visible}
        content={menu}
        trigger="click"
        onVisibleChange={handleVisibleChange}
      >
        <StyledRuleButton type='secondary' disabled={disablefield}>Add rule</StyledRuleButton>
      </StyledPopover>
    </Fragment>
  );
};

export default memo(RecordingFilter);
