import React, { useEffect } from 'react';
import styled from 'styled-components';
import { Modal, Tooltip } from 'antd';
// eslint-disable-next-line import/no-extraneous-dependencies
import { Controller, FormProvider, useForm } from 'react-hook-form'
import { theme } from 'theme';
import { Button, Spinner, UFCInput } from 'uxcam-frontend-components'
import { useRouter } from 'next/router';
import { useQuery, useQueryClient, UseQueryResult } from 'react-query';
// eslint-disable-next-line import/no-extraneous-dependencies
import * as yup from 'yup';
import { useYupValidationResolver } from 'Utils/helpers/yupValidatorResolver';
import WarnIcon from 'public/static/page-definition/warn.svg';
import { useDispatch } from 'react-redux';
import { trackPageViews } from 'redux/actions/trackingReport';
import PathEditor from './PathEditor';
import PatternDisplay from './PatternDisplay';
import { extractParamsFromPattern, extractPathnameFromUrl } from './utils';
import RuleTester from './RuleTester';

const StyledButton = styled(Button)`
	&[data-inline="true"] {
		width: min( 100%, 130px ) !important;
	}
`

const ModalWrap = styled(Modal)`
	.ant-modal-content {
		border-radius: 8px;
		min-height: 180px;
	}
	.ant-modal-footer {
		border-top: none;
		padding: 0;
	}
`;

const ModalHeaderWrap = styled.div`
  display: flex;
  justify-content: space-between;
`;

const TextTitle = styled.div`
  font-size: 18px;
  font-weight: 500;
`;

const TextWrapper = styled.div`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 0.5 ) };
	font-size: 12px;
	line-height: 16px;
	color: #090F19;
	p {
		margin: 0;
	}
`

const Content = styled.div`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 2 ) };
`

const Form = styled.form`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 1.5 ) };
`

const FormField = styled.div`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 1 ) };
`

const Label = styled.label`
	display: flex;
	flex-direction: column;
	font-weight: 500;
	font-size: ${ theme.fontSize( 1.2 ) };
	&[data-disabled="true"] {
		color: #A2A5AE;
	}
`

const CheckboxLabel = styled.label`
	display: inline-flex;
	gap: ${ theme.spacing( 1 ) };
	> input:disabled + span {
		color: ${ theme.colors.surface300.toString() }; 
	}
`

const FormBottom = styled.div`
	display: flex;
	justify-content: flex-end;
	gap: ${ theme.spacing( 2 ) };
	margin-top: ${ theme.spacing( 2 ) };
`

const ErrorLabel = styled.div`
	font-size: ${ theme.fontSize( 1.2 ) };
	color: ${ theme.colors.error500.toString() };
	margin-top: ${ theme.spacing( -0.5 ) };
`

const WarnBlock = styled.div`
	display: flex;
	align-items: center;
	gap: ${ theme.spacing( 1.25 ) };
	padding: ${ theme.spacing( 1 ) };
	background: #FEEEED;
	font-size: ${ theme.fontSize( 1.2 ) };
	border-radius: 4px;
	color: ${ theme.colors.surface400.toString() };
`

const QuestionCircle = styled.div`
	display: inline-flex;
	justify-content: center;
	align-items: center;
	vertical-align: middle;
	width: 14px;
	height: 14px;
	border-radius: 50%;
	font-size: 12px;
	margin-left: 4px;
	cursor: default;
	background: ${ theme.colors.surface10.toString() };
	color: ${ theme.colors.surface500.toString() };
`

const StyledUFCInput = styled(UFCInput)`
	&[aria-invalid="true"] {
		border-color: ${ theme.colors.error500.toString() };
	}
`

const validationSchema = yup.object().shape( {
	originalUrl: yup.string().url().required(),
	pattern: yup.string().required(),
	pageName: yup.string().required(),
} );

export interface PageRuleFormProps {
	id?: string;
	originalUrl: string;
	pattern: string;
	pageName: string;
	order?: number;
}

const defaultValues: PageRuleFormProps = {
	originalUrl: '',
	pattern: '',
	pageName: '',
}

const PageDefinitionModal: React.FC<{
	open: boolean;
	onClose: () => void;
	ruleId: string | null;
	allParameters: string[];
	activeRulesQueryRef: React.MutableRefObject<UseQueryResult<unknown[]>>;
	cleanUpRef: React.MutableRefObject<() => void>;
}> = ( {
	onClose,
	ruleId,
	allParameters: allParametersRaw,
	activeRulesQueryRef,
	cleanUpRef,
} ) => {

	const {
		query,
	} = useRouter();

	const [ savedRule, setSavedRule ] = React.useState<{
		isEdit: boolean;
		pageName: string;
	}>();

	const cleanUp = React.useCallback( () => {
		setTimeout( () => {
			setSavedRule( undefined )
		}, 300 )
	}, [] );

	React.useEffect( () => {
		// eslint-disable-next-line no-param-reassign
		cleanUpRef.current = cleanUp
	}, [ cleanUp, cleanUpRef ] )

	const queryKey = React.useMemo( () => {
		return [ 'pageRule', ruleId || 'new' ]
	}, [ ruleId ] );

	const fetchFn = React.useCallback( async () => {
		if ( !ruleId ) {
			return defaultValues
		}
		const { app } = query;
		const rule = ( await fetch( `${ process.env.SUBSCRIPTION_URL }/app/${ app }/page-definition-setting/${ ruleId }/`, {
			credentials: 'include',
		} )
			.then( ( res ) => res.json() as Promise<{
				data: {
					_id: string;
					originalUrl: string;
					patternUrl: string;
					pageName: string;
					order: number;
				};
				message: string;
				success: boolean;
			}> ) ).data;

		const {
			_id,
			pageName,
			originalUrl,
			patternUrl,
			order,
		} = rule


		return {
			id: _id,
			originalUrl,
			pattern: patternUrl,
			pageName,
			order,
		};

	}, [ ruleId, query ] );

	const fetchedRule = useQuery( queryKey, {
		queryFn: fetchFn,
		suspense: true,
		staleTime: Infinity,
	} );

	const initialData = fetchedRule.data || defaultValues;

	const resolver = useYupValidationResolver( validationSchema );

	const form = useForm<PageRuleFormProps>( {
		defaultValues,
		resolver,
	} );

	const {
		watch,
		setValue,
		handleSubmit,
		reset,
		formState: { errors },
	} = form;


	React.useEffect( () => {
		reset( initialData );
		setTimeout( () => {
			setValue( 'pattern', initialData.pattern );
			setValue( 'originalUrl', initialData.originalUrl );
		}, 0 );
	}, [ initialData, reset, setValue ] );

	const pattern = watch( 'pattern' );
	const originalUrl = watch( 'originalUrl' );

	React.useEffect( () => {
		if ( !pattern && originalUrl ) {
			setValue( 'pattern', extractPathnameFromUrl( originalUrl ).substring( 1 ) )
		}
	}, [ originalUrl, pattern, setValue ] );

	React.useEffect( () => {
		if ( originalUrl && originalUrl !== initialData.originalUrl ) {
			setValue( 'pattern', extractPathnameFromUrl( originalUrl ).substring( 1 ) )
		}
	}, [ setValue, originalUrl, initialData.originalUrl ] );

	const enableFragment = React.useMemo( () => {
		try {
			const url = new URL( originalUrl );
			return url.hash
		} catch( e ) {
			return false
		}
	}, [ originalUrl ] );

	const isIgnoreEverythingChecked = React.useMemo( () => {
		if ( !pattern ) {
			return false
		}
		try {
			const parsedUrl = new URL( originalUrl );
			const newUrl = new URL( `${ parsedUrl.origin }/${ pattern }` );
			return newUrl.pathname.endsWith( '**' );
		} catch( e ) {
			return false
		}
	}, [ pattern, originalUrl ] );

	const handleIgnoreEverythingChange = React.useCallback( ( e: React.ChangeEvent<HTMLInputElement> ) => {
		const { checked } = e.target;
		const parsedUrl = new URL( originalUrl );
		const newUrl = new URL( `${ parsedUrl.origin }/${ pattern }` );

		const { pathname, hash } = newUrl;
		
		if ( checked ) {
			setValue( 'pattern', `${ pathname.slice( 1 ) }**${ hash }` );
		} else {
			setValue( 'pattern', `${ pathname.slice( 1, -2 ) }${ hash }` );
		}
	}, [ pattern, setValue, originalUrl ] );

	const isFragmentChecked = React.useMemo( () => {
		try {
			const parsedUrl = new URL( originalUrl );
			const newUrl = new URL( `${ parsedUrl.origin }/${ pattern }` );
			return newUrl.hash.length > 0;
		} catch( e ) {
			return false
		}
	}, [ originalUrl, pattern ] );

	const handleFragmentChange = React.useCallback( () => {


		let newPattern = pattern

		try {
			const parsedUrl = new URL( originalUrl );
			const parsedPatternUrl = new URL( `https://example.com/${ pattern }` );
			const currentlyChecked = parsedPatternUrl.hash.length > 0;
			const originalUrlHash = parsedUrl.hash;

			newPattern = currentlyChecked ? parsedPatternUrl.pathname.substring( 1 ) : `${ parsedPatternUrl.pathname.substring( 1 ) }${ originalUrlHash }`

		} catch( e ) {
			// nothing
		}

		setValue( 'pattern', newPattern )
	}, [ originalUrl, pattern, setValue ] );

	React.useEffect( () => {
		// eslint-disable-next-line no-restricted-syntax
		for( const [ field ] of Object.entries( errors ) ) {
			const element = document.querySelector( `[name="${ field }"]` );
			if ( element ) {
				( element as HTMLElement ).focus();
				break;
			}
		}
	}, [ errors ] );

	const allParameters = React.useMemo( () => {
		return Array.from(
			new Set(
				allParametersRaw.concat( extractParamsFromPattern( pattern ) )
			)
		)
	}, [ allParametersRaw, pattern ] );

	const containerRef = React.useRef<HTMLDivElement | null>( null );

	const getPopupContainer = React.useCallback( () => {
		return containerRef.current || document.body
	}, [] )

	const [ saveInProgress, setSaveInProgress ] = React.useState( false )

	const reactQueryCache = useQueryClient();
	const dispatch = useDispatch()

	useEffect(() => {
		if( initialData?.id){
			dispatch(trackPageViews(null, {
				eventName: 'wa_page_definitions_edit_rule',
				track_type: 'event',
			}))
		}
	}, [dispatch, initialData?.id])

	const handleRuleSubmit = React.useCallback( ( ruleData: PageRuleFormProps ) => {
		setSaveInProgress( true )
		const {
			id,
			pattern,
			originalUrl,
			pageName,
			order,
		} = ruleData
		const url = `${ process.env.SUBSCRIPTION_URL }/app/${ query.app }/page-definition-setting/${ id ? `${ id }/` : '' }`
		const method = id ? 'PATCH' : 'POST'

		// check if the rule actually changed
		if ( id && initialData.originalUrl === originalUrl && initialData.pattern === pattern && initialData.pageName === pageName ) {
			onClose()
		}

		const body = JSON.stringify( {
			id,
			patternUrl: pattern,
			originalUrl,
			pageName,
			// eslint-disable-next-line @typescript-eslint/no-non-null-assertion
			order: typeof order === 'undefined' ? activeRulesQueryRef.current.data!.length + 1 : order,
			appId: query.app,
		} )

		fetch( url, {
			method,
			body,
			headers: {
				'Content-Type': 'application/json',
			},
			credentials: 'include',
		} )
			.then( ( res ) => res.json() as Promise<{
				data: {
					_id: string;
					originalUrl: string;
					patternUrl: string;
					pageName: string;
				};
				message: string;
				success: boolean;
			}> )
			// eslint-disable-next-line no-shadow
			.then( ( data ) => {

				setSavedRule( {
					isEdit: !!id,
					pageName: data.data.pageName,
				} )

				activeRulesQueryRef.current.refetch()
					.then( () => {
						reactQueryCache.invalidateQueries(  [ 'pageRule', data.data._id || 'new' ] )
					} )
				
					const eventProperty = {
						rule_id: id || data.data._id,
						rule_name: pageName,
						parameter_defined: allParameters.length > 0,
						wildcard: pattern.includes( '/*/' ),
						ignore_end: pattern.includes( '**' ),
						paramenter_named: pattern.includes( ':' ),
						fragments: pattern.substring( 1 ).includes( '#' ),
					}
			
					dispatch(
						trackPageViews(null, {
							eventName: initialData.id ? 'wa_page_definitions_rule_updated' :'wa_page_definitions_rule_created',
							track_type: 'event',
							eventProperty,
						})
					)
						
			} )
			.finally( () => {
				setSaveInProgress( false )
			} )

	}, [query.app, allParameters.length, dispatch, initialData.id, initialData.originalUrl, initialData.pattern, initialData.pageName, activeRulesQueryRef, onClose, reactQueryCache] )

	return (
		<FormProvider
			{ ...form }
		>
			<Content
				ref={ containerRef }
			>
				{
					savedRule ? (
						<>
							<ModalHeaderWrap>
								<TextTitle>
									URL Page Rule created successfully.
								</TextTitle>
							</ModalHeaderWrap>
							<p>
								New sessions containing URLs that match the pattern will be defined as <b>{ savedRule.pageName }</b>.
							</p>
							<FormBottom>
								<StyledButton
									type="button"
									variant="primary"
									size="large"
									onClick={ onClose }
									inline
								>
									Ok
								</StyledButton>
							</FormBottom>
						</>
					) : (
						<>
							<ModalHeaderWrap>
								<TextTitle>{ initialData.id ? 'Edit' : 'Create' } URL match rule</TextTitle>
							</ModalHeaderWrap>
							{
								initialData.id ? (
									<WarnBlock>
										<WarnIcon />
										<span>
											When changing page definition, new rules will only be applied to future sessions, changes are not retroactive
										</span>
									</WarnBlock>
								) : null
							}
							<TextWrapper>
								<p>
									Enter the URL, select dynamic sections, and name the page to simplify reporting by grouping similar URLs. 
								</p>
								<p>
									Rules are not retroactive; new page definitions will be applied to future sessions.
									<Tooltip
										overlay={
											(
												<>
													Please note that query parameters are ignored when matching the URL
													against the defined patterns and can&quot;t be used to define page rules
												</>
											)
										}
									>
										<QuestionCircle>
											?
										</QuestionCircle>
									</Tooltip>
								</p>
							</TextWrapper>
							<Form
								onSubmit={ handleSubmit( handleRuleSubmit ) }
							>
								<FormField>
									<Label>
										Enter URL
									</Label>
									<Controller
										name="originalUrl"
										render={ ( { field } ) => {
											return (
												<>
													<StyledUFCInput
														aria-invalid={ !!errors.originalUrl }
														disabled={ !!ruleId }
														{ ...field }
													/>
													{
														errors.originalUrl ? (
															<ErrorLabel>
																Must be a valid URL
															</ErrorLabel>
														) : null
													}
												</>
											)
										} }
									/>
									<CheckboxLabel>
										<input
											type="checkbox"
											disabled={ !enableFragment }
											checked={ isFragmentChecked }
											onChange={ handleFragmentChange }
										/>
										<span>
											My URL includes fragments
										</span>
									</CheckboxLabel>
								</FormField>
								<FormField>
									<Label>
										Select which parts of the URL are dynamic
									</Label>
									<PathEditor
										allParameters={ allParameters }
										getPopupContainer={ getPopupContainer }
									/>
								</FormField>
								<FormField>
									<Label
										data-disabled={ !pattern }
									>
										URL Match Pattern
									</Label>
									<PatternDisplay />
								</FormField>
								<FormField>
									<CheckboxLabel>
										<input
											disabled={ !pattern }
											onChange={ handleIgnoreEverythingChange }
											type="checkbox"
											checked={ isIgnoreEverythingChecked }
										/>
										<span>
											Ignore everything after the last part of the URL path you entered
										</span>
									</CheckboxLabel>
								</FormField>
								<FormField>
									<Label>
										Define page name
									</Label>
									<Controller
										name="pageName"
										render={ ( { field } ) => {
											return (
												<UFCInput
													{ ...field }
												/>
											)
										} }
									/>
								</FormField>
								<RuleTester isEdit={ !!initialData?.id }/>
								<FormBottom>
									<StyledButton
										type="button"
										variant="ghost"
										size="large"
										inline
										onClick={ onClose }
									>
										Cancel
									</StyledButton>
									<StyledButton
										type="submit"
										variant="primary"
										inline
										size="large"
										disabled={ saveInProgress }
									>
										Save
									</StyledButton>
								</FormBottom>
							</Form>
						</>
					)
				}
			</Content>
		</FormProvider>
	)

}

const PageDefinitionLoader: React.FC<{
	open: boolean;
	onClose: () => void;
	ruleId: string | null;
	allParameters: string[];
	activeRulesQueryRef: React.MutableRefObject<UseQueryResult<unknown[]>>;
}> = React.memo( ( {
	ruleId,
	open,
	onClose,
	allParameters,
	activeRulesQueryRef,
} ) => {

	const cleanUpRef = React.useRef<() => void>();

	// eslint-disable-next-line no-param-reassign
	ruleId = ruleId === 'new' ? null : ruleId;

	const handleClose = React.useCallback( () => {
		if ( cleanUpRef.current ) {
			cleanUpRef.current()
		}
		onClose()
	}, [ onClose ] )

	return (
		<ModalWrap
			visible={ open }
			footer={ null }
			onCancel={ handleClose }
			width={ 700 }
			closable={ false }
			centered
		>
			<React.Suspense fallback={ (
				<div>
					<Spinner
						data-size="m"
					/>
				</div>
			) }>
				<PageDefinitionModal
					key={ `${ ruleId }-${ open }` }
					open={ open }
					onClose={ handleClose }
					ruleId={ ruleId }
					allParameters={ allParameters }
					activeRulesQueryRef={ activeRulesQueryRef }
					cleanUpRef={ cleanUpRef as React.MutableRefObject<() => void> }
				/>
			</React.Suspense>
		</ModalWrap>
	)

} );

export default React.memo( PageDefinitionLoader );