/* eslint-disable no-shadow */
/* eslint-disable jsx-a11y/label-has-associated-control */
import React from 'react'
import styled from 'styled-components'
import { theme } from 'theme'
import { Modal } from 'antd'
import { Button, UFCInput } from 'uxcam-frontend-components'
import { useDispatch } from 'react-redux'
import { trackPageViews } from 'redux/actions/trackingReport'
import { displayPattern, processPatternToMatch } from './utils'

const ModalHeaderWrap = styled.div`
  display: flex;
  justify-content: space-between;
`;

const TextTitle = styled.div`
  font-size: 18px;
  font-weight: 500;
`;

const Container = styled.div`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 2 ) };
`

const ModalWrap = styled(Modal)`
	.ant-modal-content {
		border-radius: 8px;
	}
	.ant-modal-footer {
		border-top: none;
		padding: 0;
	}
`;

const FormBottom = styled.div`
	display: flex;
	justify-content: flex-end;
	gap: ${ theme.spacing( 2 ) };
	margin-top: ${ theme.spacing( 2 ) };
`

const FormField = styled.div`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 1 ) };
`

const Label = styled.label`
	display: flex;
	flex-direction: column;
	font-weight: 500;
	font-size: ${ theme.fontSize( 1.2 ) };
`

const Results = styled.div`
	display: flex;
	flex-direction: column;
	position: relative;
	gap: ${ theme.spacing( 1.5 ) };
	&:before {
		content: '';
		position: absolute;
		top: 0;
		left: 0;
		width: 2px;
		height: 100%;
		background: ${ theme.colors.surface200.toString() };
		opacity: 0.4;
	}
	&:empty {
		display: none;
	}
`

const ResultItem = styled.div`
	display: flex;
	flex-direction: column;
	padding: ${ theme.spacing( 0, 0, 0, 2 ) };
`

const ResultItemHeader = styled.div`
	position: relative;
	&:before {
		content: '';
		width: 8px;
		height: 8px;
		border-radius: 50%;
		position: absolute;
		background: ${ theme.colors.surface200.toString() };
		top: 50%;
		left: -19px;
		transform: translateY( -50% );
	}
`

const ResultItemRow = styled.div`
	padding: ${ theme.spacing( 0, 0, 0, 6 ) };
`

const P = styled.p`
	margin: 0;
`

const ResultsContainer = styled.div`
	display: flex;
	flex-direction: column;
	padding: ${ theme.spacing( 1.5 ) };
	max-height: 130px;
	overflow-y: auto;
	border-radius: 4px;
	color: ${ theme.colors.surface300.toString() };
	gap: ${ theme.spacing( 2 ) };
	background: ${ theme.colors.surface05.toString() };
`

const MultipleResultsDescription = styled.div`
	font-size: ${ theme.fontSize( 1.2 ) };
	line-height: ${ theme.fontSize( 2.2 ) };
`

interface IRule {
	patternUrl: string;
	pageName: string;
}

const TestUrl: React.FC<{
	open: boolean;
	onClose: () => void;
	rules: {
		patternUrl: string;
		pageName: string;
	}[],
}> = ( {
	open,
	onClose,
	rules,
} ) => {

	const [ url, setUrl ] = React.useState<string>( '' )

	const compiledRules = React.useMemo( () => {
		return rules.map( rule => {
			const matchRule = processPatternToMatch( rule.patternUrl )
			return {
				...rule,
				match: matchRule,
			}
		} )
	}, [ rules ] )

	const handleInputChange = React.useCallback( ( e: React.ChangeEvent<HTMLInputElement> ) => {
		setUrl( e.target.value )
	}, [] )

	const [ results, setResults ] = React.useState<IRule[]>()
	const dispatch = useDispatch()

	const handleTest = React.useCallback( () => {
		const results = compiledRules.filter( rule => {
			return rule.match( url )
		} )
		.map( rule => {
			return {
				...rule,
				params: rule.match( url ),
			}
		} )
		setResults( results )
		dispatch(trackPageViews(null, {
			eventName: 'wa_page_definitions_test_rule',
			track_type: 'event',
			eventProperty: {
				position: 'page'
			}
		}))
	}, [ compiledRules, dispatch, url ] )

	const isUrlValid = React.useMemo( () => {
		try {
			// eslint-disable-next-line no-new
			new URL( url )
			return true
		} catch ( e ) {
			return false
		}
	}, [ url ] )

	const handleReset = React.useCallback( () => {
		setResults( undefined )
		setUrl( '' )
	}, [] )

	// clear on close
	React.useEffect( () => {
		if ( !open ) {
			setTimeout( () => {
				handleReset(	)
			}, 300 )
		}
	}, [ open, handleReset ] )

	return (
		<ModalWrap
			visible={ open }
			footer={ null }
			onCancel={ onClose }
			width={ 700 }
			centered
			closable={ false }
		>
			{ results ? (
				<Container>
					<ModalHeaderWrap>
						<TextTitle>
							Your URL matches the following rules:  
						</TextTitle>
					</ModalHeaderWrap>
					<ResultsContainer>
						<div>
							URL <b>{ url }</b>
							{
								results.length ? (
									<span>
										&nbsp;
										matched these rules:
									</span>
								) : (
									<span>
										&nbsp;
										does not match any of the rules defined.
									</span>
								)
							}
						</div>
						<Results>
							{
								results.map( ( rule, index ) => {
									return (
										// eslint-disable-next-line react/no-array-index-key
										<ResultItem key={ index }>
											<ResultItemHeader>
												Rule {index + 1}:
											</ResultItemHeader>
											<ResultItemRow>
												Pattern: <b>{ displayPattern( rule.patternUrl ) }</b>
											</ResultItemRow>
											<ResultItemRow>
												Page name: <b>{ rule.pageName }</b>
											</ResultItemRow>
										</ResultItem>
									)
								} )
							}
						</Results>
					</ResultsContainer>
					{
						results.length > 1 ? (
							<MultipleResultsDescription>
								Rules are applied from top to bottom. Rule 1 will overrule Rule 2 since it appears first. If a URL matches both rules, the system will apply Rule 1.
							</MultipleResultsDescription>
						) : null
					}
					<FormBottom>
						<Button
							type="button"
							variant="ghost"
							size="large"
							onClick={ onClose }
						>
							Cancel
						</Button>
						<Button
							type="button"
							variant="primary"
							size="large"
							onClick={ handleReset }
						>
							Try another URL
						</Button>
					</FormBottom>
				</Container>
			) : (
				<Container>
					<ModalHeaderWrap>
						<TextTitle>
							Test URL
						</TextTitle>
					</ModalHeaderWrap>
					<P>
						Enter a URL to evaluate against your rules. The results will indicate if the URL matches any rules. <a target="_blank" rel="noreferrer" href="https://help.uxcam.com/en/articles/10652702-how-to-set-up-page-definition-in-uxcam">Read more</a> about rules hierarchy and competing rules. 
					</P>
					<FormField>
						<Label>
							Enter URL
						</Label>
						<UFCInput
							value={ url }
							onChange={ handleInputChange }
							placeholder="https://www.example.com/products/shoes"
						/>
					</FormField>
					<FormBottom>
						<Button
							type="button"
							variant="ghost"
							size="large"
							onClick={ onClose }
						>
							Cancel
						</Button>
						<Button
							type="button"
							variant="primary"
							size="large"
							disabled={ !isUrlValid }
							onClick={ handleTest }
						>
							Test
						</Button>
					</FormBottom>
				</Container>
			) }
		</ModalWrap>
	)
}

export default TestUrl