import React from 'react'
import type { AnyObject, ObjectSchema } from 'yup'

export const useYupValidationResolver = <T extends AnyObject>(validationSchema: ObjectSchema<T>) =>
	React.useCallback(
	  async ( data: T ) => {
		try {
		  const values = await validationSchema.validate(data, {
			abortEarly: false,
		  })
  
		  return {
			values,
			errors: {},
		  }
		} catch ( errors ) {
			const useErrors = errors as any
		  return {
			values: {},
			errors: useErrors.inner.reduce(
			  (allErrors: any, currentError: any ) => ({
				...allErrors,
				[currentError.path]: {
				  type: currentError.type ?? "validation",
				  message: currentError.message,
				},
			  }),
			  {} as Record<string, { type: string; message: string }>
			),
		  }
		}
	  },
	  [validationSchema]
);
