const MessageDiv = styled.div`
  display: flex-inline;
  color: #eb5757;
  font-weight: 400;
  font-size: 12px;
  padding: 4px;
  a {
    color: #eb5757;
    text-decoration: underline;
  }
`;

const ErrorMsg = styled.p`
  color: #eb5757;
  font-weight: 400;
  font-size: 12px;
  margin: 0;
  margin-top: 4px;
`;

const OrgProfile = () => {
  const dispatch = useDispatch();
  const [editName, setEditName] = useState(false);
  const [orgName, setOrgName] = useState();
  const [orgNameError, setOrgNameError] = useState('');
  const userNameRef = useRef(null);

  const { currentOrgReducer: currentOrg, organizationReducer: orgList } =
    useSelector((state) => state);
  const { orgId, organizationName } = currentOrg;
  const { refetch: updateOrgName } = useUpdateOrgName(
    { name: orgName, _csrf: 0 },
    orgId
  );
  const { data: newProfile } = useFetchNewProfile(`profileInfo`);
  const { data: definedRoles } = useFetchRolesAndPermission('roles_permission');
  useFetchTeamList(orgId);


  const validateOrgManagerPermission = useCallback(
    (permissionCode) =>
      newProfile &&
      authorizeOrgManagerPermission(
        permissionCode,
        definedRoles,
        newProfile?.organization,
        orgId
      ),
    [newProfile, orgId, definedRoles]
  );

  const handeOnChange = (e) => {
    if (!editName) {
      setEditName(!editName);
    }
    setOrgName(e.target.value);
    const inputValue = e.target.value;

    // Check for invalid characters
    if (!nameRegex.test(inputValue)) {
      setOrgNameError(`Name field only accepts the following characters: alphabets (A-Z, a-z), numbers (0-9), dash (-), underscore (_), apostrophe ('), and spaces.`);
      return;
    }

    // Validate character count
    if (inputValue.length > 32) {
      setOrgNameError(`Organization name should contain at most 32 characters.`);
      return;
    }

    setOrgNameError('');
  };

  const handleNameChange = () => {
    if (orgName && orgName !== organizationName) {
      updateOrgName().then((res) => {
        if (res?.data?.message) {
          message.success(res?.data?.message);
          const newOrgList = orgList.map((org) => {
            if (org[`_id`] === res?.data?.organization['_id']) {
              return res?.data?.organization;
            }
            return org;
          });

          const updateCurrentOrg = {
            ...currentOrg,
            organizationName: res?.data?.organization?.name,
          };

          dispatch(storeOrgList(newOrgList));
          dispatch(updateActiveSubscription(updateCurrentOrg));
        }

        res?.error?.message &&
          message.error(res?.error?.message || 'Unable to update name');
      });
    } else {
      setOrgName(organizationName);
    }
    setEditName(false);
  };

  const AddonEdit = (
    <ButtonDiv>
      {editName && (
        <>
          {
            !orgNameError && (
              <Button type="primary" size="small" onClick={handleNameChange}>
                Save
              </Button>
            )
          }
          <Button
            size="small"
            onClick={() => {
              setEditName(false);
              setOrgName(organizationName);
              setOrgNameError('');
            }}
          >
            Cancel
          </Button>
        </>
      )}
    </ButtonDiv>
  );

  const infoMessage = (
    <MessageDiv>
      To delete the organization, please reach out to{' '}
      <Link href="mailto:team@uxam.com">team@uxcam.com</Link>
    </MessageDiv>
  );

  useEffect(() => {
    setOrgName(organizationName);
  }, [orgId]);

  return (
    <Main>
      <Label>Organization logo</Label>
      <Photo>
        <OrgProfilePhoto hasOrgPermission={validateOrgManagerPermission} />
      </Photo>
      <Individual>
        <Label>Organization name</Label>
        <Input
          placeholder={`${organizationName}`}
          value={orgName}
          onChange={
            validateOrgManagerPermission(OrgUpdatePermission) &&
            handeOnChange
          }
          ref={userNameRef}
          addonAfter={AddonEdit}
          disabled={!validateOrgManagerPermission(OrgUpdatePermission)}
        />
        {orgNameError && <ErrorMsg>{orgNameError}</ErrorMsg>}
      </Individual>
      {validateOrgManagerPermission(['organization.delete']) && (
        <ErrorAlert
          message={infoMessage}
          type="error"
          showIcon
          icon={<InfoCircleFilled />}
        />
      )}
    </Main>
  );
};

export default OrgProfile;
