const fieldType = (item, handleSelect, attributeType) => {
  const { type, attribute, disabled } = item;
  const filterOptions = item?.options || [];
  let defaultValues = item?.values || undefined;
  if (!attribute) return;

  if(Array.isArray(defaultValues)) {
    defaultValues = defaultValues.map((obj) => ({
      ...obj,
      label: obj?.key || obj?.val || obj?.value,
      value: obj?.val || obj?.value || obj?.key,
    }));
  }

  if(attribute === 'environment'){
    defaultValues = item?.values?.map(({key}) => ({
        label: <Tooltip title={getEnvTooltip(key)}>{capitalizeEnvString(key)}</Tooltip> ,
        value: key,
      }))
  }
  if(attribute === 'sdkVersion'){
    defaultValues = item?.values?.map((obj) => ({
      label: addPlatformInfo(obj?.key || obj?.value, obj?.type),
      value: addPlatformInfo(obj?.key || obj?.value, obj?.type),
    }));
  }
  //* CX-2113 For DeviceModel 
  if(attribute === 'deviceModel'){
    const excludeIdOnLabel = ['iphone', 'ipad', 'ipod']; // * This List is used to exclude id from label 
    defaultValues = item?.values?.map(({label,value,key, val}) => {
        const labelToUse = label || key
        const valueToUse = value || val
        if(valueToUse.includes('+')){
                return({
                    label: labelToUse,
                    value: valueToUse
                })
        }
    
        return({
        label: excludeIdOnLabel?.some(prefix => labelToUse.toLowerCase().startsWith(prefix)) ?
                  labelToUse:
                  `${labelToUse} (${valueToUse})`
              ,
              value: `${labelToUse}+${valueToUse}`,
      })
    })
  }

  const filterOptionData = filterOptions.map((obj) => ({
    label: obj?.key,
    value: obj?.key,
  }));
  const filterRadioOptions = item.options;

  switch (type) {
    case 'date':
      return (
        <DatePicker
          placeholder={item.placeholder}
          disabled={disabled}
        />
      );

    case 'input':
      return <Input disabled={disabled} placeholder={item.placeholder} />;

    case 'boolean':
      return (
        <StyledSelect disabled={disabled} onChange={handleSelect}>
          {filterRadioOptions.map((obj) => (
            <Option key={obj?.key} value={obj?.val}>
              {obj?.val ? 'is true' : 'is false'}
            </Option>
          ))}
        </StyledSelect>
      );

    case 'float':
      return (
        <StyledRuleNumber
          disabled={disabled}
          controls={false}
          min={0}
          placeholder={item.placeholder}
        />
      );

    default:
      return (
        <DebounceSearch
          filterOptionData={filterOptionData}
          defaultValues={defaultValues}
          handleSelect={handleSelect}
          attribute={attribute}
          attributeType={attributeType}
          placeholder={item.placeholder}
          disabled={disabled}
        />
      );
  }
};

const CommonRuleFields = ({
  commonField,
  defaultSelected,
  form,
  disablefield,
  environmentEnabled,
}) => {
  const userId = useId();
  const isVideo = useMemo(() => commonField === 'filter', [commonField]);

  // to remove after feature flag 'app-setting-env' removed
  const filtedRuleTitleInfo = useMemo(
    () =>
      environmentEnabled
        ? ruleTitleInfo
        : () => {
            delete ruleTitleInfo.environment;
            return ruleTitleInfo;
          },
    [environmentEnabled]
  );

  const {
    filterData,
    setSelectedFilter,
    setInitialSessionData,
    initialSessionData,
    initialVideoData,
    setInitialVideoData,
    setSelectedVideoFilter,
  } = useSessionRecordingCustomHooks();
  const ruleFieldValue = Form.useWatch(`${commonField}`, form);

  const handleDataField = useCallback(
    (filter, name) => {
      const selectedAttribute = filter?.length ? filter[name] : null;
      const selctedField =
        filterData?.length > 0 &&
        filterData.find(
          (value) => selectedAttribute && value?.key === selectedAttribute
        );
      return selctedField;
    },
    [filterData]
  );

  const handleCommonFilter = useCallback(
    (name) => handleDataField(defaultSelected, name),
    [defaultSelected, handleDataField]
  );

  const handleSelectChange = (value, fieldKey) => {
    const newValue = {};
    const keyData = [`${commonField}`, fieldKey, 'value'];
    newValue[keyData] = value;

    form.setFields([{ name: [`${commonField}`, fieldKey, 'value'], value }]);
    const initialData = isVideo
      ? [...initialVideoData]
      : [...initialSessionData];
    const newInitialData = initialData.map((data, index) => {
      const newData = { ...data };
      if (index === fieldKey) {
        newData.value = value;
      }
      return newData;
    });
    isVideo
      ? setInitialVideoData(newInitialData)
      : setInitialSessionData(newInitialData);
    form.validateFields([[`${commonField}`, fieldKey, 'value']]);
  };

  const handleOperatorChange = (value, fieldKey) => {
    form.setFields([
      { name: [`${commonField}`, fieldKey, 'value'], value: undefined },
    ]);
    form.setFields([{ name: [`${commonField}`, fieldKey, 'operator'], value }]);
  };

  const handleVersionSelectChange = (value, fieldKey, field) => {
    form.setFields([
      { name: [`${commonField}`, fieldKey, 'value', field], value },
    ]);
    const initialData = isVideo
      ? [...initialVideoData]
      : [...initialSessionData];
    const newInitialData = initialData.map((data, index) => {
      const newData = { ...data };
      if (index === fieldKey) {
        newData.value = form.getFieldValue([
          `${commonField}`,
          fieldKey,
          'value',
          field,
        ]);
      }

      return newData;
    });
    isVideo
      ? setInitialVideoData(newInitialData)
      : setInitialSessionData(newInitialData);
    form.validateFields([
      [`${commonField}`, fieldKey, 'value', 'ios'],
      [`${commonField}`, fieldKey, 'value', 'android'],
    ]);
  };

  const filterAndroidOriOSOptions = useCallback(
    (versionList, osType) =>
      versionList.filter((data) => data?.type === osType),
    []
  );

  return (
    <Form.List name={`${commonField}`} key={commonField}>
      {(fields, { add: addRules, remove }) => (
        <>
          <AddMultipleFormItem>
            <RecordingFilter
              addRules={addRules}
              validateFields={form.validateFields}
              commonField={commonField}
              defaultSelected={defaultSelected}
              setSelectedFilter={
                isVideo ? setSelectedVideoFilter : setSelectedFilter
              }
              rulePosition={fields?.length}
              setFields={form?.setFields}
              fieldsLength={fields?.length - 1}
              disablefield={disablefield}
              environmentEnabled={environmentEnabled}
            />
          </AddMultipleFormItem>

          {fields.map(({ key, name, ...restField }) => {
            const dataField = handleCommonFilter(name);
            const itemValue = {
              type: dataField?.type,
              attribute: dataField?.attribute,
              options: dataField?.possibleValue,
              placeholder: `${
                placeholderInfo[dataField?.type]
                  ? placeholderInfo[dataField?.type]
                  : ''
              }`,
              values:
                form.getFieldValue([`${commonField}`, name, 'value']) ||
                undefined,
              disabled: disablefield,
            };

            const androidVersionItemValue = {
              type: dataField?.type,
              attribute: dataField?.attribute,
              options:
                dataField?.attribute === 'osVersion'
                  ? filterAndroidOriOSOptions(
                      dataField.possibleValue,
                      'android'
                    )
                  : dataField?.possibleValue,
              placeholder: 'Select value',
              values: form.getFieldValue([
                `${commonField}`,
                name,
                'value',
                'android',
              ]),
              disabled: disablefield,
            };

            const iosVersionItemValue = {
              type: dataField?.type,
              attribute: dataField?.attribute,
              options:
                dataField?.attribute === 'osVersion'
                  ? filterAndroidOriOSOptions(dataField.possibleValue, 'ios')
                  : dataField?.possibleValue,
              placeholder: 'Select value',
              values: form.getFieldValue([
                `${commonField}`,
                name,
                'value',
                'ios',
              ]),
            };

            const handleSelect = (value) => {
              handleSelectChange(value, name);
            };

            const handleAndroidSelect = (value) =>
              handleVersionSelectChange(value, name, 'android');

            const handleIOSSelect = (value) =>
              handleVersionSelectChange(value, name, 'ios');

            const operatorOption =
              dataField?.operator instanceof Array ? dataField?.operator : [];

            const handleDelete = () => {
              const filterValues = defaultSelected;

              const newFilter = filterValues.filter(
                (_, index) => index !== name
              );

              isVideo
                ? setSelectedVideoFilter(newFilter)
                : setSelectedFilter(newFilter);
              remove(name);
            };

            return (
              <RuleFieldDiv key={`main-${commonField}_${key}`}>
                <LabelAndDeleteStyled>
                  <StyledRuleTitle>
                    {filtedRuleTitleInfo[dataField?.attribute] ||
                      dataField?.title}
                  </StyledRuleTitle>
                  <StyledButton>
                    <DeleteOutlined
                      twoToneColor="#f4584c"
                      onClick={() => !disablefield && handleDelete()}
                    />
                  </StyledButton>
                </LabelAndDeleteStyled>
                <StyledMainSpace key={`${commonField}_${key}`}>
                  <StyledSpace key={userId}>
                    <StyledRuleMain>
                      <StyledRuleMain className="site-input-group-wrapper">
                        <DynamicFormItemValue noStyle>
                          <StyledInputGroup compact>
                            {!hasNoOperator?.includes(dataField?.attribute) && (
                              <OperatorFormItem
                                {...restField}
                                name={[name, 'operator']}
                                rules={[
                                  {
                                    required: true,
                                    message: 'Value required',
                                  },
                                ]}
                              >
                                <StyledSelect
                                  placeholder="Please select operator"
                                  disabled={disablefield}
                                  onChange={(e) =>
                                    handleOperatorChange(e, name)
                                  }
                                >
                                  {operatorOption?.length &&
                                    operatorOption?.map((obj) => (
                                      <Option
                                        key={obj?.key}
                                        value={obj?.val}
                                        label={obj?.key}
                                      >
                                        <div>{obj?.key}</div>
                                      </Option>
                                    ))}
                                </StyledSelect>
                              </OperatorFormItem>
                            )}
                            {['noOfInteraction', 'duration'].includes(
                              dataField?.attribute
                            ) && (
                              <>
                                <StyledBetweenMinValue
                                  isbetween={
                                    ruleFieldValue?.length > 0 &&
                                    ruleFieldValue[name]?.operator === 'gt&lt'
                                      ? 1
                                      : 0
                                  }
                                  rules={[
                                    {
                                      required: true,
                                      message: 'Value required',
                                    },
                                  ]}
                                  {...restField}
                                  name={[name, 'value', 0]}
                                >
                                  {dataField && fieldType(itemValue)}
                                </StyledBetweenMinValue>

                                {ruleFieldValue?.length > 0 &&
                                  ruleFieldValue[name]?.operator ===
                                    'gt&lt' && (
                                    <>
                                      <StyledInputSeparator
                                        className="site-input-split"
                                        style={{
                                          width: 30,
                                        }}
                                        placeholder="--"
                                        disabled
                                      />
                                      <StyledBetweenMaxValue
                                        rules={[
                                          {
                                            required: true,
                                            message: 'Value required',
                                          },
                                        ]}
                                        {...restField}
                                        name={[name, 'value', 1]}
                                      >
                                        {dataField && fieldType(itemValue)}
                                      </StyledBetweenMaxValue>
                                    </>
                                  )}
                              </>
                            )}

                            {versionTypesField.includes(
                              dataField?.attribute
                            ) && (
                              <DynamicFormItemValue noStyle>
                                <>
                                  <StyledBetweenMinValue
                                    isbetween={1}
                                    {...restField}
                                    name={[name, 'value', 'android']}
                                    rules={[
                                      {
                                        required: !form.getFieldValue([
                                          commonField,
                                          name,
                                          'value',
                                          'ios',
                                        ]),
                                        message: 'Value required',
                                      },
                                    ]}
                                  >
                                    <StyledVerisonLabel>
                                      Android
                                    </StyledVerisonLabel>
                                    {fieldType(
                                      androidVersionItemValue,
                                      handleAndroidSelect,
                                      'android'
                                    )}
                                  </StyledBetweenMinValue>

                                  <StyledSeparator>or</StyledSeparator>
                                  <StyledBetweenMaxValue
                                    {...restField}
                                    name={[name, 'value', 'ios']}
                                    rules={[
                                      {
                                        required: !form.getFieldValue([
                                          commonField,
                                          name,
                                          'value',
                                          'android',
                                        ]),
                                        message: 'Value required',
                                      },
                                    ]}
                                  >
                                    <StyledVerisonLabel>iOS</StyledVerisonLabel>
                                    {fieldType(
                                      iosVersionItemValue,
                                      handleIOSSelect,
                                      'ios'
                                    )}
                                  </StyledBetweenMaxValue>
                                </>
                              </DynamicFormItemValue>
                            )}

                            {!normalField.includes(dataField?.attribute) && (
                              <DynamicFormItemValue
                                hasoperator={
                                  !hasNoOperator?.includes(dataField?.attribute)
                                    ? 1
                                    : 0
                                }
                                {...restField}
                                name={[name, 'value']}
                                rules={[
                                  {
                                    required: true,
                                    message: 'Value required',
                                  },
                                ]}
                              >
                                {dataField &&
                                dataField?.attribute === 'date' &&
                                ruleFieldValue?.length > 0 &&
                                ruleFieldValue[name]?.operator === 'gt&lt' ? (
                                  <StyledRangePicker />
                                ) : (
                                  fieldType(itemValue, handleSelect)
                                )}
                              </DynamicFormItemValue>
                            )}
                          </StyledInputGroup>
                        </DynamicFormItemValue>
                      </StyledRuleMain>
                    </StyledRuleMain>
                  </StyledSpace>
                </StyledMainSpace>

                {dataField?.attribute === 'environment' ? (
                  <InfoLogMessage title="Environment rule is supported from Android SDK version 3.6.15 onwards and iOS SDK version 3.6.6 onwards." />
                ) : null}
              </RuleFieldDiv>
            );
          })}
        </>
      )}
    </Form.List>
  );
};

