import React, {
  createContext,
  useState,
  useMemo,
  useContext,
  memo,
} from 'react';

const SettingDataContext = createContext({
  selectedTeamList: [],
  setSelectedTeamList: () => null,
  searchValue: '',
  setSearchValue: () => null,
  selectedApp: '',
  setSelectedApp: () => null,
  searchAppName: '',
  setSearchAppName: () => null,
});

export const useSettingPage = () => {
  const {
    selectedTeamList,
    setSelectedTeamList,
    searchValue,
    setSearchValue,
    selectedApp,
    setSelectedApp,
    searchAppName,
    setSearchAppName,
  } = useContext(SettingDataContext);
  return useMemo(
    () => ({
      selectedTeamList,
      setSelectedTeamList,
      searchValue,
      setSearchValue,
      selectedApp,
      setSelectedApp,
      searchAppName,
      setSearchAppName,
    }),
    [
      selectedTeamList,
      searchValue,
      setSearchValue,
      setSelectedTeamList,
      selectedApp,
      setSelectedApp,
      searchAppName,
      setSearchAppName,
    ]
  );
};

export const SettingProvider = memo(({ children }) => {
  const [selectedTeamList, setSelectedTeamList] = useState([]);
  const [searchValue, setSearchValue] = useState('');
  const [selectedApp, setSelectedApp] = useState('');
  const [searchAppName, setSearchAppName] = useState('');

  const settingsContext = useMemo(
    () => ({
      selectedTeamList,
      setSelectedTeamList,
      searchValue,
      setSearchValue,
      selectedApp,
      setSelectedApp,
      searchAppName,
      setSearchAppName,
    }),
    [
      selectedTeamList,
      setSelectedTeamList,
      searchValue,
      setSearchValue,
      selectedApp,
      setSelectedApp,
      searchAppName,
      setSearchAppName,
    ]
  );

  return (
    <SettingDataContext.Provider value={settingsContext}>
      {children}
    </SettingDataContext.Provider>
  );
});
