/* eslint-disable no-underscore-dangle */
import React, { useState, useEffect } from 'react';
import { Upload, Button, message, Spin } from 'antd';
import styled from 'styled-components';
import { LoadingOutlined } from '@ant-design/icons';
import { useMutation } from 'react-query';

import UserImageInfo from 'components/features/setting/ProfileImageOrText';
import { convertFileToBase64 } from 'Utils/helpers/commonUtils';
import { ChangeIconEditSvg } from '../SvgIcon';
import { updateAppImage } from '../../useSettingPage';

const WrapperDiv = styled.div`
  display: flex;
  flex-direction: column;
  width: 70px;
  position: relative;
  align-items: center;
  .ant-avatar-square {
    border-radius: 13px;
  }
  .ant-upload-select {
    position: absolute;
    bottom: -16px;
    left: 0;
  }
  .ant-avatar-string {
    font-size: 40px;
  }
`;

const CircleButton = styled(Button)`
  margin: 0 8px;
  color: #5d97ff;
  text-align: center;
  border-color: #dee8ff;
`;

const ChangeIconButton = styled(CircleButton)`
  border: none;
  padding: 0;
  height: 0;
  font-size: 8px;
  color: #5b6d89;
`;

const acceptType = 'image/jpeg, image/jpg, image/png';
const fileName = 'imageFile';
const fileType = 'picture';

const ChangeIcon = ({ user, permission }) => {
  const [selectedFileList, setSelectedFileList] = useState([]);
  const [selectedApp, setSelectedApp] = useState();
  const [imageSrc, setImageScr] = useState();

  const beforeUpload = (file) => {
    const { type, size } = file;
    const isJpgOrPng =  acceptType.includes(type);
    const isMaxSize = size / 1024 / 1024 < 2;
    if (isJpgOrPng) {
      if (!isMaxSize) {
        message.error('Image size must smaller than 2MB.');
      }
    } else {
      message.error('Only files with these extensions are allowed: png, jpg, jpeg.');
    }
    return isJpgOrPng && isMaxSize;
  };


  const { image, _id: appId } = user;

  const { mutate, isLoading } = useMutation(updateAppImage, {
    onSuccess: (data) => {
      if(data?.app){
        setImageScr(data?.app?.image);
        message.success(data?.message);
      }
      if(data?.error){
        data?.error?.imageFile && message.error(data?.error?.imageFile[0])
        setImageScr(image);
      }
    },
    onError: (error) => {
      message.error(
        error?.data?.error?.message || 'Unable to change the icon of app.'
      );
      setImageScr(image);
    },
  
  });

  const handleImageUpload = async (options) => {
    const isValid = await beforeUpload(options?.file);
    const base64String = await convertFileToBase64(options?.file);
    const payload = {
      [fileName]: base64String,
    }
    setSelectedFileList(options);
    if (isValid) {
      mutate({ payload, appId });
    }
  };

  const handleChange = () => {
    setSelectedApp(user[`_id`]);
  };

  useEffect(() => {
    setImageScr(image);
  }, [image]);

  return (
    <WrapperDiv>
      <Spin
        spinning={user?._id === selectedApp ? isLoading : false}
        indicator={<LoadingOutlined />}
        size="small"
      >
        <UserImageInfo
          picture={imageSrc}
          nameInfo={user.name ? user.name.trim() : user.email.trim()}
          size={55}
          shape="square"
        />
      </Spin>

      <Upload
        name={fileName}
        customRequest={handleImageUpload}
        fileList={selectedFileList[fileName]?.originFileObj}
        accept={acceptType}
        listType={fileType}
        onChange={handleChange}
        showUploadList={false}
        maxCount={1}
      >
        {permission && (
          <ChangeIconButton
            disabled={isLoading}
            icon={<ChangeIconEditSvg />}
            className="hover-button"
          >
            Change icon
          </ChangeIconButton>
        )}
      </Upload>
    </WrapperDiv>
  );
};

export default ChangeIcon;
