import React from 'react';
import { connect } from 'react-redux';
import {
  CopyOutlined,
  EditOutlined,
  InfoCircleOutlined,
  RetweetOutlined,
} from '@ant-design/icons';
import { Row, Col, Alert, Input, Button, message, Tooltip } from 'antd';
import AppApi from 'services/appApi';
import validatePublicKey from 'uuid-validate';
import { CopyToClipboard } from 'react-copy-to-clipboard';
import { isProd } from 'Utils/constants/variables';
import { apiPlanError } from 'Utils/constants/index';
import styled from 'styled-components';
import { trackPageViews } from 'redux/actions/trackingReport';
import InfoBox from 'components/common/InfoBox';

const _pURL = isProd ? `https://api.uxcam.com/v2` : process.env.PYTHON_API_URL_V2;

const StyledAlert = styled(Alert)`
  background: rgba(93, 151, 255, 0.08);
  font-size: 12px;
  border-radius: 4px;
  width: 100%;
  border: none;
  min-height: 40px;
  height: auto;
  margin-bottom: 18px;
  a {
    text-decoration: none;
    color: #5D97FF;
  }

  .btn-wrapper .ant-btn {
    height: 40px;
    align-items: center;
  }
`;

class PublicApiAccess extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      editKeyOption: false,
      originalAppKey: null,
      appKey: null,
      viewOnly: false
    };
  }

  onApiKeyChange = (apiKey) => {
    this.setState({ appKey: apiKey.target.value, editKeyOption: true });
  };

  editKey = (editValue) => {
    let self = this;
    this.setState({ editKeyOption: editValue }, () => {
      setTimeout(() => {
        self.input.focus().val(input.val());
      }, 100);
    });
  };

  savePublicApiKey = () => {
    if (validatePublicKey(this.state.appKey)) {
      if (this.state.appKey === this.state.originalAppKey) {
        message.info('Public API key is same');
        return;
      }
      let saveData = {
        apiKey: this.state.appKey,
        _csrf: this.props.app_csrf,
      };
      AppApi.savePublicApiKey(saveData, this.props.appId)
        .then((res) => {
          this.setState({
            originalAppKey: this.state.appKey,
            editKeyOption: false,
          });
          message.success(res.data.data.message);
        })
        .catch((err) => {
          if (err.response.data.error.message) {
            message.error(err.response.data.error.message);
          } else if (err.response.data.error.apiKey.length) {
            message.error(err.response.data.error.apiKey[0]);
          }
        });
    } else {
      message.error('Please enter valid API key');
    }
  };

  cancelPublicApiKey = () => {
    let self = this;
    this.setState({
      originalAppKey: this.state.originalAppKey,
      appKey: this.state.originalAppKey,
    });
    if (this.state.originalAppKey) {
      this.setState({ editKeyOption: false });
    }
  };

  generateUUID = () => {
    let self = this;
    let d = new Date().getTime();

    this.props.trackPageViews(null, {
        eventName: 'wa_appsettings_generate_api_key',
        track_type: 'event',
    })

    if (window.performance && typeof window.performance.now === 'function') {
      d += window.performance.now();
    }
    let uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(
      /[xy]/g,
      function (c) {
        let r = (d + Math.random() * 16) % 16 | 0;
        d = Math.floor(d / 16);
        return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
      }
    );
    this.setState({ appKey: uuid, generatedApiKey: true }, () => {
      // setTimeout(() => {
      //   self.input.focus().val(input.val())
      // }, 500)
    });
    // return uuid;
  };

  publicApiRef = (input) => (this.input = input);

  copy(e) {
    e.stopPropagation();
    e.preventDefault();
    message.success('copied');
  }

  componentDidMount() {
    if (this.props.appKey) {
      this.setState({
        appKey: this.props.appKey,
        originalAppKey: this.props.appKey,
        editKeyOption: false,
      });
    } else {
      this.setState({
        appKey: this.props.appKey,
        originalAppKey: this.props.appKey,
        editKeyOption: true,
      });
    }
    this.setState({viewOnly:this.props?.appConfigViewOnly })
  }
  async UNSAFE_componentWillReceiveProps(nextProps) {
    if (nextProps.appKey) {
      this.setState({
        appKey: nextProps?.appKey,
        originalAppKey: nextProps?.appKey,
        editKeyOption: false,
      });
    } else {
      this.setState({
        appKey: nextProps?.appKey,
        originalAppKey: nextProps?.appKey,
        editKeyOption: true,
      });
    }
    if(this.props?.appConfigViewOnly !== nextProps?.appConfigViewOnly){
      this.setState({viewOnly:nextProps?.appConfigViewOnly })
    }
  }
  render() {
    const {planFeature} = this.props?.currentOrg || {};

   const { viewOnly } = this.state
    return (
      <div className="api-wrapper">
        <Row>
          <Col sm={24}>
            {planFeature?.api === 0 && (
              <Alert style={{marginBottom: 10}} message={apiPlanError} type="error" showIcon />
            )}
            <InfoBox
              type="info"
              marginBottom={ 18 }
              content={
                <>
                  Access your data directly on our servers with the Data access API.
                  Learn more about using our public API{' '}
                  <a
                    href="https://developer.uxcam.com/docs/data-access-api"
                    style={{ textDecoration: 'underline' }}
                    target="_blank"
                    rel="noreferrer"
                  >
                    here
                  </a>
                  .
                </>
              }
            />
            <div
               className={ planFeature?.api === 0 ? 'disable-overlay' : ''}
            >
              <div className="api-form">
                <div className="form-item form-label">
                  App ID{' '}
                  <Tooltip title="Unique identifier of your app to be provided as an argument in the API call.">
                    <InfoCircleOutlined />
                  </Tooltip>
                </div>
                <div className="form-item">
                  <p>{this.props.urlQuery.app || ''}</p>
                </div>
                <div className="form-item">
                  <CopyToClipboard
                    text={this.props.urlQuery.app}
                    onCopy={() => {}}
                  >
                    <Tooltip
                      placement="topLeft"
                      title={'Copy App ID'}
                      arrowPointAtCenter
                    >
                      <Button
                        onClick={(e) => this.copy(e)}
                        size={'small'}
                        style={{
                          border: 0,
                        }}
                      >
                        <CopyOutlined style={{ marginLeft: -4 }} />
                      </Button>
                    </Tooltip>
                  </CopyToClipboard>
                </div>
              </div>

              <div className="api-form">
                <div className="form-item form-label">
                  API Key{' '}
                  <Tooltip title="A code of your choice that serves as a password for accessing your app data and has to be provided in the API call.Please note that the API key and App key allow accessing your data on UXCam’s servers,even without access to the dashboard.">
                    <InfoCircleOutlined />
                  </Tooltip>
                </div>
                <div className="form-item">
                  <Input
                    ref={this.publicApiRef}
                    placeholder="Enter API key"
                    defaultValue={this.props.appKey || ''}
                    value={this.state.appKey || ''}
                    disabled={
                      !this.state.editKeyOption ||
                      ( planFeature?.api === 0) || viewOnly
                    }
                    onChange={this.onApiKeyChange}
                  />
                </div>
                <div className="form-item">
                  {!this.state.editKeyOption && (
                    <Button
                      onClick={() => this.editKey(true)}
                      icon={<EditOutlined />}
                      style={{ border: '0' }}
                      disabled={ planFeature?.api === 0 || viewOnly}
                    />
                  )}
                  {!this.state.editKeyOption && (
                    <CopyToClipboard
                      text={this.state.originalAppKey}
                      onCopy={() => {}}
                    >
                      <Tooltip
                        placement="topLeft"
                        title={'Copy API key'}
                        arrowPointAtCenter
                      >
                        <Button
                          onClick={(e) => this.copy(e)}
                          size={'small'}
                          style={{
                            border: 0,
                          }}
                        >
                          <CopyOutlined style={{ marginLeft: -4 }} />
                        </Button>
                      </Tooltip>
                    </CopyToClipboard>
                  )}
                  {this.state.editKeyOption && !viewOnly && (
                    <Button
                      onClick={this.savePublicApiKey}
                      disabled={
                        !this.state.appKey ||
                        this.state.appKey === this.state.originalAppKey || viewOnly
                      }
                      type="primary"
                    >
                      Save
                    </Button>
                  )}
                  {this.state.editKeyOption && this.state.appKey && (
                    <Button onClick={this.cancelPublicApiKey}>Cancel</Button>
                  )}
                </div>
              </div>
              <div className="api-footer">
                {this.state.editKeyOption && !viewOnly && (
                  <Button
                    onClick={this.generateUUID}
                    icon={<RetweetOutlined />}
                    disabled={planFeature?.api === 0}
                  >
                     Generate API Key

                  </Button>
                )}
              </div>
              {this.state.appKey && (
                <div className="api-form">
                  <div className="form-item form-label">
                    Public session API{' '}
                    {/* <Tooltip title='Text to be added'>
                      <Icon type='info-circle' />
                    </Tooltip> */}
                  </div>
                  <div
                    className={`form-item session-api`}
                  >
                    <a
                      href={`${_pURL}/session?appid=${this.props.urlQuery.app}&apikey=${this.state.appKey}&page=1`}
                      target="_blank"
                    >{`${_pURL}/session?appid=${this.props.urlQuery.app}&apikey=${this.state.appKey}&page=1`}</a>
                  </div>
                </div>
              )}
              {this.state.appKey && (
                <div className="api-form">
                  <div className="form-item form-label">
                    Public user API{' '}
                  </div>
                  <div
                    className='form-item session-api'
                  >
                    <a
                      href={`${_pURL}/user?appid=${this.props.urlQuery.app}&apikey=${this.state.appKey}&page=1`}
                      target="_blank"
                    >{`${_pURL}/user?appid=${this.props.urlQuery.app}&apikey=${this.state.appKey}&page=1`}</a>
                  </div>
                </div>
              )}
            </div>
          </Col>
        </Row>
        <style>{`
          .api-wrapper{
            min-height: 200px;
          }
          .disable-overlay{
            margin-top: 16px;
            opacity: 0.4;
          }

          .api-form{
            display: flex;
          }
          .api-form .form-item{
            margin-right: 10px;
            margin-bottom: 10px;
            line-height: 33px;
          }
          .api-form .form-item .ant-btn{
            margin-right: 10px;
            height: 28px;
            text-transform: none;
          }
          .api-form .form-item .ant-input{
            min-width: 300px;
            border-color: #dddddd;
          }
          .api-footer{
            margin-left: 110px;
          }
          .api-footer .ant-btn{
            border: 1px solid #161E35;
          }
          .api-footer .ant-btn:hover{
            border-color: #5D97FF;
          }
          .api-form .form-item.form-label{
            width: 100px;
          }
          .api-wrapper hr{
            border-color: #cad1e8;
            border-top: 0;
            margin-bottom: 20px;
            margin-top: 30px;
           }
          `}</style>
      </div>
    );
  }
}
function mapStateToProps(state) {
  return {
    currentOrg: state.currentOrgReducer,
    urlQuery: state.urlReducer,
  };
}

const mapDispatchToProps = dispatch => ({
  trackPageViews: (profileArgs, events) => dispatch(trackPageViews(profileArgs,events))
})

export default connect(mapStateToProps, mapDispatchToProps)(PublicApiAccess);
