const positiveNumberRule = {
  validator(rule, value) {
    if (!value || (Number.isInteger(Number(value)) && Number(value) > 0)) {
      return Promise.resolve();
    }
  
    return Promise.reject(new Error('Only positive integers are allowed.'));
  },
};

const fractionalPercentageRule = {
  validator(rule, value) {
    const numValue = Number(value);

    // Check if value is a valid number
    if (!value || Number.isNaN(numValue)) {
      return Promise.reject(new Error('Value required'));
    }

    // Check if value is positive
    if (numValue <= 0) {
      return Promise.reject(new Error('Value must be greater than 0'));
    }

    // Check if value doesn't exceed 100
    if (numValue > 100) {
      return Promise.reject(new Error('Value cannot exceed 100'));
    }

    // Check if value has at most 1 decimal place
    const decimalPart = value.toString().split('.')[1];
    if (decimalPart && decimalPart.length > 1) {
      return Promise.reject(new Error('Only 1 decimal place allowed'));
    }

    // Check minimum value of 0.1
    if (numValue < 0.1) {
      return Promise.reject(new Error('Minimum value is 0.1'));
    }

    return Promise.resolve();
  },
};

