import React from 'react'
// eslint-disable-next-line import/no-extraneous-dependencies
import { useFormContext } from 'react-hook-form'
import styled from 'styled-components'
import { theme } from 'theme'
import { UFCInput } from 'uxcam-frontend-components'
import { InfoIcon } from 'components/svg_files'
import { PageRuleFormProps } from '../RuleBuilder'
import { extractUrlParts } from '../utils'
import PathItem from './PathItem'

const PathContainer = styled.div`
	display: flex;
	flex-wrap: wrap;
	gap: ${ theme.spacing( 1.5, 2.5 ) };
`

const Container = styled.div`
	display: flex;
	flex-direction: column;
	gap: ${ theme.spacing( 1.25 ) };
`

const Warning = styled.div`
	font-size: ${ theme.fontSize( 1.2 ) };
	color: ${ theme.colors.error500.toString() };
`

const Hint = styled.div`
	display: flex;
	align-items: center;
	gap: ${ theme.spacing( 1.25 ) };
	background: ${ theme.colors.surface05.toString() };
	border-radius: 4px;
	padding: ${ theme.spacing( 0.625, 1 ) };
	line-height: 14px;
	font-size: ${ theme.fontSize( 1.2 ) };
	color: ${ theme.colors.surface400.toString() };
`

const PathEditor: React.FC<{
	allParameters: string[];
	getPopupContainer: () => HTMLElement;
}> = ( {
	allParameters,
	getPopupContainer,
} ) => {

	const {
		watch,
		setValue,
	} = useFormContext<PageRuleFormProps>()

	const originalUrl = watch( 'originalUrl' )
	const pattern = watch( 'pattern' )

	const containsHash = React.useMemo( () => {
		try {
			const parsedUrl = new URL( originalUrl )
			const url = new URL( `${ parsedUrl.origin }/${ pattern }` )

			return url.hash.length > 0
		} catch ( e ) {
			return false
		}
	}, [ originalUrl, pattern ] )

	const hashSeparator = React.useMemo( () => {
		try {
			const parsedUrl = new URL( originalUrl )
			// Mirror the original route's separator: include the leading '/' when
			// the path has a trailing slash before '#' (e.g. '/#/' vs '#/').
			const leadingSlash = parsedUrl.pathname.endsWith( '/' ) && parsedUrl.pathname !== '/' ? '/' : ''
			const hashPrefix = parsedUrl.hash.startsWith( '#/' ) ? '#/' : '#'
			return `${ leadingSlash }${ hashPrefix }`
		} catch ( e ) {
			return '#'
		}
	}, [ originalUrl ] )

	const [ , displayParts ] = React.useMemo( () => {
		return extractUrlParts( originalUrl, containsHash )
	}, [ originalUrl, containsHash ] )

	const hashStartIndex = React.useMemo( () => {
		return displayParts.indexOf( '#' )
	}, [ displayParts ] )

	const displayPartsRef = React.useRef( displayParts )
	React.useEffect( () => {
		displayPartsRef.current = displayParts
	}, [ displayParts ] )

	const hashStartIndexRef = React.useRef( hashStartIndex )
	React.useEffect( () => {
		hashStartIndexRef.current = hashStartIndex
	}, [ hashStartIndex ] )

	const handlePartChange = React.useCallback( ( index: number, newValue?: string ) => {
		const parsed = new URL( originalUrl )
		const newUrl = new URL( `${ parsed.origin }/${ pattern }` )
		const pathPatternParts = newUrl.pathname.slice( 1 ).split( '/' ).filter( ( part ) => part )
		const hashPatternParts = newUrl.hash ? newUrl.hash.slice( 1 ).split( '/' ).filter( ( part ) => part ) : []
		const currentHashStart = hashStartIndexRef.current

		if ( currentHashStart === -1 ) {
			pathPatternParts[ index ] = newValue || displayPartsRef.current[ index ]
			setValue( 'pattern', pathPatternParts.join( '/' ) )
			return
		}

		const newParts = [ ...pathPatternParts, '#', ...hashPatternParts ]
		newParts[ index ] = newValue || displayPartsRef.current[ index ]
		const pathParts = newParts.slice( 0, currentHashStart )
		const hashParts = newParts.slice( currentHashStart + 1 )
		const hashPrefix = newUrl.hash.startsWith( '#/' ) ? '#/' : '#'
		const hashSegment = hashParts.length ? `${ hashPrefix }${ hashParts.join( '/' ) }` : '#'
		setValue( 'pattern', `${ pathParts.join( '/' ) }${ hashSegment }` )
	}, [ originalUrl, pattern, setValue ] )

	const patternParts = React.useMemo( () => {
		if ( !pattern ) {
			return [] as string[]
		}

		try {
			const [ pathPattern, ...hashRest ] = pattern.split( '#' )
			const pathParts = pathPattern.split( '/' ).filter( ( part ) => part )

			if ( hashRest.length === 0 ) {
				return pathParts
			}

			const hashPattern = hashRest.join( '#' )
			const hashParts = hashPattern.split( '/' ).filter( ( part ) => part )
			return [ ...pathParts, '#', ...hashParts ]
		} catch ( e ) {
			return [] as string[]
		}
	}, [ pattern ] )
	const displayPlaceholder = !displayParts.length

	const selectMoreDisabled = React.useMemo( () => {
		return patternParts.filter(
			part => part === '*' || part.startsWith( ':' ) || part === '***'
		).length >= 5;
	}, [ patternParts ] )

	return displayPlaceholder ? (
		<UFCInput
			disabled
		/>
	) : (
		<Container>
			<PathContainer>
				{
					displayParts.map( ( part, index ) => {
						if ( part === '#' ) {
							return null
						}

						const patternPart = patternParts[ index ] || ''
						const selected = patternPart === '*' || patternPart.startsWith( ':' ) || patternPart === '***'
						const nextIsHash = displayParts[ index + 1 ] === '#'
						const separator = nextIsHash ? hashSeparator : '/'

						return (
							<PathItem
								// eslint-disable-next-line react/no-array-index-key
								key={ index }
								patternPart={ patternPart }
								part={ part }
								disabled={ !selected && selectMoreDisabled }
								isHash={ false }
								getPopupContainer={ getPopupContainer }
								index={ index }
								handlePartChange={ handlePartChange }
								allParameters={ allParameters }
								isLast={ index === displayParts.length - 1 }
								separator={ separator }
							/>
						)
					} )
				}
			</PathContainer>
			{
				selectMoreDisabled ? (
					<Warning>
						You can pick up to 5 unique parameters per URL.
					</Warning>
				) : null
			}
			<Hint>
				<InfoIcon />
				<span>
					Named parameter will be saved as page properties that can be used on page analytics.
				</span>
			</Hint>
		</Container>
	) 
}

export default React.memo( PathEditor )