/* eslint-disable no-underscore-dangle */
import React, { useState, useRef, useEffect } from 'react';
import { Button, Modal, Form, Input, message } from 'antd';
import styled from 'styled-components';
import { useSelector, useDispatch } from 'react-redux';
import { trackPageViews } from 'redux/actions/trackingReport';
import { useQueryClient } from 'react-query';
import { useRouter } from 'next/router';

import { useDeleteApp } from 'components/features/setting/useSettingPage';
import { DeleteIconSvg } from '../SvgIcon';

const ModalWrap = styled(Modal)`
  .ant-modal-content {
    padding: 20px 20px 0 20px;
    border-radius: 8px;
  }
  .ant-modal-body {
    padding: 20px;
  }
  .ant-modal-footer {
    border-top: none;
  }
`;

const ModalHeaderWrap = styled.div`
  display: flex;
  justify-content: flex-start;
  margin-bottom: 15px;
`;

const TextTitle = styled.div`
  font-size: 18px;
  font-weight: 500;
  white-space: pre-wrap;
`;

const InputWrap = styled(Input)`
  background: #ffffff;
  margin: 10px 0;
`;
const CircleButton = styled(Button)`
  margin: 0 8px;
  color: #5d97ff;
  text-align: center;
  border-color: #dee8ff;
  width: 42px;
  height: 41px;
`;

const PrimaryModalButton = styled(Button)`
  font-size: 14px;
  background: #f4584c;
  width: 172px;
  height: 47px;
  padding: 0;
`;

const SecondaryModalButton = styled(PrimaryModalButton)`
  background: #ffffff;
  color: #5d97ff;
  border: 1px solid #5d97ff;
  margin-right: 15px;
  width: 145px;
  padding: 0;
  :hover {
    background: #ffffff;
    color: #5d97ff;
    border: 1px solid #5d97ff;
  }
`;

const FormButton = styled.div`
  display: flex;
  justify-content: end;
`;

const StyledParagraph = styled.p`
  margin-bottom: 0;
  color: #161e35;
`;

const FormItem = Form.Item;

const AppDeleteModalForm = ({ appDetail }) => {
  const [modalVisible, setModalVisible] = useState(false);
  const router = useRouter();

  const { name: applicationName, _id: applicationId } = appDetail;

  const queryClient = useQueryClient();
  const data = { name: applicationName };

  const { refetch: deleteApp, isLoading } = useDeleteApp(data, applicationId);

  const [form] = Form.useForm();
  const inputRef = useRef(null);

  const {
    currentOrgReducer: { orgId, organizationName, profileReducer: profile },
    currentAppReducer: currentApp,
  } = useSelector((state) => state);
  const dispatch = useDispatch();

  const handleDestroyClose = () => {
    form.resetFields();
  };
  const handleCancel = () => {
    setModalVisible(false);
    form.resetFields();
  };

  const queryKey = `appList_${orgId}`;

  const onFinish = () => {
    deleteApp().then((res) => {
      if (res?.data?.error) {
        message.error(res?.data?.error?.message);
        return;
      }
      if (res?.data?.message) {
        message.success(res?.data?.message);
        dispatch(trackPageViews(null, {
          eventName: 'wa_delete_app',
          eventProperty: {
            email: profile?.email || '',
            appId: applicationId,
            appName: applicationName,
            appType: appDetail?.appType || '',
            region: appDetail?.region || '',
          }
        }));
        handleCancel();
        if (applicationId === currentApp?._id) {
          router.reload();
        } else {
          queryClient.setQueryData(queryKey, (applist) =>
            applist.filter((app) => app?._id !== applicationId)
          );
          queryClient.invalidateQueries('profileInfo');
          queryClient.invalidateQueries(`teamList${orgId}`);
          queryClient.invalidateQueries(`total_apps_${orgId}`);
        }
      }
    });
  };

  const handleModalOpen = () => {
    setModalVisible(true);
  };

  useEffect(() => {
   const timer = setTimeout(() => {
      modalVisible && inputRef?.current && inputRef?.current.focus();
    }, 500);

    return () => {
      clearTimeout(timer)
    }
  }, [modalVisible, inputRef?.current]);

  return (
    <>
      <CircleButton shape="circle" onClick={() => handleModalOpen()}>
        <DeleteIconSvg />
      </CircleButton>

      <ModalWrap
        visible={modalVisible}
        onCancel={handleCancel}
        closable={false}
        destroyOnClose={handleDestroyClose}
        footer={[null]}
        width={609}
      >
        <Form form={form} onFinish={onFinish} requiredMark={false}>
          <>
            <ModalHeaderWrap>
              <TextTitle>Delete {appDetail?.name}</TextTitle>
            </ModalHeaderWrap>
            <StyledParagraph>
              {`This app and all associated analytics data will be permanently
              removed from ${organizationName}.`}
            </StyledParagraph>
            <StyledParagraph>This action cannot be undone.</StyledParagraph>
            <FormItem
              name="name"
              rules={[
                {
                  required: true,
                  message: 'Please enter your app name',
                },
                () => ({
                  validator(_, value) {
                    if (!value || applicationName === value) {
                      return Promise.resolve();
                    }

                    return Promise.reject(
                      new Error(
                        `The name you entered doesn’t match the name of the app`
                      )
                    );
                  },
                }),
              ]}
            >
              <InputWrap
                ref={inputRef}
                placeholder="Enter the app name to confirm the deletion"
              />
            </FormItem>
          </>
          <FormButton>
            <SecondaryModalButton
              key="link"
              type="secondary"
              onClick={() => handleCancel()}
            >
              Cancel
            </SecondaryModalButton>

            <PrimaryModalButton
              loading={isLoading}
              type="primary"
              key="submit"
              htmlType="submit"
              danger
            >
              Delete
            </PrimaryModalButton>
          </FormButton>
        </Form>
      </ModalWrap>
    </>
  );
};

export default AppDeleteModalForm;
