import React, { useCallback, useEffect, useState, useMemo } from 'react';
import { DeleteOutlined } from '@ant-design/icons';
import { Form, Input, Select } from 'antd';
import styled from 'styled-components';

import {
  StyledButton,
  StyledRuleButton,
  StyledRuleNumber,
  StyledFormItem,
} from '../RecordingSettingStyles';

import { InfoLogMessage } from './common';

import DebounceSearch from '../DebounceSearch';
import { useRenamedScreenOptions } from '../utils';

const FormItem = Form.Item;
const InputGroup = Input.Group;

const StyledExceptionMain = styled.div`
  margin-bottom: 8px;
`;

const StyledExceptionDelete = styled(StyledButton)`
  position: absolute;
  top: -5px;
  right: 0;
`;

const StyledResultBox = styled.div`
  padding 5px 0 0 20px;

  .ant-form-item {
    margin-bottom: 0;
  }
  .ant-form-item-has-error {
    margin-bottom: 0 !important;
  }
`;

const ExceptionScreenFormItem = styled(StyledFormItem)`
  width: ${({ isblur }) => (isblur ? '50%' : '70%')};
  .ant-select-selector {
    border-radius: 0 2px 2px 0 !important;
    border: 1px solid #ecebec !important;
  }
  .ant-select-selection-item {
    color: #5b6d89;
  }
`;
const ExceptionBlurFormItem = styled(StyledFormItem)`
  display: flex;
  width: 30%;
  .ant-select-selector {
    border-radius: 2px 0 0 2px !important;
    border: 1px solid #ecebec !important;
  }
  .ant-select-selection-item {
    color: #5b6d89;
  }
`;

const BlurRadiusFormItem = styled(StyledFormItem)`
  color: #5b6d89;
  width: 100px;
  .ant-form-item-label {
    padding-bottom: 0;
  }
`;
const AddMultipleFormItem = styled(FormItem)`
  margin-bottom: 0;
  .ant-btn {
    border-color: #5d97ff;
    color: #5d97ff;
    position: absolute;
    right: 0;
    bottom: 20px;
  }
  .ant-form-item-control-input {
    min-height: 0;
  }
`;

// new css
const StyledCompactFormItem = styled(FormItem)``;

const StyledInputGroup = styled(InputGroup)`
  .ant-select-selector {
    border-radius: 0;
  }
`;

const StyledInfoParagraph = styled.p`
  font-weight: 400;
  font-size: 12px;
  color: #e81414;
  line-height: normal;
  margin-top: 8px;
  margin-bottom: 0;
`;

const ExceptionField = ({
  rulesOptions,
  form,
  disablefield,
  screenRecordingRules,
}) => {
  const { getRenamedScreenName } = useRenamedScreenOptions();

  const handleRuleChange = (name) => (value) => {
    form.setFields([
      {
        name: ['videoPrivacy', 'exceptions', `${name}`, 'config', 'radius'],
        value: value === 'blur' ? 10 : undefined,
      },
    ]);
  };
  const exceptionRule = Form.useWatch(['videoPrivacy', 'exceptions'], form);
  const videoPrivayValues = form.getFieldValue(['videoPrivacy', 'exceptions']);
  
  const optionToFilter = useMemo(
    () => (screenRecordingRules === 'occlude' ? 'record' : 'occlude'),

    [screenRecordingRules]
  );

  const hasRecordOrOccludeException = useMemo(
    () =>
      exceptionRule?.length &&
      exceptionRule?.findIndex(
        (exception) =>
          exception?.rule === 'record' || exception?.rule === 'occlude'
      ) !== -1,

    [exceptionRule]
  );

  const hasBlurRadius = useCallback(
    (value) =>
      exceptionRule?.filter((exception) => exception?.config?.radius === value)
        ?.length > 1,
    [exceptionRule]
  );

  const handleRuleOption = useCallback(
    (indexField) =>
      exceptionRule?.length &&
      exceptionRule[indexField]?.rule &&
      hasRecordOrOccludeException
        ? rulesOptions.filter((rule) => rule?.value !== optionToFilter)
        : rulesOptions,

    [exceptionRule, rulesOptions]
  );

  const handleDuplicate = useCallback(
    (screen) =>
      exceptionRule.filter(
        (rule) => rule?.screens?.length && rule?.screens.includes(screen?.value)
      ),
    [exceptionRule]
  );

  const handleConditionalValue = useCallback(
    (name) =>
      exceptionRule?.length &&
      exceptionRule.filter((data) => data)?.length &&
      exceptionRule[name] &&
      exceptionRule[name]?.rule === 'blur',
    [exceptionRule]
  );

  const handleAddButton = async (fields, addException) => {
    const values = await form.validateFields([
      ['videoPrivacy', 'exceptions', fields?.length - 1, 'screens'],
      ['videoPrivacy', 'exceptions', fields?.length - 1, 'rule'],
    ]);
    values && addException();
  };

  const handleSelect = (val, name) => {
    const selectedScreen = val?.length
      ? val.map(
          (screen) =>
            screen?.value
        )
      : [];
    form.setFields([
      {
        name: ['videoPrivacy', 'exceptions'],
        touched: true,
      },
      {
        name: ['videoPrivacy', 'exceptions', `${name}`, 'screens'],
        value: selectedScreen,
        touched: true,
      },
    ]);
    form.validateFields(['videoPrivacy', 'exceptions']);
  }

  useEffect(() => {
    exceptionRule?.length &&
      exceptionRule?.map((_, index) =>
        form.validateFields([
          ['videoPrivacy', 'exceptions', index, 'config', 'radius'],
        ])
      );
  }, [exceptionRule]);

  return (
    <StyledResultBox>
      <Form.List name={['videoPrivacy', 'exceptions']}>
        {(fields, { add: addException, remove: removeException }) => (
          <>
            {(screenRecordingRules !== 'blur' ||
              (screenRecordingRules === 'blur' && fields?.length <= 1)) && (
              <AddMultipleFormItem>
                <StyledRuleButton
                  onClick={() =>
                    !disablefield && handleAddButton(fields, addException)
                  }
                >
                  Add rule
                </StyledRuleButton>
              </AddMultipleFormItem>
            )}
            {fields.map(({ key, name }) => (
              <StyledExceptionMain key={key}>
                <StyledCompactFormItem>
                  <StyledInputGroup compact>
                    <ExceptionBlurFormItem
                      name={[name, 'rule']}
                      rules={[
                        { required: true, message: 'Please select rule' },
                      ]}
                      label="Rule"
                    >
                      <Select
                        placeholder="Select rule"
                        showArrow
                        options={handleRuleOption(name - 1)}
                        onChange={handleRuleChange(name)}
                        disabled={disablefield}
                      />
                    </ExceptionBlurFormItem>

                    {handleConditionalValue(name) && (
                      <BlurRadiusFormItem
                        name={[name, 'config', 'radius']}
                        rules={[
                          {
                            required: true,
                            message: 'Blur radius required',
                          },
                          () => ({
                            validator(_, value) {
                              if (!hasBlurRadius(value)) {
                                return Promise.resolve();
                              }

                              return Promise.reject(
                                new Error(
                                  'Each rule should have unique blur radius.'
                                )
                              );
                            },
                          }),
                        ]}
                        label=" "
                      >
                        <StyledRuleNumber
                          controls={false}
                          min={1}
                          addonAfter="dp"
                          disabled={disablefield}
                        />
                      </BlurRadiusFormItem>
                    )}
                    <ExceptionScreenFormItem
                      name={[name, 'screens']}
                      rules={[
                        {
                          required: true,
                          message: 'Please select any screen',
                        },
                      ]}
                      isblur={handleConditionalValue(name) ? 1 : 0}
                      label="Screens"
                    >
                      <DebounceSearch
                        attribute="screen"
                        placeholder="Select screen"
                        disabled={disablefield}
                        defaultValues={
                          videoPrivayValues[name]?.screens?.map(
                            (screen) => ({
                              label: getRenamedScreenName(screen),
                              value: screen,
                              key: screen,
                            })
                          )
                        }
                        handleSelect={(val) => {
                          handleSelect(val, name);
                        }}
                      />
                    </ExceptionScreenFormItem>

                    {handleConditionalValue(name) && (
                      <InfoLogMessage 
                        title={
                          <>
                          Blur will apply to the app versions with the SDKs starting from 3.6.0. 
                          On the app versions with the earlier SDKs, the screens will be occluded. {' '} 
                          <a
                            target='_blank'
                            href='https://developer.uxcam.com/docs/screen-blurring'>Learn more</a>
                          {' '} about the SDKs supporting blur on different frameworks.
                          </>
                        }
                      />
                    )}
                  </StyledInputGroup>
                  <StyledExceptionDelete>
                    <DeleteOutlined
                      onClick={() => !disablefield && removeException(name)}
                    />
                  </StyledExceptionDelete>
                </StyledCompactFormItem>
              </StyledExceptionMain>
            ))}
          </>
        )}
      </Form.List>
    </StyledResultBox>
  );
};

export default ExceptionField;
