import React from 'react';
import { useSelector } from 'react-redux';
import { Input, Select } from 'antd';
import styled from 'styled-components';

import TeammateDeleteButton from './TeammateDeleteButton';
import TeammateModalForm from './TeammateModalForm';

import { useSettingPage } from '../context';
import {
  useFetchAllAppListById,
  useFetchActiveSubscription,
  useFetchTeamList,
} from '../../useSettingPage';

const { Option } = Select;

const TeamExtraWrap = styled.div`
  display: flex;
  gap: 0 15px;
`;

const TeamSeatWrap = styled.span`
  background: #f5f5f5;
  height: 36px;
  padding: 8px 10px;
  border-radius: 36px;
  font-size: 14px;
  font-weight: 400;
  color: #161e35;
  text-align: center;
  width: 100%;
  flex-basis: 100%;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  max-width: fit-content;
`;

const InputWrapper = styled(Input)`
  height: 36px;
  background: #ffffff;
  border: 1px solid #c0cad9;
  border-radius: 4px;
  align-items: center;
  padding: 10px 15px;
`;

const StyledAppDiv = styled.div`
  white-space: nowrap;
  display: flex;
  align-items: center;
  .ant-select {
    padding: 0 5px;
  }

  .ant-select .ant-select-dropdown {
    border-radius: 8px;
  }

  .ant-select .ant-select-selector {
    border: none;
    padding: 0;
    color: #161e35;
    &:hover{
      .ant-select-selection-placeholder {
        color: #5d97ff;
      }
    }
  }


  .ant-select-single .ant-select-selector .ant-select-selection-item {
    padding: 0 1px;
    margin-top: 4px;
  }
  .ant-select-selection-placeholder {
    color: #161e35;
    text-decoration: underline;
    text-decoration-style: dashed;  
    text-decoration-color: #8a99b1;  
    text-underline-offset: 6px;
  }

  .ant-select-clear {
    top: 40%;
    right: -8px;
  }
`;

export const AppListContent = () => {
  const { setSelectedApp } = useSettingPage();

  const {
    currentOrgReducer: { orgId },
  } = useSelector((state) => state);

  const handleAppChange = (value) => {
    setSelectedApp(value);
  };

  const { isLoading, data: appList } = useFetchAllAppListById(orgId);

  return (
    <StyledAppDiv>
      <Select
        showArrow={false}
        onChange={handleAppChange}
        dropdownStyle={{
          minWidth: '200px',
          maxHeight: '250px',
          overflowY: 'auto',
        }}
        allowClear
        placeholder="Apps"
        loading={isLoading}
      >
        {appList?.length > 0 &&
          appList.map((appItem) => (
            <Option key={appItem[`_id`]}>{appItem?.name}</Option>
          ))}
      </Select>
    </StyledAppDiv>
  );
};

const TeamExtraContent = () => {
  const { selectedTeamList, setSearchValue } = useSettingPage();

  const {
    currentOrgReducer: { orgId },
  } = useSelector((state) => state);
  const { data: activeSubscription } = useFetchActiveSubscription(orgId);

  const { data: teamDataList } = useFetchTeamList(orgId);

  const memberCount = activeSubscription?.planLimit?.teamMemberCount;
  const totalSelectedMember = selectedTeamList?.length;

  const handleSearch = (e) => {
    const { value } = e.target;
    setSearchValue(value?.toLowerCase()?.trim());
  };

  return (
    <TeamExtraWrap>
      {totalSelectedMember === 0 ? (
        <TeamSeatWrap>{`${teamDataList?.length || ''} of ${
          memberCount || ''
        } seats used`}</TeamSeatWrap>
      ) : (
        <TeammateDeleteButton
          totalSelectedMember={totalSelectedMember}
          type="multiple"
          selectedTeamList={selectedTeamList}
        />
      )}
      <InputWrapper placeholder="Search teammates " onChange={handleSearch} />
      <TeammateModalForm />
    </TeamExtraWrap>
  );
};

export default TeamExtraContent;
