import React from 'react';
import { Input } from 'antd';
import styled from 'styled-components';

import AppAddModalForm from './AppAddModalForm';

import { useSettingPage } from '../context';

const TeamExtraWrap = styled.div`
  display: flex;
  gap: 0 15px;
`;

const InputWrapper = styled(Input)`
  height: 36px;
  background: #ffffff;
  border: 1px solid #c0cad9;
  border-radius: 4px;
  align-items: center;
  padding: 10px 15px;
`;

const TeamExtraContent = () => {
  const { setSearchAppName } = useSettingPage();

  const handleSearch = (e) => {
    const { value } = e.target;
    setSearchAppName(value?.toLowerCase()?.trim());
  };

  return (
    <TeamExtraWrap>
      <InputWrapper placeholder="Search apps " onChange={handleSearch} />
      <AppAddModalForm />
    </TeamExtraWrap>
  );
};

export default TeamExtraContent;
