const EmptyRef: MockDefinition[] = []

const PageDefinition: React.FC<{
	status: 'active' | 'archive',
	isManager: boolean,
}> = ( {
	status,
	isManager,
} ) => {

	const {
		query,
		pathname,
		push,
	} = useRouter()

	const [ archiveRuleId, setArchiveRuleId ] = React.useState<{ id: string, name: string } | null>()

	const ruleId = React.useMemo( () => {
		const queryRule = query.rule_id
		if ( queryRule ) {
			return queryRule as string
		}
		const url = query.url as string
		const searchParams = new URLSearchParams( url.split( '?' )[1] || '?' )
		return searchParams.get( 'rule_id' ) as string || null
	}, [ query ] )

	const fetchFn = React.useCallback( async ( status: string ) => {
		const { app } = query
		return ( await fetch( `${ process.env.SUBSCRIPTION_URL }/app/${ app }/page-definition-setting/?status=${ status }`, {
			credentials: 'include',
		} )
			.then( ( res ) => res.json() as Promise<{
				data: MockDefinition[]
				success: boolean
				message: string
			}> ) ).data.map( ( item ) => ( {
				...item,
				id: item._id,
			} ) )
	}, [ query ] )

	const activeFetchFn = React.useCallback( async () => {
		return fetchFn( 'active' )
	}, [ fetchFn ] )
	const archivedFetchFn = React.useCallback( async () => {
		return fetchFn( 'archive' )
	}, [ fetchFn ] )

	const rulesKey = useMemo( () => {
		return [ query.app, 'page-definitions', status ]
	}, [ status, query.app ] )

	const activeRulesKey = useMemo( () => {
		return [ query.app, 'page-definitions', 'active' ]
	}, [ query.app ] )
	const archivedRulesKey = useMemo( () => {
		return [ query.app, 'page-definitions', 'archive' ]
	}, [ query.app ] )

	const activeResult = useQuery( activeRulesKey, {
		queryFn: activeFetchFn,
		suspense: true,
		staleTime: Infinity,
	} )
	const archivedResult = useQuery( archivedRulesKey, {
		queryFn: archivedFetchFn,
		suspense: true,
		staleTime: Infinity,
	} )

	const result = status === 'active' ? activeResult : archivedResult

	const allParameters = useMemo( () => {
		return Array.from(
			new Set(
				( activeResult.data || [] )
				.concat( archivedResult.data || [] )
				.reduce( ( acc, rule ) => {
					return acc.concat( extractParamsFromPattern( rule.patternUrl ) )
				}, [] as string[] )
			)
		)
	}, [ activeResult.data, archivedResult.data ] )

	const resultRef = React.useRef( result )
	React.useEffect( () => {
		resultRef.current = result
	}, [ result ] )

	const dataRaw = result.data || EmptyRef

	const isEmpty = dataRaw.length === 0
	const showDataPlaceholder = isEmpty && status === 'active'

	const data = useMemo( () => {
		if ( !showDataPlaceholder ) {
			return dataRaw
		}
		return dataRaw.concat( {
			_id: '',
			order: 0,
			patternUrl: (
				<TablePlaceholderText>
					{ 'website/{category}/products/{productID}/details' }
				</TablePlaceholderText>
			) as unknown as string,
			pageName: (
				<TablePlaceholderText>
					Product details page
				</TablePlaceholderText>
			) as unknown as string,
			createdOn: '',
			updatedOn: '',
			createdByEmail: '',
		} )
	}, [ dataRaw, showDataPlaceholder ] )

	const dataRef = React.useRef( data )
	const activeRulesRef = React.useRef( activeResult )

	React.useEffect( () => {
		dataRef.current = data
	}, [ data ] )
	React.useEffect( () => {
		activeRulesRef.current = activeResult
	}, [ activeResult ] )

	const [ hash, setHash ] = React.useState( '' )
	const dispatch = useDispatch()

	React.useEffect( () => {
		// eslint-disable-next-line no-shadow
		const { hash } = window.location
		setHash( hash )
	}, [ query ] )

	React.useEffect(() => {
		if(hash === '#changelog'){
			dispatch(trackPageViews(null, {
				eventName: 'wa_page_definitions_view_changelog',
				track_type: 'event',
			}))
		}
	}, [ dispatch, hash ])

	const ruleBuilderOpen = useMemo( () => {
		return hash === '#rule-builder'
	}, [ hash ] )
	const changeLogOpen = useMemo( () => {
		return hash === '#changelog'
	}, [ hash ] )
	const testUrlOpen = useMemo( () => {
		return hash === '#test-url'
	}, [ hash ] )

	const handeBuilderClose = React.useCallback( () => {
		// eslint-disable-next-line @typescript-eslint/no-unused-vars, no-shadow
		const { rule_id: ruleId, ...rest } = query

		push( {
			pathname,
			query: {
				...rest,
			},
		}, `${ window.location.pathname }` )
	}, [ pathname, push, query ] )

	const handleTestClose = React.useCallback( () => {
		// eslint-disable-next-line @typescript-eslint/no-unused-vars, no-shadow
		const { url, ...rest } = query

		push( {
			pathname,
			query: {
				...rest,
			},
		}, `${ window.location.pathname }` )
	}, [ pathname, push, query ] )

	const reactQueryCache = useQueryClient()

	// eslint-disable-next-line no-shadow
	const rawHandleDragEnd = React.useCallback( ( result: MockDefinition[] ) => {
		const playload = {
			pageDefinitionSettings: result.map( ( rule, index ) => {
				return {
					_id: rule._id,
					order: index + 1,
				}
			} )
		}

		fetch( `${ process.env.SUBSCRIPTION_URL }/app/${ query.app }/page-definition-setting/update-order/`, {
			method: 'POST',
			body: JSON.stringify( playload ),
			headers: {
				'Content-Type': 'application/json',
			},
			credentials: 'include',
		} )
			.then( ( res ) => res.json() )
	}, [ query.app ] )

	const handleDragEndRefTimeout = React.useRef<ReturnType<typeof setTimeout>>()

	const handleDragEnd = React.useCallback( ( result: MockDefinition[] ) => {
		if ( handleDragEndRefTimeout.current ) {
			clearTimeout( handleDragEndRefTimeout.current )
		}
		handleDragEndRefTimeout.current = setTimeout( () => {
			rawHandleDragEnd( result )
		}, 500 )

		const orderMap = result.reduce( ( acc, rule, index ) => {
			acc[ rule._id ] = index + 1
			return acc
		}, {} as Record<string, number> )

		const data = dataRef.current.map( ( rule ) => {
			return {
				...rule,
				order: orderMap[ rule._id ],
			}
		} )
			.sort( ( a, b ) => a.order - b.order )

		// change the order in the cache
		reactQueryCache.setQueryData( rulesKey, data );

	}, [ rawHandleDragEnd, reactQueryCache, rulesKey ] )

	const handleNewRuleClick = React.useCallback( () => {
		push( {
			pathname,
			query: {
				...query,
				rule_id: 'new',
			},
		}, `${ window.location.pathname }?rule_id=new#rule-builder` )
		dispatch(trackPageViews(null, {
			eventName: 'wa_page_definitions_click_create_rule',
			track_type: 'event',
		}))
	}, [ pathname, push, query, dispatch] )

	const handleArchiveConfirm = React.useCallback( () => {
		if ( !archiveRuleId ) { return }
		
		const { app } = query
		fetch( `${ process.env.SUBSCRIPTION_URL }/app/${ app }/page-definition-setting/${ archiveRuleId.id }/`, {
			method: 'DELETE',
			credentials: 'include',
		} )
			.finally( () => {
				reactQueryCache.invalidateQueries( [ app, 'page-definitions', 'active' ] )
				reactQueryCache.invalidateQueries( [ app, 'page-definitions', 'archive' ] )
				setArchiveRuleId( null )
				dispatch(trackPageViews(null, {
					eventName: 'wa_page_definitions_archive_rule',
					track_type: 'event',
					eventProperty: {
						rule_id: archiveRuleId.id,
						rule_name: archiveRuleId.name,
					}
				}))
			} );
	}, [ query, reactQueryCache, archiveRuleId, dispatch ] )

	const handleArchiveClose = React.useCallback( () => {
		setArchiveRuleId( null )
	}, [] )

	return (
		<Content>
			<RuleBuilder
				open={ ruleBuilderOpen }
				onClose={ handeBuilderClose }
				ruleId={ ruleId }
				allParameters={ allParameters }
				activeRulesQueryRef={ activeRulesRef as React.MutableRefObject<UseQueryResult<unknown[]>> }
			/>
			<ArchiveConfirmation
				open={ Boolean( archiveRuleId ) }
				onConfirm={ handleArchiveConfirm }
				onClose={ handleArchiveClose }
			/>
			<TestUrl
				open={ testUrlOpen }
				onClose={ handleTestClose }
				rules={ activeResult.data || EmptyRef }
			/>
			<Changelog
				open={ changeLogOpen }
				onClose={ handeBuilderClose }
			/>
			<PageDefinitionNavContextProvider
				status={ status }
				onArchive={ setArchiveRuleId }
				isManager={ isManager }
			>
				<TableWrapper
					data-wrapper
					data-status={ status }
				>
					<DashboardTable
						columns={ Columns }
						data={ data }
						resizeMode="onEnd"
						draggable={ !showDataPlaceholder }
						onDragEnd={ handleDragEnd }
					/>
				</TableWrapper>
			</PageDefinitionNavContextProvider>
			{
				showDataPlaceholder ? (
					<Placeholder>
						<PlaceholderInner>
							<PageDefinitionPlaceholder />
							<PlaceholderTitle>
								Define your first page URL rule
							</PlaceholderTitle>
							<PlaceholderText>
								Replace long URLs with shorter page names for clearer reporting, and optionally name dynamic URL parts (like product IDs) for reporting and filtering. Note: Rules are not retroactive and apply only to future sessions.
							</PlaceholderText>
							{
								isManager ? (
									<Button
										variant="secondary"
										type="button"
										size="large"
										onClick={ handleNewRuleClick }
									>
										<PlusCircle />
										Create URL Rule
									</Button>
								) : (
									<Tooltip
										overlay="You don't have permission to create or edit page rules."
									>
										<span>
											<Button
												variant="secondary"
												type="button"
												size="large"
												disabled
											>
												<PlusCircle />
												Create URL Rule
											</Button>
										</span>
									</Tooltip>
								)
							}
						</PlaceholderInner>
					</Placeholder>
				) : null
			}
		</Content>
	)

}

const PageDefinitionLoader: React.FC = () => {
	const {
		query,
		pathname,
		push,
	} = useRouter()

	const dispatch = useDispatch()

	const [ status, setStatus ] = React.useState< 'active' | 'archive' >( 'active' )

	const handleNewRuleClick = React.useCallback( () => {
		push( {
			pathname,
			query: {
				...query,
				rule_id: 'new',
			},
		}, `${ window.location.pathname }?rule_id=new#rule-builder` )
		dispatch(trackPageViews(null, {
			eventName: 'wa_page_definitions_click_create_rule',
			track_type: 'event',
		}))
	}, [ dispatch, pathname, push, query ] )

	const handleOpenChangelog = React.useCallback( () => {
		push( {
			pathname,
			query: {
				...query,
			},
		}, `${ window.location.pathname }#changelog` )
	}, [ pathname, push, query ] )

	const selectedTab = React.useMemo( () => {
		return Tabs.find( ( tab ) => tab.key === status ) || Tabs[0]
	}, [ status ] )

	const handleTabChange = React.useCallback((tab: string) => {
		return () => {
			// eslint-disable-next-line @typescript-eslint/no-explicit-any
			setStatus(tab as any);
			dispatch(trackPageViews(null, {
				eventName: 'wa_page_definitions_list_filter',
				track_type: 'event',
				eventProperty: {
					filter: tab,
				},
			}))
		}
	}, [dispatch])

	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	const currentAppReducer = useSelector<IReduxState>( ( state ) => state.currentAppReducer ) as any
	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	const profileReducer = useSelector<IReduxState>( ( state ) => state.profileReducer ) as any

	const isManager = React.useMemo( () => {
		return ( currentAppReducer.role === 0 || currentAppReducer.role === 1 ) ||
			// eslint-disable-next-line @typescript-eslint/no-explicit-any
			[ 'owner', 'manger' ].includes( profileReducer.organization.find( ( org: any ) => org.$oid === currentAppReducer.orgId )?.role || 'user' )
	}, [ currentAppReducer, profileReducer ] )

	return (
		<StylesProvider>
			<Container>
				<div>
					<InfoContainer>
						<InfoIcon />
						<span>
							Easily organize your URLs into simple pages by creating rules that group dynamic URLs or define pages using URL fragments. <a href="https://help.uxcam.com/en/articles/10652702-define-pages-properties-to-simplify-data" target='_blank' rel='noreferrer'>Learn more.</a>
						</span>
					</InfoContainer>
				</div>
				<Header>
					<div>
						<Tooltip
							overlay={ selectedTab.tooltip }
							align={ {
								points: [ 'cl', 'cr' ]
							} }
						>
							<Dropdown
								selectorProps={ {
									selectedValue: selectedTab.label,
								} }
								trigger={ [ 'click' ] }
								overlay={ (
									<DropdownOverlay paddingVariant="vertical" >
										<DropdownListing
											selectedKeys={[ selectedTab.key ]}
										>
											{ Tabs.map( ( tab ) => (
												<DropdownListingItem onClick={ handleTabChange( tab.key ) } key={tab.key}>
													{ tab.label }
												</DropdownListingItem>
											) ) }
										</DropdownListing>
									</DropdownOverlay>
								) }
							/>
						</Tooltip>
					</div>
					<HeaderActions>
						{ 
							isManager ? (
								<Button
									variant="primary"
									onClick={ handleNewRuleClick }
									type="button"
									size="large"
								>
									<Cogs />
									Create URL Rule
								</Button>
							) : (
								<Tooltip
									overlay="You don't have permission to create or edit page rules."
								>
									<span>
										<Button
											variant="primary"
											type="button"
											size="large"
											disabled={ !isManager }
										>
											<Cogs />
											Create URL Rule
										</Button>
									</span>
								</Tooltip>
							)
						}
						<Link
							href="#test-url"
							legacyBehavior
						>
							<a
								href="#test-url"
							>
								<TestLinkButton
									variant="secondary"
									type="button"
									size="large"
								>
									<LinkCheck />
									Test URL
								</TestLinkButton>
							</a>
						</Link>
						<ChangelogButton
							variant="secondary"
							type="button"
							size="large"
							onClick={ handleOpenChangelog }
						>
							<History />
						</ChangelogButton>
					</HeaderActions>
				</Header>
				<React.Suspense fallback={ (
					<div>
						<Spinner
							data-size="m"
						/>
					</div>
				) }>
					<PageDefinition
						status={ status }
						isManager={ isManager }
					/>
				</React.Suspense>
			</Container>
		</StylesProvider>
	)
}

export default React.memo( PageDefinitionLoader );
