import React from 'react'
import { useFormContext } from 'react-hook-form';
import { theme } from 'theme';
import styled from 'styled-components';
import { PageRuleFormProps } from './RuleBuilder';

const Container = styled.div`
	display: flex;
	background: ${ theme.colors.primary05.toString() };
	border-radius: 6px;
	padding: ${ theme.spacing( 0, 1 ) };
	line-height: 28px;
	font-size: ${ theme.fontSize( 1.2 ) };
	color: ${ theme.colors.surface300.toString() };
	b {
		font-weight: 700;
		color: ${ theme.colors.primary400.toString() };
	}
`

const PatternDisplay = () => {

	const {
		watch,
	} = useFormContext<PageRuleFormProps>();

	const pattern = watch( 'pattern' );
	const originalUrl = watch( 'originalUrl' );

	const { parts, hashLeadingSlash } = React.useMemo( () => {

		if ( !pattern ) {
			return { parts: [] as string[], hashLeadingSlash: '' };
		}

		try {
			const parsedURL = new URL( originalUrl );
			const url = new URL( `${ parsedURL.origin }/${ pattern }` );
			// eslint-disable-next-line no-shadow
			const parts = url.pathname.slice( 1 ).split( '/' );

			if ( url.hash ) {
				// Split the hash on '/' so each dynamic segment (e.g. ':ruth') is
				// rendered as a parameter ({ruth}) instead of the whole hash being
				// treated as one literal chunk. The leading '#'/'#/' stays attached
				// to the first hash segment.
				parts.push( ...url.hash.split( '/' ) );
			}

			// The pattern never stores the trailing '/' before '#', so mirror the
			// original route: '/#/' keeps the leading slash, '#/' does not.
			const leadingSlash = parsedURL.pathname.endsWith( '/' ) && parsedURL.pathname !== '/' ? '/' : ''

			return { parts, hashLeadingSlash: leadingSlash }
		} catch ( e ) {
			return { parts: [] as string[], hashLeadingSlash: '' }
		}
	}, [ pattern, originalUrl ] );

	return (
		<Container>
			{
				parts.map( ( part, index, arr ) => {
					// The hash boundary token starts with '#'. Peel it off so the
					// first hash segment is still subject to param/wildcard rendering,
					// and prefix the literal '#' with the route's leading slash.
					const isHashBoundary = part.startsWith( '#' )
					const segment = isHashBoundary ? part.slice( 1 ) : part
					const usePart = segment.replace( '**', '')
					const nextPart = arr[ index + 1 ];
					const hasNext = typeof nextPart === 'string' && !nextPart.startsWith( '#' )
					const isParam = usePart === '*' || usePart.startsWith( ':' );
					const containsIgnore = segment.endsWith( '**' )

					return (
						// eslint-disable-next-line react/no-array-index-key
						<React.Fragment key={ index }>
							{ isHashBoundary ? `${ hashLeadingSlash }#` : null }
							{ isParam ? (
								<b>{ usePart === '*' ? usePart : `{${ usePart.substring( 1 ) }}` }</b>
							) : usePart }
							{ containsIgnore ? <b>**</b> : null }
							{ hasNext ? <span>/</span> : null }
						</React.Fragment>
					)
				} )
			}
		</Container>
	)

}

export default React.memo( PatternDisplay );