import React, { useMemo } from 'react';
import { useSelector } from 'react-redux';
import styled from 'styled-components';
import { useQueryClient } from 'react-query';
import { theme } from 'theme';

const PlanDetailWrapper = styled.div`
  border: 1px solid #c0cad9;
  border-radius: 5px;
  height: fit-content;
  padding: 20px;
`;

const Header = styled.div`
  font-weight: 500;
  font-size: 16px;
  color: #161e35;

  h3 {
    font-size: ${ theme.fontSize( 1.8 ) };
    line-height: ${ theme.fontSize( 2.8 ) };
    color: ${ theme.colors.primaryMidnight.toString() };
    font-weight: 500;
  }
`;

const EnterprisePlanWrap = styled.div`
  font-weight: 500;
  font-size: 14px;
  margin-top: 10px;
  display: flex;
  flex-wrap: wrap;
`;

const EnterprisePlanLeft = styled.span`
  flex: 50%;
`;

const EnterprisePlanRight = styled.span`
  justify-content: flex-end;
`;

const EnterprisePlanLeftTotal = styled(EnterprisePlanLeft)`
  font-size: 14px;
  color: #8a99b1;
  font-weight: 400;
`;

const EnterprisePlanRightTotal = styled(EnterprisePlanRight)`
  font-size: 14px;
  color: #8a99b1;
  font-weight: 400;
`;

const PlanExpire = styled.div`
  border: 1px solid #f4584c;
  padding: 6px;
  font-weight: 400;
  margin-top: 10px;
  font-size: 14px;
  border-radius: 4px;
  p {
    margin: 0;
    padding: 0;
    color: #f4584c;
  }
`;

const mapObjBillingly = {
  1: 'Billed every 1 month',
  3: 'Billed every 3 months',
  6: 'Billed every 6 months',
  9: 'Billed every 9 months',
  12: 'Billed every 12 months',
};

const SubscriptionPlanDetail = () => {
  const queryClient = useQueryClient();
  const {
    currentOrgReducer: { orgId, planLimit, planType },
  } = useSelector((state) => state);

  const { dataRetentionTime: dataRetentionPeriod, videoRetentionTime: videoRetentionPeriod} = planLimit || {};

  const currentSunscriptionKey = useMemo(
    () => `currentSubscription${orgId}`,
    [orgId]
  );

  const currentSubscription = queryClient.getQueryData(currentSunscriptionKey);
  const currentSubscriptionStatus =
    currentSubscription?.subscription?.status?.toLowerCase();

  const contract = currentSubscription?.contract;

    const expireInfo =  `Your current plan has been ${currentSubscriptionStatus}${
      currentSubscriptionStatus === 'canceled' &&
      currentSubscription?.payment?.expiresAt
        ? ` and it will expire at ${currentSubscription?.payment?.expiresAt}.`
        : '.'
    }`

  const cancelledText = useMemo(() => {
    if( currentSubscription?.subscription?.status === 'Active' ){
      return 'Cancels on '
    }

    return 'Canceled on '
  }, [currentSubscription?.subscription?.status])

  return (
    <PlanDetailWrapper>
      <Header>
        <h3>Plan details</h3>
        <EnterprisePlanWrap>
          <EnterprisePlanLeft>
            {currentSubscription?.yourPlan?.featurePlan}
          </EnterprisePlanLeft>
          <EnterprisePlanRight>
            ${currentSubscription?.payment?.price}
          </EnterprisePlanRight>
        </EnterprisePlanWrap>
        <EnterprisePlanWrap>
          {
              !!currentSubscription?.payment?.renewalStatus &&
              <EnterprisePlanLeftTotal>
                {
                  currentSubscription?.payment?.renewalStatus === 'cancel' ?
                  cancelledText : "Renews on "
                }
                {currentSubscription?.payment?.billingEndDate || currentSubscription?.payment?.nextBillingDate}
              </EnterprisePlanLeftTotal>
          }
          {
            planType !== 'free' && (
              <EnterprisePlanRightTotal>
                {mapObjBillingly[currentSubscription?.payment?.billingFrequency]}
              </EnterprisePlanRightTotal>
            )
          }
        </EnterprisePlanWrap>
        <EnterprisePlanWrap>
          <EnterprisePlanLeftTotal>
            Data retention policy
          </EnterprisePlanLeftTotal>
          <EnterprisePlanRightTotal>
            {`${dataRetentionPeriod} month${
              dataRetentionPeriod > 1 ? 's' : ''
            }`}
          </EnterprisePlanRightTotal>
        </EnterprisePlanWrap>
        {videoRetentionPeriod && (
          <EnterprisePlanWrap>
            <EnterprisePlanLeftTotal>
              Video retention policy
            </EnterprisePlanLeftTotal>
            <EnterprisePlanRightTotal>
              {`${videoRetentionPeriod} month${
                videoRetentionPeriod > 1 ? 's' : ''
              }`}
            </EnterprisePlanRightTotal>
          </EnterprisePlanWrap>
        )}
        {contract && (
          <EnterprisePlanWrap>
            <EnterprisePlanLeftTotal>Contract Period</EnterprisePlanLeftTotal>
            <EnterprisePlanRightTotal>
              {contract.contractStart} - {contract.contractEnd}
            </EnterprisePlanRightTotal>
          </EnterprisePlanWrap>
        )}
        {currentSubscriptionStatus &&
          currentSubscriptionStatus !== 'active' &&
          currentSubscriptionStatus !== 'past due' && (
            <PlanExpire>
              <p>
                {expireInfo}
              </p>
            </PlanExpire>
          )}
      </Header>
    </PlanDetailWrapper>
  );
};

export default SubscriptionPlanDetail;
