const PaymentDue = ({ paymentLink }:{
    paymentLink?: string;
}) => {
  const {
    currentOrgReducer: { orgId },
  } = useSelector((state) => state) as IReduxState;

  const handlePayNow = () => {
    if (paymentLink) {
      window.open(paymentLink, '_blank');
    }
  };

  return (
      <PlanDetailWrapper>
        <PaymentPlanWrap>
          <PaymentPlanLeft>
            <h3 style={{ marginBottom: '4px' }}>Payment due</h3>
            <p style={{ marginBottom: '8px' }}>Your account has an unpaid invoice. Please complete the payment to keep your dashboard access active.</p>
            <p style={{ marginBottom: '0px' }}>
              Need help?{" "}
              <button
                type="button"
                onClick={() => {
                  if (window.Intercom) {
                    window.Intercom('show');
                  }
                }}
              >
                Contact support
              </button>
            </p>
          </PaymentPlanLeft>
          <PaymentPlanRight>
            <OrangeButton type="primary" onClick={handlePayNow}>Pay now</OrangeButton>
          </PaymentPlanRight>
        </PaymentPlanWrap>
      </PlanDetailWrapper>
    );
};

export default PaymentDue;
