import React, { useCallback, useEffect, useMemo, useState } from 'react';

import { RootStateOrAny, useDispatch, useSelector } from 'react-redux';

import NotificationAlert from 'dashboard-builder/dist/cjs/Alert';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { trackPageViews } from 'redux/actions/trackingReport';
import { fetchPlanHatApi } from 'redux/actions/common';

// assets
import CircleAlert from 'public/static/circle-alert.svg';
import Illustration from 'public/static/lock-features/alerts-locked-illustration.svg'

// components
import { tokenRefreshManager } from 'services/tokenRefreshManager';
import LockedPage from 'components/common/LockedPage';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import { IUseRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContextTypes';
import { useIsAppType } from 'hooks/useIsAppType';
import MassUserIdFilter from 'components/shared/GlobalFilter/components/MassUserIdFilter';
import InfoBox from 'components/common/InfoBox';

// styles
import { Container, Header, StyledButton, TableContainer } from './styles';

const AlertsSection: React.FC<{
  appId: string;
}> = ({ appId }) => {
  const [openModal, setOpenModal] = useState(false);
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext();
  const {
    urlReducer: { 
      url: reduxUrl,
      parentType,
    },
} = useSelector((state: RootStateOrAny) => state);
  const env = process.env.APP_ENV || 'develop';
  const url = window.location.href || reduxUrl || '';
  const conversionEnabled = useFeatureFlag( 'conversion-report' )
  const dispatch = useDispatch();
  const { selfServeFlag, setShowPricingModal, alertsFeatureAllowed, retentionFeatureAllowed, aiSessionFeatureAllowed } = useRestrictionContext() as unknown as IUseRestrictionContext

  const defaultOpenModal = useMemo(() => url.includes('#create-alert') || url.includes('#view-alert'), [url]);

  const removeHashFromUrl = () => {
    const hashIndex = url.indexOf('#create-alert') !== -1 ? url.indexOf('#create-alert') : url.indexOf('#view-alert');
    const searchIndex = url.indexOf('?');
    if (hashIndex === -1) return;
    const newPath = url.substring(0, searchIndex !== -1 ? searchIndex : hashIndex);
    window.history.replaceState({}, document.title, newPath);
  }

  const addHashToUrl = () => {
    window.location.hash = 'create-alert';
  }

  const trackEvent = React.useCallback(
    (eventName: string, property: string) => {
      dispatch(
        fetchPlanHatApi({
          action: eventName,
          property,
        })
      );
      dispatch(trackPageViews(null, {
        eventName,
        track_type: 'event',
        eventProperty: property,
        pageName: parentType,
      }))
    },
    [ dispatch, parentType ]
  );

  useEffect(() => {
    if (defaultOpenModal) setOpenModal(true);

    return () => {
      setOpenModal(false);
    }
  }, [defaultOpenModal])

  const InfoMessage = useMemo(() => (
      <>
        Set custom alerts for proactive monitoring of your key metrics and stay ahead of potential issues.
        {' '}
        <a href='https://help.uxcam.com/hc/en-us/articles/30459874917273-Overview-of-Alerts' 
          target='_blank' 
          rel='noopener noreferrer'
          style={{
            textDecoration: 'none',
            color: '#5D97FF',
          }}
        >Learn how.</a>
      </>
    ), [])

  const handleClick = useCallback( () => {
    setOpenModal(true);
    addHashToUrl();
    dispatch(
      trackPageViews( null, {
        eventName: 'wa_alerts_click_alert_creator',
        track_type: 'event',
        eventProperty: {},
      } )
    )
  }, [ dispatch ] )

  const handleClickSeePricing = useCallback( () => {
		setShowPricingModal( true )
		dispatch( trackPageViews( null, {
			eventName: 'wa_see_pricing_clicked',
			track_type: 'event',
			eventProperty: {
				source: 'Settings'
			},
		} ) )
	}, [ setShowPricingModal, dispatch ] )

	const handleClickRequestPricing = useCallback( () => {
		setShowPricingModal( true )
		dispatch( trackPageViews( null, {
			eventName: 'wa_request_pricing_clicked',
			track_type: 'event',
			eventProperty: {
				source: 'Settings'
			},
		} ) )
	}, [ setShowPricingModal, dispatch ] )

  const newScreenFilter = useFeatureFlag('new-screens-filter')
  const isWebApp = useIsAppType( 'web' )

  return (
      <Container>
      { !alertsFeatureAllowed ? (
        <LockedPage
          image={ Illustration }
          title="Custom Alerts"
          subTitle="Stay on top of changes and act faster"
          list={
            <>
              <li>Monitor your product&apos;s performance effortlessly.</li>
              <li>Anticipate and address potential issues promptly.</li>
              <li>Make informed decisions faster and more effectively.</li>
            </>
          }
          selfServeFlag={ selfServeFlag }
          handleClickSeePricing={ handleClickSeePricing as () => null }
          handleClickRequestPricing={ handleClickRequestPricing as () => null }
          imageSrc={ undefined }
          />
      ) : (
        <>
          <Header>
            <InfoBox
              type="info"
              content={ InfoMessage }
            />
            <StyledButton
              type="primary"
              onClick={handleClick}
              disabled={defaultOpenModal}
              loading={defaultOpenModal}
              icon={<CircleAlert />}
              data-intercom-target="Create alert top bar"
            >
              Create alert
            </StyledButton>
          </Header>
          <TableContainer>
            <NotificationAlert
              appId={appId}
              env={env}
              noCodeEnabled={noCodeEventsFeatureFlag}
              cohortsEnabled={retentionFeatureAllowed}
              conversionEnabled={conversionEnabled}
              openModal={openModal}
              trackEvent={trackEvent}
              handleCloseModal={() => {
                setOpenModal(false);
                removeHashFromUrl();
              } }
              isWebSDK={ isWebApp }
              newScreenFilter={ newScreenFilter }
              handleOpenModal={() => setOpenModal(true)}
              onBeforeRequest={ tokenRefreshManager.refreshIfNeeded }
              // eslint-disable-next-line @typescript-eslint/ban-ts-comment
              // @ts-ignore 
              MassUserIdModal={ MassUserIdFilter }
              isNewAISessionEnabled={ aiSessionFeatureAllowed }
            />
          </TableContainer>
        </>
      ) }
      </Container>
  );
};

export default AlertsSection;
