/* eslint-disable no-nested-ternary */
import React, {  useEffect } from 'react';
import { useRouter } from 'next/router';
import { useSelector, useDispatch } from 'react-redux';

import { setSingleSignOn } from 'redux/actions/sso';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';

import NewOrgSetting from './OrganizationSetting';
import ApplicationSetting from './AppSetting';
import NewProfile from './OrganizationSetting/ProfileSection/Profile'

import {
  useFetchRolesAndPermission,
  useFetchNewProfile,
} from './useSettingPage';


const AppSettings = () => {
  const {
    urlReducer: urlQuery,
    currentOrgReducer: activeSubscription,
  } = useSelector((state) => state);

  const queryKey = `roles_permission`;
  const { setShowPricingModal } = useRestrictionContext()

  useFetchRolesAndPermission(queryKey);
  useFetchNewProfile(`profileInfo`);

  const router = useRouter();
  const dispatch = useDispatch();

  const { setting } = urlQuery;

  const routerQuery = router?.query;

  const currentKey = routerQuery?.setting || setting

  const renderComponent = (() => {
    switch (currentKey) {
      case 'org_setting':
        return <NewOrgSetting />;
      case 'profile_setting':
        return <NewProfile />;
      default:
        return <ApplicationSetting />;
    }
  })();

  useEffect(() => {
    if (activeSubscription) {
      dispatch(
        setSingleSignOn(activeSubscription?.planFeature?.SAMLSingleSignOn === 1)
      );
    }

    setShowPricingModal(false)
  }, [activeSubscription, dispatch, setShowPricingModal]);

  return renderComponent;
};

export default AppSettings;
