import React, { useState } from 'react'
import { useSelector } from 'react-redux'
import styled from 'styled-components'
import { useQuery, useMutation, useQueryClient } from 'react-query'
import SubscriptionApi from 'services/subscriptionApi'
import { emailRegex } from 'Utils/helpers/commonUtils'
import { Button, Spinner } from 'uxcam-frontend-components'
import { theme } from 'theme'
import { Form } from 'antd'
import { setError } from 'redux/actions/common'
import { Country } from 'country-state-city'
import ChipInput from './ChipInput'
import BillingInformationModal from './BillingInformationModal'

const Row = styled.div`
  display: flex;
  margin-bottom: 10px;
`

const HorizontalWrapper = styled.div`
  display: flex;
  width: 100%;
  justify-content: space-between;
  margin-bottom: 10px;
  align-items: center;
`

const ButtonUpdate = styled( Button )`
  font-size: 14px !important;
  line-height: 16px !important;
  padding: 8px 14px !important;
  height: fit-content !important;
  min-width: 0 !important;
`

const BillingInfoWrapper = styled.div`
  position: relative;
  border: 1px solid #c0cad9;
  border-radius: 5px;
  padding: 20px;
  margin-top: 20px;
  .ant-form-item-explain.ant-form-item-explain-error {
    font-size: 12px;
    margin: 2px;
  }

  ${ Row }:last-of-type {
    margin-bottom: 0;
  }
`;

const Header = styled.div`
  h3 {
    font-size: ${ theme.fontSize( 1.8 ) };
    line-height: ${ theme.fontSize( 2.8 ) };
    color: ${ theme.colors.primaryMidnight.toString() };
    font-weight: 500;
    margin-bottom: 0px;
    z-index: 4;
  }
`;

const Label = styled.h4`
  font-size: 14px;
  line-height: 22px;
  font-weight: 500;
  color: #49576E;
  font-family: 'Roboto', sans-serif;
  min-width: 140px;
  margin-right: 24px;
  margin-bottom: 0;
`

const Value = styled( Label )`
  font-weight: 400;
  min-width: initial;
  margin-right: initial;
  width: 100%;
`

const SpinnerWrapper = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba( 255, 255, 255, 0.5 );
  z-index: 2;
`

const BillingInfo = () => {
  const [ popupOpen, setPopupOpen ] = useState( false )
  const {
    currentOrgReducer: { orgId },
  } = useSelector((state) => state)
  const queryClient = useQueryClient()

  const { data, isFetching: queryIsLoading, refetch } = useQuery(
    'billingInfo',
    () => SubscriptionApi.getBillingInfo( orgId ), {
      enabled: !!orgId
    }
  )

  const { mutate, isLoading: mutationIsLoading } = useMutation( {
    mutationFn: ( newData ) => SubscriptionApi.setRecipientEmails( orgId, newData ),
    onMutate: async ( newData ) => {
      await queryClient.cancelQueries( { queryKey: [ 'billingInfo' ] } )
      const prevData = queryClient.getQueryData( [ 'billingInfo' ] )

      queryClient.setQueryData( [ 'billingInfo' ], ( prev ) => ( {
        ...prev,
        billing_recipients: newData
      } ) )
      return { prevData }
    },
    onSuccess: () => {
      refetch()
      setPopupOpen( false )
    }
  } )

  const fieldErrors = ( obj ) => Object.keys( obj ).map( ( el ) => {
    const err = obj[ el ]
    if ( typeof err !== 'string' ) {
      const key = Object.keys( err )[ 0 ]
      return {
        name: key,
        errors: [ err[ key ] ]
      }
    }

    if ( err.includes( 'VAT Number not applicable for this country' ) ) {
      return {
        name: 'vatNumber',
        errors: [ 'Please enter valid VAT number' ]
      }
    }

    setError( 'Please enter valid billing information' )
    return null
  } )

  const [ form ] = Form.useForm() 

  const { mutate: billingMutation, isLoading: bilingMutationIsLoading } = useMutation( {
    mutationFn: ( newData ) => SubscriptionApi.setBillingAddress( orgId, newData ),
    onMutate: async ( newData ) => {
      await queryClient.cancelQueries( { queryKey: [ 'billingInfo' ] } )
      const prevData = queryClient.getQueryData( [ 'billingInfo' ] )

      queryClient.setQueryData( [ 'billingInfo' ], ( prev ) => ( {
        ...prev,
        billing_info: newData
      } ) )
      return { prevData }
    },
    onSuccess: () => {
      refetch()
      setPopupOpen( false )
    },
    onError: ( { response } ) => {
      const errors = fieldErrors( response?.data?.error )
      if ( errors?.length ) {
        form.setFields( errors )
      }
    }
  } )

  const billingInfo = data?.billing_info
  const billingRecipients = data?.billing_recipients

  const chipInputCallback = React.useCallback( ( newData ) => {
    mutate( newData )
  }, [ mutate ] )

  const setFormDefaultValues = React.useCallback( () => {
    form.setFieldsValue( {
      firstName: billingInfo?.address?.first_name || undefined,
      lastName: billingInfo?.address?.last_name || undefined,
      country: billingInfo?.address?.country || undefined,
      state: billingInfo?.address?.state || undefined,
      zip: billingInfo?.address?.zip || undefined,
      city: billingInfo?.address?.city || undefined,
      address: billingInfo?.address?.address || undefined,
      vatNumber: billingInfo?.vat_number || undefined,
    } )
  }, [ form, billingInfo ] )

  React.useEffect( () => { 
    setFormDefaultValues()
  }, [ setFormDefaultValues ] )

  const countryCode = billingInfo?.address?.country
  const country = countryCode ? Country.getCountryByCode( countryCode )?.name : '-'

  return (
      <>
        <BillingInformationModal
          popupOpen={ popupOpen }
          setPopupOpen={ setPopupOpen }
          form={ form }
          setBillingAddress={ billingMutation }
          billingAddressIsLoading={ bilingMutationIsLoading }
          billingInfo={ billingInfo }
          setFormDefaultValues={ setFormDefaultValues }
        />
        <BillingInfoWrapper>
          { queryIsLoading && !data && (
            <SpinnerWrapper>
              <Spinner data-size="m" />
            </SpinnerWrapper>
          ) }
          <Header>
            <HorizontalWrapper>
              <h3>Billing information</h3>
              <ButtonUpdate
                variant="secondary"
                size="big"
                onClick={ () => setPopupOpen( true ) }
              >
                Update Information
              </ButtonUpdate>
            </HorizontalWrapper>
          </Header>
          <Row>
            <Label>VAT Number:</Label>
            <Value>{ billingInfo?.vat_number || '-' }</Value>
          </Row>
          <Row>
            <Label>First Name:</Label>
            <Value>{ billingInfo?.address?.first_name || '-' }</Value>
          </Row>
          <Row>
            <Label>Last Name:</Label>
            <Value>{ billingInfo?.address?.last_name || '-' }</Value>
          </Row>
          <Row>
            <Label>Country:</Label>
            <Value>{ country }</Value>
          </Row>
          <Row>
            <Label>State:</Label>
            <Value>{ billingInfo?.address?.state || '-' }</Value>
          </Row>
          <Row>
            <Label>City:</Label>
            <Value>{ billingInfo?.address?.city || '-' }</Value>
          </Row>
          <Row>
            <Label>Address line 1:</Label>
            <Value>{ billingInfo?.address?.address || '-' }</Value>
          </Row>
          <Row>
            <Label>Postal code:</Label>
            <Value>{ billingInfo?.address?.zip || '-' }</Value>
          </Row>
          <Row>
            <Label>Billing Recipients:</Label>
            <Value>
              <ChipInput
                data={ billingRecipients }
                callback={ chipInputCallback }
                inputPlaceholder="Add recipients’ emails"
                regex={ emailRegex }
                loading={ mutationIsLoading }
                btnLabel="Add recipients"
              />
            </Value>
          </Row>
        </BillingInfoWrapper>
      </>
  )
}

export default BillingInfo
