import { useMemo } from 'react';

// packages
import { notification } from 'antd';
import capitalize from 'lodash/capitalize';
import { useMutation, useQuery, useQueryClient } from 'react-query';
import { RootStateOrAny, useSelector, useDispatch } from 'react-redux';

// components
import { rollbar } from 'components/common/rollbar';

// services
import { axiosInstance } from 'services/globalInstance';

// actions
import { trackPageViews } from 'redux/actions/trackingReport';

type saveIssueConfigPayload = {
  appid: string;
  notificationType: string[];
  slack: {
    webhookUrl: string;
    channelName: string;
    isEnabled: boolean;
  };
  microsoft: {
    webhookUrl: string;
    isEnabled: boolean;
  };
  notification: string[];
};

type testIssueNotificationPayload = {
  appid: string;
  notificationType: string;
  slack?: {
    webhookUrl: string;
    channelName: string;
    isEnabled: boolean;
  };
  microsoft?: {
    webhookUrl: string;
    isEnabled: boolean;
  };
  notification: string[];
}

export const useGetIssueConfig = ({ appid }: { appid: string }) =>
  useQuery(
    ['issueConfig', appid],
    () =>
      axiosInstance
        .get(
          `${process.env.PYTHON_API_URL}/issue_notification/${appid}/configuration`,
          {
            withCredentials: true,
          }
        )
        .then((res) => res.data),
    {
      retry: false,
    }
  );

export const useIssueNotification = () => {
  const queryClient = useQueryClient();
  const dispatch = useDispatch();
  const {
    urlReducer: {app: appId},
  } = useSelector((state: RootStateOrAny) => state);
  const queryKey = useMemo(() => ['issueConfig', appId], [appId]);
  const { data: issueConfigData } = useGetIssueConfig({ appid: appId });

  const formatChannelName = (channelName: string) => {
    if (!channelName) return channelName;
    if (channelName[0] === '#') {
      return channelName.slice(1);
    }
    return channelName;
  };

  function generateNotificationArray(isSlackChecked: boolean, isTeamsChecked: boolean) {
    const notificationArray: string[] = [];
  
    if (isSlackChecked && !notificationArray.includes('slack')) {
      notificationArray.push('slack');
    }
  
    if (isTeamsChecked && !notificationArray.includes('microsoft')) {
      notificationArray.push('microsoft');
    }
  
    return notificationArray;
  }
  

  const transformedString = (options: string[]) => {
    const transformedItems: string[] = [];
    options.forEach((item) => {
      if (item === 'Handled Exception') {
        transformedItems.push('exception');
      } else if (item === 'UI Freeze') {
        transformedItems.push('uifreeze');
      } else {
        transformedItems.push(item.toLowerCase());
      }
    });
    const res =
      transformedItems.length === 1
        ? transformedItems[0]
        : transformedItems.join(', ');
    return res;
  };

  const issueConfig = useMemo(() => {
    if (issueConfigData) {
      const {
        notification: checkOptions,
        slack,
        microsoft,
      } = issueConfigData.data.crashNotificationConfiguration;
      const { isCrashNotificationEnabled } = issueConfigData.data;
      return {
        isCrashNotificationEnabled,
        checkOptions,
        slack: {
          ...slack,
          channelName: formatChannelName(slack.channelName),
        },
        microsoft,
        enabledIssueType: generateNotificationArray(slack.isEnabled, microsoft.isEnabled),
      };
    }
    return {
      isCrashNotificationEnabled: false,
      checkOptions: [],
      slack: {
        webhookUrl: '',
        channelName: '',
        isEnabled: false,
      },
      microsoft: {
        webhookUrl: '',
        isEnabled: false,
      },
      enabledIssueType: [],
    };
  }, [issueConfigData]);

  const showSuccessNotification = (msg: string) => {
    notification.success({
      message: msg,
      duration: 4,
    });
  };

  const showErroNotification = (msg: string) => {
    notification.error({
      message: msg,
      duration: 4,
    });
  };

  const testNotification = useMutation({
    mutationFn: (payload: testIssueNotificationPayload) =>
      axiosInstance.post(
        `${process.env.PYTHON_API_URL}/issue_notification/test`,
        payload,
        {
          withCredentials: true,
        }
      ),
    onSuccess: (res, payload) => {
      const successObject = res.data.data;
      const errorMessage = Object.keys(successObject).map((key) => `${successObject[key]?.error?.message || ''}`)
      .join('\n');
      const successMessage = Object.keys(successObject)
        .map((key) => `${successObject[key].message || ''}`)
        .join('\n');
      if (successMessage.length) showSuccessNotification(successMessage);
      if (errorMessage.length) showErroNotification(errorMessage);

      dispatch(
        trackPageViews(null, {
          eventName: 'wa_test_issue_notification',
          track_type: 'event',
          eventProperty: {
            notification_platform: payload.notificationType,
            issue_type: transformedString(payload.notification),
            response: res.status === 200 ? 'success' : 'fail',
          },
        })
      );
    },
    onError: (err: any, payload) => {
      const res = err.response;
      const errorObject = res.data.error;

      const errorMessage = Object.keys(errorObject)
        .map((key) => `${capitalize(key)}: The URL provided is not a valid webhook URL.`)
        .join('\n');

      rollbar.error(
        errorObject,
        `Error on ${payload.notificationType} test notification`
      );
      res.status === 422
        ? showErroNotification(errorMessage)
        : showErroNotification('Something went wrong! Please try again.');

      dispatch(
        trackPageViews(null, {
          eventName: 'wa_test_issue_notification',
          track_type: 'event',
          eventProperty: {
            notification_platform: payload.notificationType,
            issue_type: transformedString(payload.notification),
            response: 'fail',
          },
        })
      );
    },
  });

  const saveIssueConfig = useMutation({
    mutationFn: (payload: saveIssueConfigPayload) =>
      axiosInstance.post(
        `${process.env.PYTHON_API_URL}/issue_notification/save`,
        payload,
        {
          withCredentials: true,
        }
      ),
    onSuccess: (res, payload) => {
      queryClient.invalidateQueries(queryKey);
      const successObject = res.data.data;
      const errorMessage = Object.keys(successObject).map((key) => `${successObject[key]?.error?.message || ''}`)
      .join('\n');
      let successMessage = Object.keys(successObject)
        .map((key) => `${capitalize(key)}: Issue notification configuration has been successfully updated.`)
        .join('\n');
      if (Object.keys(successObject).length > 1) successMessage = 'Issue notification configuration has been successfully updated.';
      if(successMessage.length > 0) showSuccessNotification(successMessage)
      if(errorMessage.length > 3) showErroNotification(errorMessage)

      dispatch(
        trackPageViews(null, {
          eventName: 'wa_issue_notification_configured',
          track_type: 'event',
          eventProperty: {
            notification_platform: payload.notificationType,
            issue_type: transformedString(payload.notification),
          },
        })
      );
    },
    onError: (err: any, payload) => {
      const res = err.response;
      const errorObject = res.data.error;

      const errorMessage = Object.keys(errorObject)
        .map((key) => `${capitalize(key)}: The URL provided is not a valid webhook URL.`)
        .join('\n');
      rollbar.error(
        errorObject,
        `Error on save ${payload.notificationType} issue notification`
      );
      res.status === 422
        ? showErroNotification(errorMessage)
        : showErroNotification('Something went wrong! Please try again.');
    },
  });

  return {
    testNotification,
    saveIssueConfig,
    issueConfig,
  };
};
