/* eslint-disable jsx-a11y/control-has-associated-label */
import React, { memo, useCallback, useEffect, useMemo } from 'react';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import styled from 'styled-components';
import LogoPlay from 'public/static/logo-play.svg';
import { theme } from 'theme';

import {
  IGetNocodeEventManageListPayload,
  INocodeEvent,
} from 'types/nocodeEvents';
import { useQuery } from 'react-query';
import { getNocodeEventManageList } from 'components/features/sessions/hooks/useNocodeEvents';
import { useSelector } from 'react-redux';
import { IReduxState } from 'types/reduxStateTypes';
import { DashboardTable, StylesProvider } from 'uxcam-frontend-components';
import InfoBox from 'components/common/InfoBox';

import { usePagination } from 'components/features/issues/components/ReactTable/usePagination';

import {
  gesturesValueToStringTypeAdjusted,
  gesturesViewTypeIntToStringAdjusted,
} from 'components/common/NoCodeEvents/NoCodeEventsPopups/ManageNoCodeEventPopup';

import useNocodeColumns from './useNocodeColumns';


const WrapperTop = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
`

const GhostButton = styled.button`
	padding: ${ theme.spacing( 1, 1.5 ) };
	margin-right: ${ theme.spacing( 0 ) };
	border: none;
	font-size: ${ theme.fontSize( 1.4 ) };
	line-height: ${ theme.fontSize( 1.7 ) };
	color: ${ theme.colors.primary500.toString() };
	border-radius: 6px;
	background-color: ${ theme.colors.primary10.toString() };
	font-weight: 500;
	display: flex;
	align-items: center;
	cursor: pointer;
	transition: all 0.2s ease-in-out;
	svg {
		margin-right: ${ theme.spacing( 0.75 ) };
	}
	&:hover {
		background-color: ${ theme.colors.primary500.toString() };
		color: ${ theme.colors.primarySnow.toString() };
	}
`

const Wrapper = styled.div`
  height: 100%;
  display: flex;
  flex-direction: column;
  position: relative;
`;

const TableWrapper = styled.div`
	overflow-y: auto;
	height: 100%;
	position: relative;
  table{
    width: 99.6% !important;
  }
`

const NocodeEventSection: React.FC = () => {
  const {
    manageListPage,
    setShowNoCodeEventsTutorial,
    setManageListPage,
  } = useNoCodeEventsContext();
  const { currentAppReducer } = useSelector((state: IReduxState) => state);

  const {
    setCurrentAction,
    setManagePopupOpen,
    setScreenEventModalOpen,
  } = useNoCodeEventsContext();

  const { pagination, setPagination } = usePagination()
  
  // eslint-disable-next-line no-underscore-dangle
  const appid = currentAppReducer?._id;
  const payload = useMemo(
    () => ({
      appid,
      filters: [],
      date_range: {
        attribute: 'upload_time',
        operator: 'between_dates',
        value: {
          lower: '2023-04-08T10:16:26.366Z',
          upper: '2023-05-08T10:16:26.366Z',
        },
      },
      orderBy: [
        {
          sortName: 'name',
          sortOrder: 'desc',
        },
      ],
      page: manageListPage,
    }),
    [appid, manageListPage]
  );

  const fetchNocodeEventList = useCallback(() => {
    if (appid)
      return getNocodeEventManageList(
        payload as IGetNocodeEventManageListPayload
      );
    return undefined;
  }, [appid, payload]);

  const {
    isLoading,
    isFetching,
    data: response,
    refetch,
  } = useQuery({
    queryKey: ['manage-nocode-list'],
    queryFn: fetchNocodeEventList,
    keepPreviousData: true,
  });

  const data = response?.data?.data;
  const rawPagination = data?.pagination;

  const handleTutorialTrigger = useCallback(() => {
    setShowNoCodeEventsTutorial(true)
  }, [setShowNoCodeEventsTutorial])

  const columns = useNocodeColumns()

  useEffect(() => {
    refetch();
  }, [refetch, manageListPage]);

  useEffect(() => {
    if( pagination ){
      setManageListPage(pagination.pageIndex);
    }
  }, [pagination, setManageListPage])

  const handleEdit = useCallback(
    (event: INocodeEvent) => {
      if (event.eventType === 'Screen') {
        setCurrentAction({
          name: event.name,
          type: "smart_screenvisit_event",
          description: event.description || '',
          id: event.nceId as unknown as string,
          eventType: event.eventType,
          createdByName: event.createdByName,
          createdOn: event.createdOn,
          props: {
            activityName: event.screenName,
          },
        });
        setScreenEventModalOpen(true);
      } else {
        setCurrentAction({
          name: event.name,
          type: 'smart_gesture_event',
          description: event.description || '',
          id: event.nceId as unknown as string,
          screenName: event.screenName,
          eventType: event.eventType,
          createdByName: event.createdByName,
          createdOn: event.createdOn,
          props: {
            category: event.category,
            gestureType:
              event.gestureType !== undefined
                ? gesturesValueToStringTypeAdjusted[event.gestureType]
                : undefined,
            idString: event.elementId,
            viewName: event.viewName,
            viewType:
              event.viewType !== undefined
                ? gesturesViewTypeIntToStringAdjusted[event.viewType]
                : undefined,
            viewTypeId: event.viewTypeId,
          },
        });
        setManagePopupOpen(true);
      }
    },
    [setCurrentAction, setManagePopupOpen, setScreenEventModalOpen]
  );

  const rowsData = useMemo(() => data?.body?.map((item) => ({
      ...item,
      onRowClick: (row: INocodeEvent) => handleEdit(row)
    })) || [], [data?.body, handleEdit]);

  return (
    <Wrapper>
      <WrapperTop>
        <InfoBox
          type='info'
          content={
            <>
              Create and manage events without a single line of code. Click <a href='https://help.uxcam.com/hc/en-us/articles/24753425542297-What-are-smart-events' target="_blank" rel="noreferrer">here</a> to know more.
            </>
          }
        />
        <GhostButton onClick={ handleTutorialTrigger }>
          <LogoPlay />
          Watch tutorial
        </GhostButton>
      </WrapperTop>
      <TableWrapper>
        <StylesProvider>
          <DashboardTable 
            columns={columns}
            data={rowsData || []}
            resizeMode='onChange'
            isLoading={isLoading || isFetching}
            pagination={{
              ...pagination,
              totalPagination: rawPagination?.pages || 1,
            }}
            setPagination={setPagination}
          />
        </StylesProvider>
      </TableWrapper>
    </Wrapper>
  );
};

export default memo(NocodeEventSection);
