import React, { useState, createContext, useContext, useMemo } from "react";

const SelectedFilterModeContext = createContext();

export const SelectedFilterModeProvider = ({ children }) => {
  const [selectedFilter, setSelectedFilter] = useState([]);
  const [initialSessionData, setInitialSessionData] = useState();
  const [selectedVideoFilter, setSelectedVideoFilter] = useState([]);
  const [initialVideoData, setInitialVideoData] = useState();
  const [filterData, setFilterData] = useState([]);

  const valueInfo = useMemo(()=>({ selectedFilter,
    setSelectedFilter,
    filterData,
    initialSessionData,
    setFilterData,
    setInitialSessionData,
    selectedVideoFilter,
    setSelectedVideoFilter,
    initialVideoData,
    setInitialVideoData}), [ selectedFilter,
      setSelectedFilter,
      filterData,
      initialSessionData,
      setFilterData,
      setInitialSessionData,
      selectedVideoFilter,
      setSelectedVideoFilter,
      initialVideoData,
      setInitialVideoData])

  return (
    <SelectedFilterModeContext.Provider
      value={valueInfo}
    >
      {children}
    </SelectedFilterModeContext.Provider>
  );
};

export const useSessionRecordingCustomHooks = () => {
  const {
    selectedFilter,
    setSelectedFilter,
    filterData,
    setFilterData,
    setInitialSessionData,
    initialSessionData,
    selectedVideoFilter,
    setSelectedVideoFilter,
    initialVideoData,
    setInitialVideoData
  } = useContext(SelectedFilterModeContext);
  return {
    selectedFilter,
    setSelectedFilter,
    filterData,
    setFilterData,
    initialSessionData,
    setInitialSessionData,
    selectedVideoFilter,
    setSelectedVideoFilter,
    initialVideoData,
    setInitialVideoData
  };
};
