import React from 'react';
import { useSelector } from 'react-redux';
import styled from 'styled-components';
import { useFetchTeamList } from '../../useSettingPage';
import AnalysisTimeSection from './AnalysisTimeSection';
import AutoCustomAnalysisSection from './AutoCustomAnalysisSection';
import AppUsageSection from './AppUsageSection';

interface TaraAIWrapperProps {
  $bottomBarClassFlag: boolean;
}

const TaraAIWrapper = styled.div<TaraAIWrapperProps>`
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: ${({ $bottomBarClassFlag }) => $bottomBarClassFlag ? '60px' : '0'};
`;

const TaraAI: React.FC = () => {
  const { bottomBarClassFlag } = useSelector((state: any) => state.commonReducer);
  const { currentOrgReducer: { orgId } } = useSelector((state: any) => state);

  // Pre-fetch team list for credit usage per user section
  useFetchTeamList(orgId);

  return (
    <TaraAIWrapper $bottomBarClassFlag={bottomBarClassFlag}>
      <AnalysisTimeSection />
      <AppUsageSection />
      <AutoCustomAnalysisSection />
    </TaraAIWrapper>
  );
};

export default TaraAI;
