import React from 'react'
// eslint-disable-next-line import/no-extraneous-dependencies
import { match } from 'path-to-regexp'

export const extractUrlParts = ( url: string, containsHash = false ) : [ boolean, string[] ] => {
	try {
		const parsedUrl = new URL( url )
		const urlParts = parsedUrl.pathname.split( '/' ).filter( ( part ) => part )
		if ( containsHash && parsedUrl.hash ) {
			const hashSegments = parsedUrl.hash.slice( 1 ).split( '/' ).filter( ( part ) => part )
			return [ true, [ ...urlParts, '#', ...hashSegments ] ]
		}
		return [ true, urlParts ]
	} catch ( e ) {
		return [ false, [] ]
	}
}

export const extractParamsFromPattern = ( pattern: string ) : string[] => {
	try {
		const url = new URL( `https://example.com/${ pattern }` )
		const { pathname } = url
		return pathname.split( '/' ).filter( ( part ) => part.startsWith( ':' ) ).map( ( part ) => part.substring( 1 ) )
	} catch ( e ) {
		return []
	}
}

export const displayPattern = ( pattern: string, useSpacing = true ) => {
	if ( typeof pattern !== 'string' ) {
		return pattern
	}
	try {
		const url = new URL( `https://example.com/${ pattern }` )
		const { pathname, hash } = url
		const parts = ( pathname.substring(1) + hash ).split( '/' ).map( ( part ) => {
			return part.startsWith( ':' ) ? (
				<span style={ useSpacing ? {
					marginLeft: '4px',
				} : undefined }>
					{ `{${ part.substring( 1 ) }}` }
				</span>
			) : (
				<span>
					{ part }
				</span>
			)
		} )

		return parts.map( ( part, index ) => {
			return (
				// eslint-disable-next-line react/no-array-index-key
				<React.Fragment key={ index }>
					{ index > 0 ? <span>/</span> : null }
					{ part }
				</React.Fragment>
			)
		} )
	} catch ( e ) {
		return pattern
	}
}

export const extractPathnameFromUrl = ( url: string ): string => {
	try {
		const parsedUrl = new URL( url )
		return parsedUrl.pathname
	} catch ( e ) {
		if ( !url.startsWith( 'http') ) {
			if ( url.startsWith( '/' ) ) {
				// eslint-disable-next-line no-param-reassign
				url = url.substring( 1 )
			}
			return extractPathnameFromUrl( `https://example.com/${ url }` )
		}
		return ''
	}
}

export const processPatternToMatch = ( pattern: string ) => {

    let normalisedPattern: string
    try {
        const parsedUrl = new URL( pattern )
        normalisedPattern = parsedUrl.pathname + ( parsedUrl.hash || '' )
    } catch {
        normalisedPattern = pattern.startsWith( '/' ) ? pattern : `/${ pattern }`
    }

    const [ rawPath, ...hashRest ] = normalisedPattern.split( '#' )
    const hasHash = hashRest.length > 0
    const rawHash = hasHash ? hashRest.join( '#' ) : ''

    const substitute = ( str: string, offset = 0 ) => str
        .replaceAll( '**', '\u0000' )
        .split( '*' )
        .map( ( part, index ) => index === 0 ? part : `:${ offset + index - 1 }${ part }` )
        .join( '' )

    const pathStarCount = ( rawPath.replaceAll( '**', '' ).match( /\*/g ) || [] ).length

    const pathSubstituted = substitute( rawPath )
    const usePath = pathSubstituted.replaceAll( '\u0000', '/(.*)' )
    const usePathOptional = pathSubstituted.replaceAll( '\u0000', '(.*)' )

    const isIgnoreEnd = normalisedPattern.endsWith( '**' )

    const pathMatchFn = match( usePath )
    const pathMatchFnOptional = match( usePathOptional )

    let hashMatchFn: ReturnType<typeof match> | null = null
    let hashMatchFnOptional: ReturnType<typeof match> | null = null
    if ( hasHash ) {
        const hashSubstituted = `#${ substitute( rawHash, pathStarCount ) }`
        const useHash = hashSubstituted.replaceAll( '\u0000', '/(.*)' )
        const useHashOptional = hashSubstituted.replaceAll( '\u0000', '(.*)' )
        hashMatchFn = match( useHash )
        hashMatchFnOptional = match( useHashOptional )
    }

    return ( testUrl: string ) => {
        const url = new URL( testUrl )
        const pathResult = pathMatchFn( url.pathname ) || pathMatchFnOptional( url.pathname )

        if ( !pathResult ) {
            return null
        }

        if ( isIgnoreEnd ) {
            return { ...( pathResult.params as object ) }
        }

        if ( !hasHash ) {
            return url.hash === '' ? { ...( pathResult.params as object ) } : null
        }

        const hashResult = hashMatchFn!( url.hash ) || hashMatchFnOptional!( url.hash )
        if ( !hashResult ) {
            return null
        }

        return { ...( pathResult.params as object ), ...( hashResult.params as object ) }
    }
}
