/* eslint-disable react/no-unstable-nested-components */
import React, { forwardRef, useMemo, useRef } from 'react';
import { PrinterOutlined } from '@ant-design/icons';
import { Button, Table, Skeleton } from 'antd';
import ReactHtmlParser from 'react-html-parser';
import ReactToPrint from 'react-to-print';
import styled, { css } from 'styled-components';

const StyledInvoice = styled.div`
  padding: 10px 0;
  table tr th,
  table tr td,
  h2,
  p {
    color: #505050;
  }
  .ant-table-thead th {
    background: #fff;
  }

  table {
    margin: 30px 0;
    border: 1px solid #d0d2d7;
    border-spacing: 0;
    border-bottom: 0;
    border-left: 0;
    backgroundcolor: '#fff';
  }
  table tr th,
  table tr td {
    padding: 10px;
    border: 1px solid #d0d2d7;
    border-right: 0;
    border-top: 0;
    border-spacing: 0;
  }
  @media print {
    padding: 50px 50px;
    border: 0;
    .invoice-wrapper .ant-modal-close {
      display: none;
    }

    thead {
      border-top: 0;
    }
    *::before,
    *::after,
    table {
      border: 0;
    }
    table tr th,
    table tr td {
      border: 1px solid #d0d2d7;
      border-bottom: 0;
      border-right: 0;
    }
    table {
      border-bottom: 1px solid #d0d2d7;
      border-right: 1px solid #d0d2d7;
    }
  }
  ${({ lineItems }) =>
    lineItems &&
    css`
      table {
        margin: 30px 0;
        border: 1px solid #d0d2d7;
        border-spacing: 0;
        border-bottom: 0;
        backgroundcolor: #fff;
      }
      table tr th,
      table tr td {
        padding: 10px;
        border: 1px solid #d0d2d7;
        border-right: 0;
        border-left: 0;
        border-top: 0;
        border-spacing: 0;
      }
      @media print {
        table {
          border: 1px solid #d0d2d7;
          border-spacing: 0;
        }
        table tr th,
        table tr td {
          padding: 10px;
          border: 1px solid #d0d2d7;
          border-right: 0;
          border-left: 0;
          border-top: 0;
          border-spacing: 0;
        }
      }
    `}
`;

const TitleDiv = styled.div`
  display: flex;
  width: 100%;
  border: 0;
`;

const LeftDiv = styled.div`
  border: 0;
  padding: 0 10px 0 0;
  verticalalign: top;
  img {
    width: 150px;
    margin: 0 0 10px;
  }
  h2 {
    fontsize: 24px;
    marginbottom: 10px;
  }
`;

const RightDiv = styled.div`
  width: 230px;
  border: 0;
  margin-left: auto;
  span {
    display: inline-block;
    width: 65px;
  }
  p {
    color: #505050;
    margin: 8px 0;
  }
`;

const BillToDiv = styled.div`
  padding: 0px;
  border: 0;
  vertical-align: top;
  width: 50%;
  strong {
    color: #444444;
  }
`;

const PairDiv = styled.div`
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  width: 230px;
`;

const StyledKey = styled.span`
  display: inline-block;
  width: 65px;
  font-weight: 500;
`;

const StyledValue = styled.span`
  word-break: break-all;
  line-height: normal;
  span {
    color: green;
  }
`;

const BillingDiv = styled.div`
  display: flex;
  justify-content: space-between;
`;

const DescDiv = styled.div`
  padding: 10px;
  p {
    margin-bottom: 0;
    line-height: normal;
  }
`;

const StyledParagraph = styled.p`
  font-weight: 500;
  color: #505050 !important;
`;

const StyledCellSummary = styled(Table.Summary.Cell)`
  font-weight: 500;
  span {
    margin-left: 24px;
  }
`;

const StyledTitleCellSummary = styled(StyledCellSummary)`
  display: flex;
  justify-content: end;
  span {
    position: relative;
    left: 28px;
  }
`;

const columns = [
  {
    title: 'Description',
    width: 300,

    render: (record) => (
      <div>
        {record?.plan === 'overage' ? (
          `Overage session ${record?.extraSessions} recording ${record?.extraVideos} events ${record?.extraEvents} from ${record?.billingPeriodStartDate} to ${record?.billingPeriodEndDate}`
        ) : (
          <p>
            Subscribed to <span key={record?.plan}>{record?.plan}</span> 
            {/* NOTE: done for CX-1441 [may need this later] */}
            {/* with{' '}
            <span key={record?.videoCount}>{record?.videoCount}</span> videos */}
            from{' '}
            <strong key={record?.billingPeriodStartDate}>
              {record?.billingPeriodStartDate}
            </strong>{' '}
            to{' '}
            <strong key={record?.billingPeriodEndDate}>
              {record?.billingPeriodEndDate}
            </strong>
          </p>
        )}
      </div>
    ),
  },
  {
    title: 'Plan Type',
    width: 100,
    dataIndex: 'planType',
    key: 'planType',
  },
  {
    title: 'Amount',
    width: 100,
    key: 'amount',
    render: (record) => <span>{`USD $${record?.amount}`}</span>,
  },
  {
    title: 'Status',
    width: 100,
    key: 'status',
    render: (record) => <strong>{record?.status}</strong>,
  },
];

const columns2 = [
  {
    title: 'Description',
    width: '70%',

    render: (record) => (
      <DescDiv>
        <StyledParagraph>{record?.description}</StyledParagraph>
        {record?.entityType === 'plan_item_price' && (
          <p>{`${record?.dateFrom} to ${record?.dateTo}`}</p>
        )}
      </DescDiv>
    ),
  },
  {
    title: 'Amount (USD)',
    key: 'amount',
    width: '15%',
    align: 'center',
    render: (record) => <strong>{`$${record?.amount}`}</strong>,
  },
];

const ComponentToPrint = forwardRef((props, ref) => {
  const transaction = props?.invoiceReceipt?.transaction;

  const hasLineItems = useMemo(
    () => transaction?.lineItems?.length,
    [transaction]
  );
  return (
    <StyledInvoice ref={ref} lineItems={hasLineItems > 0}>
      <TitleDiv>
        <LeftDiv>
          <img src="/static/uxcam-new-logo.svg" alt="UXCam" />
          <h2>INVOICE</h2>
        </LeftDiv>

        <RightDiv>
          <p>
            <strong>UXCam Inc.</strong>
          </p>
          <p>
            315 Montgomery St, 10th Floor
            <br />
            San Francisco, CA, 94104 <br />
            U.S.A.
          </p>
          <p>
            <span>
              <strong>Tax ID</strong>
            </span>
            : 471651508
          </p>
        </RightDiv>
      </TitleDiv>

      <BillingDiv>
        <BillToDiv>
          {transaction?.invoiceAddress && (
            <>
              <strong>Bill to:</strong>
              <p>{ReactHtmlParser(transaction?.invoiceAddress)}</p>
            </>
          )}
        </BillToDiv>

        <PairDiv>
          <div>
            <StyledKey>Date</StyledKey>
            <StyledValue>
              {': '}
              {transaction?.invoiceDate}
            </StyledValue>
          </div>
          <div>
            <StyledKey>Invoice #</StyledKey>
            <StyledValue>
              {': '}
              {transaction?.invoiceId}
            </StyledValue>
          </div>
          {hasLineItems && (
            <div>
              <StyledKey>Status</StyledKey>
              <StyledValue>
                {': '}
                <span>{transaction?.status?.toUpperCase()}</span>
              </StyledValue>
            </div>
          )}
        </PairDiv>
      </BillingDiv>

      {hasLineItems ? (
        <Table
          columns={columns2}
          dataSource={transaction?.lineItems}
          pagination={{ position: ['none', 'none'] }}
          summary={() => (
            <Table.Summary.Row>
              <StyledTitleCellSummary index={0}>
                {' '}
                <span>Total</span>{' '}
              </StyledTitleCellSummary>
              <StyledCellSummary index={1}>
                {' '}
                <span>{`$${transaction?.amount}`}</span>{' '}
              </StyledCellSummary>
            </Table.Summary.Row>
          )}
        />
      ) : (
        <Table
          columns={columns}
          dataSource={[transaction]}
          summary={() => (
            <Table.Summary fixed="bottom">
              <Table.Summary.Row>
                <Table.Summary.Cell colSpan={3}>Total</Table.Summary.Cell>
                <Table.Summary.Cell>
                  {' '}
                  <strong key={transaction?.amount}>
                    USD ${transaction?.amount}
                  </strong>
                </Table.Summary.Cell>
              </Table.Summary.Row>
            </Table.Summary>
          )}
          pagination={{ position: ['none', 'none'] }}
        />
      )}

      <p>
        This is only for your records, no payment is due. If you have any
        questions, please contact us at team@uxcam.com. Thank you for your
        business!
      </p>
    </StyledInvoice>
  );
});

const NewInvoice = ({invoiceReceipt, loading }) => {
  const componentRef = useRef();
  
  return (
    <Skeleton loading={loading}>
      <ComponentToPrint invoiceReceipt={invoiceReceipt} ref={componentRef} />
      <ReactToPrint
        trigger={() => (
          <Button type="primary" key="submit" icon={<PrinterOutlined />}>
            Print
          </Button>
        )}
        content={() => componentRef.current}
      />
    </Skeleton>
  );
};

export default NewInvoice;
