import React, { memo, useState } from 'react';
import { Upload, Button, Spin, message } from 'antd';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';
import { LoadingOutlined } from '@ant-design/icons';

import ProfileImageOrText from 'components/features/setting/ProfileImageOrText';
import { updateImage, uploadImage } from 'redux/actions/profile';
import { convertFileToBase64 } from 'Utils/helpers/commonUtils';

const UploadButton = styled(Button)`
  color: #5d97ff;
  border-color: #5d97ff;
  margin-left: 18px;
`;

const acceptType = 'image/jpeg, image/jpg, image/png';
const fileName = 'profileImage';
const fileType = 'picture';

const ProfilePhoto = () => {
  const [loading, setLoading] = useState(false);
  const dispatch = useDispatch();

  const { profileReducer: user } = useSelector((state) => state);
  const { profilePicture, name, email } = user;

  const beforeUpload = (file) => {
    const { type, size } = file;
    const isJpgOrPng = acceptType.includes(type);
    const isMaxSize = size / 1024 / 1024 < 2;
    if (!isJpgOrPng) {
      message.error('Only files with these extensions are allowed: png, jpg, jpeg.');
    }
    if (!isMaxSize) {
      message.error('Image must be smaller than 2MB.');
    }
    return isJpgOrPng && isMaxSize;
  };

  const handleImageUpload = async (options) => {
    const file = options?.file;
    if (!beforeUpload(file)) return;
  
    setLoading(true);
  
    try {
      const base64String = await convertFileToBase64(file);
  
      if (!base64String) {
        message.error("Failed to convert image to Base64.");
        setLoading(false);
        return;
      }
  
      const payload = { profileImage: base64String };
      const response = await dispatch(updateImage(payload));
  
      if (response?.success) {
        dispatch(uploadImage(response?.data?.profile?.profilePicture));
        message.success(response?.data?.message);
      } else {
        message.error(response?.error?.profileImage?.[0] || "Image upload failed.");
      }
    } catch (error) {
      message.error("An error occurred while processing the image.");
    } finally {
      setLoading(false);
    }
  };
  

  return (
    <>
      <Spin spinning={loading} indicator={<LoadingOutlined />} size="small">
        <ProfileImageOrText
          picture={profilePicture}
          size={80}
          nameInfo={name || email}
          shape="circle"
        />
      </Spin>

      <Upload
        name={fileName}
        customRequest={handleImageUpload}
        accept={acceptType}
        listType={fileType}
        showUploadList={false}
        maxCount={1}
      >
        <UploadButton disabled={loading}>Choose image</UploadButton>
      </Upload>
    </>
  );
};

export default memo(ProfilePhoto);
