import React from 'react'
import styled from 'styled-components'
import IconPlus from 'public/static/icon-plus-circle.svg';
import IconClose from 'public/static/close-new.svg';
import { Button } from 'uxcam-frontend-components';
import ButtonNew from 'components/common/ButtonNew';
import { useClickOutside } from 'hooks/useOnClickOutside';

const StaticContainer = styled.div`
	display: flex;
	flex-wrap: wrap;
	position: relative;
	gap: 8px;
	button {
		font-weight: 400;
		font-size: 14px;
		line-height: 24px;
		svg {
			margin-right: 2px;
		}
		&:not( :hover ) {
			background-color: #F3F4F5;
			color: #49576E;
		}
	}
`

const StaticChip = styled.div`
	font-size: 14px;
	line-height: 24px;
	height: fit-content;
	font-weight: 400;
	font-family: 'Roboto', sans-serif;
	color: #49576E;
	background-color: #E8E8EB;
	padding: 0 6px;
	border-radius: 4px;
`

const InputContainer = styled.div`
	display: flex;
	flex-direction: column;
`

const InputChipContainer = styled.div`
	display: flex;
	flex-wrap: wrap;
	width: 100%;
	border: 1px solid #E8E8EB;
	border-radius: 6px;
	padding: 5px 10px 0 10px;
	margin-bottom: 8px;
`

const InputChipWrapper = styled.div`
	display: flex;
	flex-wrap: wrap;
	margin-bottom: 5px;
	margin-right: 8px;
	gap: 8px;
`

const InputChip = styled( StaticChip )`
	display: flex;
   align-items: center;
	background-color: #DFEAFF;
	border-radius: 4px;
	color: #161E35;
	font-size: 12px;
	line-height: 18px;
	font-weight: 400;
	font-family: 'Roboto', sans-serif;
	cursor: default;
	padding-right: 3px;
	margin-right: 0px;
	button {
		padding: 0;
		margin: 0;
		background: transparent;
		border: none;
		height: 16px;
		width: 16px;
		cursor: pointer;
		svg {
			height: 16px;
			width: 16px;
		}
	}
`

const Error = styled.div`
	font-size: 12px;
	line-height: 18px;
	color: #F4584C;
`

const Buttons = styled.div`
	display: flex;
	gap: 8px;
	margin-top: 8px;
	button {
		min-width: 0 !important;
		padding-left: 36px;
		padding-right: 36px;
	}
`

const Input = styled.input`
	flex: 1;
	font-size: 12px;
	line-height: 18px;
	color: #161E35;
	padding: 0;
	margin: 0;
	border: none;
	min-width: 150px;
	margin-bottom: 5px;
	&::placeholder {
		color: #737886;
	}
`

const ChipInput = ( { data, callback, inputPlaceholder, regex, loading, btnLabel } ) => {
	const [ isEdit, setIsEdit ] = React.useState( false )
	const [ localData, setLocalData ] = React.useState( [] )
	const [ inputVal, setInputVal ] = React.useState( '' )
	const [ error, setError ] = React.useState( null )
	const [ initialDataUpdated, setInitialDataUpdated ] = React.useState( false )

	const timeout = React.useRef( null )
	const chipContainerRef = React.useRef( null )
	const handleAdd = React.useCallback( () => setIsEdit( true ), [] )

	const handleRemove = React.useCallback( ( element ) => {
		setLocalData( prevValue => prevValue.filter( item => item !== element ) )
	}, [] )

	const checkRegex = React.useCallback( ( value ) => regex ? regex.test( value ) : true, [ regex ] )
	const addEmail = React.useCallback( ( value ) => {
		const newVal = value.trim()

		if ( !newVal ) {
			setInputVal( '' )
			return false
		}
		
		if ( !checkRegex( newVal ) ) {
			setError( 'Please enter a valid email' )
			timeout.current = setTimeout( () => setError( null ), 4000 )
			return false
		}
		
		if ( localData?.includes( newVal ) ) {
			setError( 'Email already exists' )
			timeout.current = setTimeout( () => setError( null ), 4000 )
			return false
		}

		const newLocalData = [ ...localData, newVal ]
		setLocalData( newLocalData )
		setInputVal( '' )
		return newLocalData
	}, [ checkRegex, localData ] )
	
	const handleSave = React.useCallback( ( { noCallback = false } ) => {
		const callbackFn = noCallback ? () => null : callback
		if ( inputVal?.length ) {
			const newLocalData = addEmail( inputVal )
			if ( !newLocalData ) {
				return
			}
			callbackFn( newLocalData )

		} else if ( !localData?.length && !inputVal?.length && data?.length ) {
			callbackFn( [] )
		} else if ( JSON.stringify( data ) !== JSON.stringify( localData ) ) {
			callbackFn( localData )
		}
		
		if ( !noCallback ) {
			setIsEdit( false )
		}
		setInputVal( '' )
	}, [ localData, data, callback, addEmail, inputVal ] )
	
	const handleCancel = React.useCallback( () => {
		setLocalData( data || [] )
		setIsEdit( false )
		setInputVal( '' )
	}, [ data ] )

	const handleKeyDown = React.useCallback( ( e ) => {
		setError( null )

		if ( [ 188, 32, 13 ].includes( e.keyCode ) ) {
			addEmail( e.target.value )
		}

		// Backspace
		if ( e.keyCode === 8 && !inputVal ) {
			if ( localData?.length ) {
				setLocalData( localData.slice( 0, -1 ) )
			}
		} 
	}, [ localData, inputVal, addEmail ] )

	const handleOnChange = React.useCallback( ( e ) => {
		const val = e.target.value

		if ( !val.includes( ',' ) ) {
			setInputVal( val.trim() )
		}
	}, [] )

	useClickOutside( chipContainerRef, () => {
		handleSave( { noCallback: true } )
	} )

	React.useEffect( () => {
		if ( !initialDataUpdated && !localData?.length && data ) {
			setLocalData( data || [] )
			setInitialDataUpdated( true )
		}
	}, [ data, localData, initialDataUpdated ] )

	React.useEffect( () => {
		return () => {
			clearTimeout( timeout.current )
		}
	}, [] )
	
	if ( isEdit ) {
		return (
			<InputContainer ref={ chipContainerRef }>
				<InputChipContainer>
					<InputChipWrapper>
						{ localData?.map( ( element ) => (
							<InputChip key={ element }>
								{ element }
								<button type="button" onClick={ () => handleRemove( element ) } disabled={ loading }>
									<IconClose />
								</button>
							</InputChip>
						) ) }
					</InputChipWrapper>
					<Input
						placeholder={ inputPlaceholder }
						onKeyDown={ handleKeyDown }
						value={ inputVal }
						onChange={ handleOnChange }
					/>
				</InputChipContainer>
				{ !!error && (
					<Error>
						{ error }
					</Error>
				) }
				<Buttons>
					<Button
						variant="primary"
						size='large'
						onClick={ handleSave }
						disabled={ loading }
					>
						Save
					</Button>
					<Button
						variant="ghost"
						size='large'
						onClick={ handleCancel }
					>
						Cancel
					</Button>
				</Buttons>
			</InputContainer>
		)
	}

	return (
		<StaticContainer>
			{ ( data || [] ).map( ( element ) => (
				<StaticChip key={ element }>
					{ element }
				</StaticChip>
			) ) }
			<ButtonNew
				onClick={ handleAdd }
				variant="ghost"
				size="medium"
				disabled={ loading }
			>
				<IconPlus />
				{ btnLabel }
			</ButtonNew>
		</StaticContainer>
	)
}

export default ChipInput
