import appApi from 'services/appApi';

export const getSSOConfiguration = (orgId) => async dispatch => {
    try {
      const response = await appApi.getSSOConfiguration(orgId);
      dispatch({ type: 'GET_SSO_CONFIG', data: response.data.data })
    } catch (err) {
      const message =  err?.response?.data?.error?.status === 403 ? 'You are not allowed to perform this operation' : 'Something went wrong! Please try again later!';
      dispatch({ type: 'GET_SSO_CONFIG_ERR', data: message });
    }
  }

export const setSingleSignOn = data => ({ type: 'SET_SINGLE_SIGN_ON', data })

export const clearSSOConfigurations = (spEntityUrl, spAcsUrl ) => ({ type: 'CLEAR_SSO_CONFIG', data : {
    ssoUrl: '',
    entityId: '',
    certificate: '',
    loginUrl: '',
    spEntityId: spEntityUrl,
    spAcsUrl,
  }})
