import React, { useCallback, useEffect, useState } from 'react';
import {
  CopyOutlined,
  ExclamationCircleOutlined,
  DeleteOutlined,
  EyeInvisibleOutlined,
  EyeOutlined,
  InfoCircleOutlined,
  RetweetOutlined,
} from '@ant-design/icons';
import {
  Alert,
  Button,
  Input,
  Modal,
  Segmented,
  Tag,
  Tooltip,
  message,
} from 'antd';
import { CopyToClipboard } from 'react-copy-to-clipboard';
import AppApi from 'services/appApi';
import InfoBox from 'components/common/InfoBox';
import { isProd } from 'Utils/constants/variables';

// Same host and same version as `_pURL` in PublicApiAccess: a customer
// integrating both APIs wires up one prefix, not two. v2 is the only prefix
// we hand out or document.
//
// Built from the unversioned PYTHON_API_URL rather than PYTHON_API_URL_V2 so
// the prefix is visible here: that var was removed from .buildenv once before,
// which is what left the panel rendering `undefined/session`.
const deletionUrl = `${
  isProd ? 'https://api.uxcam.com/v2' : `${process.env.PYTHON_API_URL}/v2`
}/deletion`;

/**
 * Request/response snippets for the Data Deletion API.
 *
 * One box with two switchers, the same shape as the Tara data-access panel:
 * the operation on top, the endpoint it posts to, then the language. Three
 * stacked code blocks per operation would have been nine, and a reader only
 * ever wants one.
 */
const OPERATIONS = [
  { value: 'users', label: 'Delete users' },
  { value: 'sessions', label: 'Delete sessions' },
  { value: 'status', label: 'Check status' },
];

const LANGUAGES = [
  { value: 'curl', label: 'curl' },
  { value: 'javascript', label: 'JavaScript' },
  { value: 'python', label: 'Python' },
];

/**
 * The endpoint one operation posts to.
 *
 * `/status` is a path segment, so it must go BEFORE the query string.
 * Appending it to a URL that already carried `?appid=` produced
 * `.../deletion?appid=<id>/status`, which is a different, non-existent
 * endpoint -- and it looked plausible enough in the panel to miss.
 *
 * Shared by the snippet builder and the endpoint line above it, so the URL a
 * reader sees is by construction the one the snippet below it calls.
 */
const endpointFor = (operation, baseUrl, appId) =>
  `${operation === 'status' ? `${baseUrl}/status` : baseUrl}?appid=${appId}`;

// Every identifier field takes a list, and each field appears once.
const PAYLOADS = {
  users: {
    subjectType: 'user',
    selector: {
      kind: 'identifiers',
      identifiers: [
        { uxcamUserId: ['<uxcamUserId>'] },
        { userId: ['<yourUserId>'] },
      ],
    },
    reason: 'GDPR erasure request',
  },
  sessions: {
    subjectType: 'session',
    selector: {
      kind: 'identifiers',
      identifiers: [{ sessionId: ['<sessionId>', '<sessionId2>'] }],
    },
  },
  status: { requestId: '<requestId>' },
};

/**
 * Builds one snippet.
 *
 * `token` is what the reveal toggle is currently showing -- the placeholder
 * while masked, the real key once revealed -- so a snippet copied out of a
 * masked panel can go into a ticket, and one copied from a revealed panel
 * runs as-is.
 */
const buildSnippet = ({ operation, language, baseUrl, appId, token }) => {
  const endpoint = endpointFor(operation, baseUrl, appId);
  const payload = PAYLOADS[operation];
  const pretty = JSON.stringify(payload, null, 2);

  if (language === 'curl') {
    return [
      `curl -X POST '${endpoint}' \\`,
      `  -H 'Authorization: Bearer ${token}' \\`,
      "  -H 'Content-Type: application/json' \\",
      `  -d '${JSON.stringify(payload)}'`,
    ].join('\n');
  }

  if (language === 'javascript') {
    return [
      `const res = await fetch('${endpoint}', {`,
      "  method: 'POST',",
      '  headers: {',
      `    Authorization: 'Bearer ${token}',`,
      "    'Content-Type': 'application/json',",
      '  },',
      `  body: JSON.stringify(${pretty.replace(/\n/g, '\n  ')}),`,
      '});',
      'const data = await res.json();',
    ].join('\n');
  }

  return [
    'import requests',
    '',
    `res = requests.post(`,
    `    "${endpoint}",`,
    `    headers={`,
    `        "Authorization": "Bearer ${token}",`,
    '        "Content-Type": "application/json",',
    '    },',
    `    json=${pretty.replace(/\n/g, '\n    ').replace(/true/g, 'True')},`,
    '    timeout=30,',
    ')',
    'res.raise_for_status()',
    'data = res.json()',
  ].join('\n');
};

/**
 * Data Deletion API — the Deletion Key and the endpoints that use it.
 *
 * Laid out to match `PublicApiAccess` row for row, because a customer reads
 * these two tabs the same way. Where it differs, it differs on purpose:
 *
 *  - The value is never typed. The public key is generated in the browser and
 *    POSTed up; this one is minted server-side with a CSPRNG, so there is no
 *    editable input and no Save. A user-chosen deletion key is a guessable
 *    one.
 *  - It is masked by default and revealed on demand, then shown automatically
 *    the moment it is generated, which is when it needs copying.
 *  - Generating over an existing key, and revoking, both confirm first. Each
 *    breaks whatever is using the current key the instant it runs.
 *
 * The tab is only rendered for organisation owners and admins (`app.delete`).
 * This component still renders the server's 403, so the UI cannot offer an
 * action the API would refuse.
 */
const DeletionApiKey = ({ appId }) => {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [state, setState] = useState(null);
  const [revealed, setRevealed] = useState(false);
  const [forbidden, setForbidden] = useState(false);
  const [operation, setOperation] = useState('users');
  const [language, setLanguage] = useState('curl');

  const load = useCallback(async () => {
    if (!appId) return;
    setLoading(true);
    try {
      const res = await AppApi.getDeletionApiKey(appId);
      setState(res?.data?.data || null);
      setForbidden(false);
    } catch (err) {
      if (err?.response?.status === 403) {
        setForbidden(true);
      } else if (err?.response?.status !== 404) {
        message.error(
          err?.response?.data?.error?.message ||
            'Could not load the Deletion Key.'
        );
      }
    } finally {
      setLoading(false);
    }
  }, [appId]);

  useEffect(() => {
    load();
  }, [load]);

  const failed = (err, fallback) =>
    message.error(err?.response?.data?.error?.message || fallback);

  const generate = async (rotate) => {
    setSaving(true);
    try {
      const res = await AppApi.saveDeletionApiKey(appId, rotate);
      setState(res?.data?.data || null);
      setRevealed(true);
      message.success(
        rotate
          ? 'Deletion Key regenerated — the previous key no longer works, '
            + 'copy the new one now'
          : 'Deletion Key generated'
      );
    } catch (err) {
      failed(err, 'Could not generate the Deletion Key.');
    } finally {
      setSaving(false);
    }
  };

  // Regenerating is destructive and irreversible for the OLD key: the server
  // overwrites `deletionApiKey`, so the previous value stops authenticating
  // the moment this returns. Verified against staging -- old key 400 (auth
  // passed) before, 401 after, with no propagation delay. So this asks
  // first, states the consequence in full, and puts the consequence in the
  // title rather than a soft "are you sure".
  const confirmGenerate = () => {
    Modal.confirm({
      title: 'Regenerating will break your current integration',
      icon: <ExclamationCircleOutlined style={{ color: '#faad14' }} />,
      okText: 'Yes, regenerate the key',
      cancelText: 'Keep the current key',
      okButtonProps: { danger: true },
      width: 520,
      content: (
        <>
          <p style={{ marginBottom: 8 }}>
            The current Deletion Key stops working <strong>immediately</strong>
            . Any service still using it starts receiving{' '}
            <code>401 Unauthorized</code> until you give it the new key.
          </p>
          <p style={{ marginBottom: 0 }}>
            There is no grace period and the old key cannot be recovered. Only
            do this if you are ready to update every caller, or if you believe
            the current key has been exposed.
          </p>
        </>
      ),
      onOk: () => generate(true),
    });
  };

  const revoke = () => {
    Modal.confirm({
      title: 'Revoking will switch the Deletion API off for this app',
      icon: <ExclamationCircleOutlined style={{ color: '#ff4d4f' }} />,
      okText: 'Yes, revoke the key',
      cancelText: 'Keep the current key',
      okButtonProps: { danger: true },
      width: 520,
      content: (
        <>
          <p style={{ marginBottom: 8 }}>
            The key is destroyed and cannot be recovered, and deletion is
            switched off for this app. Every deletion request is refused until
            a new key is generated.
          </p>
          <p style={{ marginBottom: 0 }}>
            Deletions already accepted are unaffected — they are queued and
            will still complete.
          </p>
        </>
      ),
      onOk: async () => {
        setSaving(true);
        try {
          const res = await AppApi.revokeDeletionApiKey(appId);
          setState(res?.data?.data || null);
          setRevealed(false);
          message.success('Deletion Key revoked');
        } catch (err) {
          failed(err, 'Could not revoke the Deletion Key.');
        } finally {
          setSaving(false);
        }
      },
    });
  };

  const copy = (e) => {
    e.stopPropagation();
    e.preventDefault();
    message.success('copied');
  };

  if (forbidden) {
    return (
      <div className="api-wrapper">
        <InfoBox
          type="info"
          marginBottom={18}
          content={
            <>
              The Deletion Key authorises permanent erasure of user data, so
              only organisation owners and admins can view or manage it.
            </>
          }
        />
      </div>
    );
  }

  const key = state?.deletionKey;
  // Active means "the API will actually accept a request", which needs BOTH:
  // the enrolment flag opens the gate (403 without it) and the key is what the
  // Bearer token is compared against (`bool(expected) and compare_digest`), so
  // a flag set with no key still refuses everything. Reporting that as Active
  // would be the one wrong thing this row could say.
  const active = Boolean(state?.deletionEnabled) && Boolean(key);
  // Last four characters, in the clear. Twenty-four identical bullets told you
  // a key existed and nothing else -- with no way to tell which key is live
  // without revealing it, you cannot check a rotation took effect, or which of
  // two keys in your vault is the current one. Four characters of a 43-char
  // CSPRNG token are not a meaningful head start for a guesser, and the same
  // last-four convention is what every card and token UI uses.
  const maskedKey =
    key && key.length > 4 ? `${'•'.repeat(20)}${key.slice(-4)}` : '•'.repeat(24);
  // No empty-string arm: the only consumer is the Deletion Key row, which is
  // not rendered at all unless `key` is set.
  const displayedKey = revealed ? key : maskedKey;

  // Follows the reveal toggle: masked yields a shareable placeholder, revealed
  // yields a snippet that runs as-is. The user has already made that choice
  // for the field above; the snippet honours it rather than deciding again.
  const token = revealed && key ? key : '<deletionApiKey>';
  const endpoint = endpointFor(operation, deletionUrl, appId);
  const snippet = buildSnippet({
    operation,
    language,
    baseUrl: deletionUrl,
    appId,
    token,
  });

  return (
    <div className="api-wrapper">
      {/*
        A warning, not an info note. This panel arms an irreversible operation,
        and the first thing a reader needs is the consequence -- not a
        description of the feature. Everything here is something the reader has
        to act on or accept; nothing describes what we built or changed.
      */}
      <Alert
        type="warning"
        showIcon
        className="deletion-warning"
        message="Deletions are permanent and cannot be undone."
        description={
          <>
            Users and their sessions disappear from every dashboard, export and
            API immediately, and are erased from storage within 7 days.
            Requests are authenticated with the Deletion Key below — anyone
            holding it can erase this app&apos;s data without dashboard access.{' '}
            <a
              href="https://developer.uxcam.com/docs/deletion-api"
              style={{ textDecoration: 'underline' }}
              target="_blank"
              rel="noreferrer"
            >
              Read the deletion API docs
            </a>
            .
          </>
        }
      />

      <div className="api-form">
        <div className="form-item form-label">
          App ID{' '}
          <Tooltip title="Unique identifier of your app to be provided as an argument in the API call.">
            <InfoCircleOutlined />
          </Tooltip>
        </div>
        <div className="form-item">
          <p>{appId || ''}</p>
        </div>
        <div className="form-item">
          <CopyToClipboard text={appId}>
            <Tooltip placement="topLeft" title="Copy App ID" arrowPointAtCenter>
              <Button onClick={copy} size="small" style={{ border: 0 }}>
                <CopyOutlined style={{ marginLeft: -4 }} />
              </Button>
            </Tooltip>
          </CopyToClipboard>
        </div>
      </div>

      {/*
        Only once a key exists. An empty input reading "No Deletion Key yet"
        was a control that could not be used, next to a label describing a
        thing that did not exist -- the Status row below already says so, and
        says what to do about it. Per Ekata's review.
      */}
      {key && (
        <div className="api-form">
          <div className="form-item form-label">
            Deletion Key{' '}
            <Tooltip title="A key used only by the Data deletion API, sent as an Authorization Bearer token. It is generated for you and cannot be chosen. Please note that anyone holding this key can permanently erase your users' data, even without access to the dashboard.">
              <InfoCircleOutlined />
            </Tooltip>
          </div>
          <div className="form-item">
            <Input readOnly value={displayedKey} />
          </div>
          <div className="form-item">
            <Tooltip
              placement="topLeft"
              title={revealed ? 'Hide Deletion Key' : 'Reveal Deletion Key'}
              arrowPointAtCenter
            >
              <Button
                onClick={() => setRevealed(!revealed)}
                size="small"
                style={{ border: 0 }}
                icon={revealed ? <EyeInvisibleOutlined /> : <EyeOutlined />}
              />
            </Tooltip>
            <CopyToClipboard text={key}>
              <Tooltip
                placement="topLeft"
                title="Copy Deletion Key"
                arrowPointAtCenter
              >
                <Button onClick={copy} size="small" style={{ border: 0 }}>
                  <CopyOutlined style={{ marginLeft: -4 }} />
                </Button>
              </Tooltip>
            </CopyToClipboard>
          </div>
        </div>
      )}

      {/*
        A state badge, not a sentence that has to be read to find out which
        state you are in -- the two states are now told apart by colour and a
        two-word label, and the sentence beside it only says what follows from
        that. antd's own Tag, so it matches every other status pill in the
        dashboard. Per Ekata's review.
      */}
      <div className="api-form">
        <div className="form-item form-label">Status</div>
        <div className="form-item">
          {loading ? (
            <p style={{ margin: 0, color: '#8c8c8c' }}>Loading…</p>
          ) : (
            <p style={{ margin: 0 }}>
              <Tag color={active ? 'green' : 'default'}>
                {active ? 'Active' : 'Not set up'}
              </Tag>
              <span style={{ color: '#8c8c8c' }}>
                {active
                  ? 'the Deletion API will accept requests for this app'
                  : 'generate a Deletion Key to start accepting deletion '
                    + 'requests. Until then, every request is refused.'}
              </span>
            </p>
          )}
        </div>
      </div>

      {state?.enrolledBy && (
        <div className="api-form">
          <div className="form-item form-label">Last changed</div>
          <div className="form-item">
            {/*
              When first, then who. The question this row answers is "is this
              the key I issued last Tuesday?", so the timestamp is what gets
              scanned; the address is the qualifier.
            */}
            <p style={{ margin: 0 }}>
              {state.enrolledAt
                ? `${new Date(state.enrolledAt).toLocaleString()} · `
                : ''}
              {state.enrolledBy}
            </p>
          </div>
        </div>
      )}

      <div className="api-footer">
        <Button
          onClick={key ? confirmGenerate : () => generate(false)}
          icon={<RetweetOutlined />}
          loading={saving}
          disabled={loading}
        >
          {key ? 'Regenerate Deletion Key' : 'Generate Deletion Key'}
        </Button>
        {key && (
          <Button
            onClick={revoke}
            icon={<DeleteOutlined />}
            loading={saving}
            danger
            style={{ marginLeft: 10 }}
          >
            Revoke
          </Button>
        )}
      </div>

      {key && (
        <div className="api-form call-the-api">
          <div className="form-item form-label">Call the API</div>
          <div className="form-item snippet-panel">
            <Segmented
              options={OPERATIONS}
              value={operation}
              onChange={setOperation}
            />
            {/*
              The verb and the URL, between the two switchers: the operation
              above chooses them, the snippet below calls them. Without it a
              reader had to read the curl line to find out which of the two
              endpoints "Check status" meant.
            */}
            <div className="endpoint-line">
              <span className="method-badge">POST</span>
              <code>{endpoint}</code>
              <CopyToClipboard text={endpoint}>
                <Tooltip
                  placement="topLeft"
                  title="Copy endpoint URL"
                  arrowPointAtCenter
                >
                  <Button onClick={copy} size="small" className="endpoint-copy">
                    <CopyOutlined />
                  </Button>
                </Tooltip>
              </CopyToClipboard>
            </div>
            <Segmented
              className="language-switch"
              options={LANGUAGES}
              value={language}
              onChange={setLanguage}
            />
            <div className="snippet-body">
              <pre>
                <code>{snippet}</code>
              </pre>
              <CopyToClipboard text={snippet}>
                <Tooltip placement="topLeft" title="Copy snippet" arrowPointAtCenter>
                  <Button onClick={copy} size="small" className="snippet-copy">
                    <CopyOutlined />
                  </Button>
                </Tooltip>
              </CopyToClipboard>
            </div>
            <InfoBox
              type="info"
              marginTop={12}
              content={
                revealed
                  ? 'Copy includes your live Deletion Key, so the request runs as-is.'
                  : 'The key is masked above. Reveal it to copy a snippet that runs as-is.'
              }
            />
          </div>
        </div>
      )}
    </div>
  );
};

export default DeletionApiKey;
