import React, { useState } from 'react';
import { Form, Modal, Button, Input, message } from 'antd';
import styled from 'styled-components';
import { useDispatch } from 'react-redux';

import { updatePassword } from 'redux/actions/profile';

const StyledModal = styled(Modal)`
  .ant-input {
    height: 24px;
  }
  .ant-input-password {
    border-radius: 5px;
  }
  .ant-modal-content,
  .ant-modal-header {
    border-radius: 8px;
  }
`;

const StyledSaveBtn = styled(Button)`
  font-weight: 400;
  font-size: 14px;
  line-height: 14px;
  padding: 10px 22px;
`;

const StyledDiv = styled.div`
  display: flex;
  flex-direction: row-reverse;
  .ant-form-item {
    margin-bottom: 0;
  }
`;

const StyledButton = styled(Button)`
  margin-right: 8px;
`;

export const passwordRegex =  /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*().,'"`~|\\=+\-_*^;:{}\[\]<>/?])[a-zA-Z\d!@#$%^&*().,'"`~|\\=+\-_*^;:{}\[\]<>/?]{12,}$/;

const FormItem = Form.Item;
const { Password } = Input;

const ChangePassword = () => {
  const [visiblePasswordModal, setVisiblePasswordModal] = useState(false);
  const [changePasswordLoading, setChangePasswordLoading] = useState(false);
  const [form] = Form.useForm();

  const dispatch = useDispatch();

  const onFinish = async (values) => {
    if (values?.newpass) {
      setChangePasswordLoading(true);
      const res = await dispatch(updatePassword(values));
      if (res?.success) {
        setVisiblePasswordModal(false);
        message.success(res?.data?.message || res?.message);
      }
      if (res?.error) {
        const updatedFields = Object.keys(res?.error).map((name) => ({
          name,
          errors: [res?.error[name]],
        }));
        form.setFields(updatedFields);
      }
      setChangePasswordLoading(false);
    }
  };
  const onFinishFailed = () => {
    /* */
  };
  const handleCancel = () => {
    setVisiblePasswordModal(false);
    form.resetFields();
  };
  const showModal = () => {
    setVisiblePasswordModal(true);
  };

  return (
    <>
      <StyledButton onClick={showModal}>Change password</StyledButton>
      <StyledModal
        maskClosable={false}
        visible={visiblePasswordModal}
        title="Change password"
        onCancel={handleCancel}
        destroyOnClose
        style={{ top: 270 }}
        footer={null}
      >
        <Form
          form={form}
          onFinish={onFinish}
          onFinishFailed={onFinishFailed}
          autoComplete="off"
        >
          <FormItem
            name="oldpass"
            rules={[
              {
                required: true,
                message: 'Please input your current password.',
              },
            ]}
          >
            <Password placeholder="Current password" />
          </FormItem>

          <FormItem
            name="newpass"
            rules={[
              {
                required: true,
                message: 'Please input your new password.',
              },
              {
                pattern: passwordRegex,
                message:
                  'Password must be a minimum of 12 characters and include at least one lowercase letter, one uppercase letter, one digit, and one special character.',              },
            ]}
          >
            <Password placeholder="New password" />
          </FormItem>

          <StyledDiv>
            <FormItem>
              <StyledSaveBtn
                type="primary"
                htmlType="submit"
                loading={changePasswordLoading}
              >
                Save
              </StyledSaveBtn>
            </FormItem>
          </StyledDiv>
        </Form>
      </StyledModal>
    </>
  );
};
export default ChangePassword;
