import React from 'react';
import { Button, Tooltip } from 'antd';
import styled from 'styled-components';
import { BackIcon } from 'components/shared/Sessions/DetailSideBar/IconSvg/index';
import Router from 'next/router';

import { useSelector } from 'react-redux';

const StyleCloseButton = styled(Button)`
  background: #ffffff;
  border: 0px;
  padding: 0px;
  margin-left: 15px;
  &:hover {
    background: transparent;
    color: #5d97ff;
    border-color: #c0cad9 !important;
    svg {
      path {
        fill: #5d97ff;
      }
    }
  }
`;

const BackToIntegratePage = () => {
  const { _id: appId } = useSelector((state) => state.currentAppReducer);
  const { orgId } = useSelector((state) => state.currentOrgReducer);


  const handleBackToIntegratePage = () => {
    const asURL = appId ? `/integration?appId=${appId}` : `/settings/org/${orgId}/apps`;
    const queryRequest = appId ?  `/integration?appId=${appId}&parentType=${`integration`}` : `/integration?parentType=settings&setting=org_setting&org=${orgId}&org_tab=apps`;
    Router.push(
      queryRequest,
      asURL
    );
  };

  return (
    <Tooltip title="Close">
      <StyleCloseButton
        icon={<BackIcon />}
        onMouseDown={() => handleBackToIntegratePage()}
      />
    </Tooltip>
  );
};

export default BackToIntegratePage;
