/* eslint-disable react/jsx-props-no-spreading */
import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Button, Input, Form, message } from 'antd';
import { getSessionUsage, updateSessionUsage, getWebSessionUsage, updateWebSessionUsage } from 'redux/actions/subscription';
import { DeleteOutlined, PlusOutlined } from '@ant-design/icons';
import { useQueryClient } from 'react-query';
import styled from 'styled-components';
import { theme } from 'theme';

const FormItem = Form.Item;

const SessionUsageCard = styled.div`
  margin-top: 15px;
  border: solid 1px #c0cad0;
  border-radius: 5px;
  .session-usages-card-head {
    padding: 15px 20px 0px;
    h3 {
      font-size: 18px;
      font-weight: 500;
      margin-bottom: 0px;
      color: #161e35;
    }
    p {
      font-size: 14px;
      line-height: 18px;
      margin-top: 7px;
    }
  }
  .session-usages-card-body {
    padding: 20px;
    padding-top: 0px;
    .session-usages-card-element {
      &:not( :first-of-type ) {
        margin-top: -10px;
      }
      &:last-of-type {
        .ant-btn.ant-btn-primary.ant-btn-sm {
          margin-bottom: 0px;
        }
      }
    }
    .session-usage-label {
      margin: 15px 0px 10px;
      color: #161e35;
      font-size: 14px;
      font-weight: 500;
    }
    .ant-input-affix-wrapper {
      border: solid 1px rgba(#49576e, 0.4);
      border-radius: 4px;
      padding: 0px 12px;
      width: 120px;
    }
    .ant-input {
      min-width: 105px;
      height: 34px;
      line-height: 34px;
      border: 0px;
      border-radius: 4px;
    }
    .ant-input-suffix {
      color: rgba(#49576e, 0.6);
    }
    .ant-form-item-explain.ant-form-item-explain-error {
      margin-top: 5px;
    }
  }
  .ant-form-item {
    margin-bottom: 10px;
    display: inline-block;
    width: 100%;
    label {
      color: #49576e;
    }
  }
  .ant-btn.ant-btn-primary {
    width: 90px;
    height: 36px;
    border-radius: 4px;
    font-size: 14px;
    line-height: 34px;
    margin-bottom: 10px;
  }
  .ant-form-item-control {
    .ant-form-item-children {
      .ant-input-number {
        color: #49576e;
        min-width: 123px;
        width: calc(100% - 32px);
        max-width: 132px;
        border: solid 1px #c0cad0;
      }
      .anticon {
        margin-left: 10px;
        &:hover {
          color: #f4584c;
        }
      }
    }

    .ant-btn.dynamic-delete-button {
      height: 36px;
      position: absolute;
      left: 140px;
    }

    .ant-btn-outline {
      height: 30px;
      line-height: 28px;
      font-size: 12px;
      border-color: #5d97ff;
      color: #5d97ff;
      width: 100%;
      max-width: 123px;
      padding-left: 10px;
      padding-right: 10px;
      .anticon {
        margin-left: 0px;
      }
    }
    .ant-btn {
      text-transform: none;
      border: none;
      &.btn-add {
        border: solid 1px #5d97ff;
        color: #5d97ff;
        font-size: 14px;
        border-radius: 4px;
        height: 36px;
      }
    }
  }
`;

const validateRule = [
  {
    required: true,
    message: 'Please enter value.',
  },
  {
    pattern: new RegExp(/^0*(?:[0-9][0-9]?|100)$/),
    message: 'Please enter value between 0 to 100',
  },
];

const SessionUsageAlert = () => {
  const [mobileLoading, setMobileLoading] = useState(false);
  const [webLoading, setWebLoading] = useState(false);
  const [ showMobileSaveButton, setShowMobileSaveButton] = useState(false);
  const [ showWebSaveButton, setShowWebSaveButton] = useState(false);

  const dispatch = useDispatch();
  const [ formMobile ] = Form.useForm();
  const [ formWeb ] = Form.useForm();

  const {
    currentOrgReducer: { orgId },
    sessionUsageReducer: sessionUsage,
  } = useSelector((state) => state);

  const queryClient = useQueryClient();
  const currentSubscriptionKey = React.useMemo( () => `currentSubscription${orgId}`, [orgId] );
  const currentSubscription = queryClient.getQueryData(currentSubscriptionKey);
  const currentMonth = currentSubscription?.currentMonth;
  const subscriptionIsCancelled = currentSubscription?.subscription?.status === 'Canceled'

  const mobileValueRef = React.useRef();
  const webValueRef = React.useRef();

  const { totalSessionCount, totalWebSessionCount } = currentMonth || {};
  const showMobileUsage = !!totalSessionCount && !subscriptionIsCancelled
  const showWebUsage = !!totalWebSessionCount && !subscriptionIsCancelled

  useEffect(() => {
    if ( orgId ) {
      dispatch(getSessionUsage(orgId));
      dispatch(getWebSessionUsage(orgId));
    }
  }, [orgId, dispatch]);

  useEffect(() => {
    if ( !mobileValueRef.current?.length ) {
      const mobileInitialValue = sessionUsage?.sessionUsageNotificationPercentage instanceof Array ? sessionUsage?.sessionUsageNotificationPercentage : [];
      mobileValueRef.current = mobileInitialValue;
      formMobile.setFieldsValue( { sessionUsageNotificationPercentage: mobileInitialValue } )
    }
      
    if ( !webValueRef.current?.length ) {
      const webInitialValue = sessionUsage?.webSessionUsageNotificationPercentage instanceof Array ? sessionUsage?.webSessionUsageNotificationPercentage : [];
      webValueRef.current = webInitialValue;
      formWeb.setFieldsValue( { webSessionUsageNotificationPercentage: webInitialValue } )
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ sessionUsage ] )

  const checkDuplicateValue = (arrayValue) =>
    arrayValue.length === new Set(arrayValue).size;

  const handleValidationOnAdd = ( add, isWeb ) => {
    const form = isWeb ? formWeb : formMobile
    form.validateFields().then((values) => {
      if (values) {
        add();
      }
    });
  };

  const handeSessionUsageUpdate = async (data) =>
    dispatch(updateSessionUsage(orgId, data));

  const handeWebSessionUsageUpdate = async (data) =>
    dispatch(updateWebSessionUsage(orgId, data));
  
  const onFinish = async (values, isWeb) => {
    const percentages = isWeb ? values.webSessionUsageNotificationPercentage : values.sessionUsageNotificationPercentage || [];
    
    if (!checkDuplicateValue(percentages) ) {
      message.error('Please enter unique values.');
      return;
    }

    if ( isWeb ) {
      setWebLoading( true )
      await handeWebSessionUsageUpdate( { webSessionUsageNotificationPercentage: values.webSessionUsageNotificationPercentage } )
        .then( ( res ) => {
          let responseMessage
          if ( res?.success ) {
            const responseValPresent = !!res?.data?.webSessionUsageNotificationPercentage?.length
            responseMessage = res?.data?.message
            
            setShowWebSaveButton( false )
            responseValPresent
              ? message.success( responseMessage )
              : message.success(
                  'The percentage at which the email notification is sent for session usage is removed'
                );
          }
        } )
        .finally( () => {
          setWebLoading( false )
          webValueRef.current = values.webSessionUsageNotificationPercentage
        } )
    } else {
      setMobileLoading( true )
      await handeSessionUsageUpdate( { sessionUsageNotificationPercentage: values.sessionUsageNotificationPercentage } )
        .then( ( res ) => {
          let responseMessage
          if ( res?.success ) {
            const responseValPresent = !!res?.data?.sessionUsageNotificationPercentage?.length
            responseMessage = res?.data?.message
            
            setShowMobileSaveButton( false )
            responseValPresent
              ? message.success( responseMessage )
              : message.success(
                  'The percentage at which the email notification is sent for session usage is removed'
                );
          }
        } )
        .finally( () => {
          setMobileLoading( false )
          mobileValueRef.current = values.sessionUsageNotificationPercentage
        } )
    }
  };

  const handleOnValuesChange = React.useCallback( ( val ) => {
    if ( val ) {
      const sessionUsageNotificationPercentage = val?.sessionUsageNotificationPercentage
      const webSessionUsageNotificationPercentage = val?.webSessionUsageNotificationPercentage

      if ( sessionUsageNotificationPercentage ) {
        if ( JSON.stringify( sessionUsageNotificationPercentage ) !== JSON.stringify( mobileValueRef.current ) ) {
          setShowMobileSaveButton( true )
        } else {
          setShowMobileSaveButton( false )
        }
      }
  
      if ( webSessionUsageNotificationPercentage ) {
        if ( JSON.stringify( webSessionUsageNotificationPercentage ) !== JSON.stringify( webValueRef.current ) ) {
          setShowWebSaveButton( true )
        } else {
          setShowWebSaveButton( false )
        }
      }
    }
  }, [])

  if ( !showMobileUsage && !showWebUsage ) {
    return null;
  }

  return (
    <SessionUsageCard>
      <div className="session-usages-card-head">
        <h3>Session usage alert</h3>
        <p>Get notified when the session usage reaches a threshold</p>
      </div>
      <div className="session-usages-card-body">
        { showMobileUsage && (
          <div className="session-usages-card-element">
            <div className="session-usage-label">
              Mobile session usage threshold (%)
            </div>
            <Form
              onFinish={ ( values ) => onFinish( values, false ) }
              form={ formMobile }
              className="session-usages-card-new"
              colon={false}
              onValuesChange={ handleOnValuesChange } 
            >
              <Form.List name="sessionUsageNotificationPercentage">
                {  (fields, { add, remove }, { errors } ) => (
                  <>
                    {fields.map((field) => (
                      <FormItem key={field.name}>
                        <FormItem
                          {...field}
                          validateTrigger={['onChange', 'onBlur']}
                          rules={validateRule}
                        >
                          <Input
                            suffix="%"
                            maxLength={10}
                            onKeyPress={(event) => {
                              if (!/[0-9]/.test(event.key)) {
                                event.preventDefault();
                              }
                            }}
                            placeholder="Enter percentage"
                          />
                        </FormItem>
                        <Button
                          className="dynamic-delete-button"
                          icon={<DeleteOutlined />}
                          onClick={() => {
                            remove(field.name);
                          }}
                        />
                      </FormItem>
                    ))}
                    {fields.length <= 4 ? (
                      <FormItem>
                        <Button
                          onClick={() => handleValidationOnAdd( add ) }
                          className="btn-add"
                          icon={<PlusOutlined />}
                        >
                          Add threshold
                        </Button>
                      </FormItem>
                    ) : null}
                    <Form.ErrorList errors={errors} />
                  </>
                )}
              </Form.List>
              { showMobileSaveButton && (
                <Button
                  size="small"
                  loading={ mobileLoading }
                  type="primary"
                  htmlType="submit"
                >
                  Save
                </Button>
              ) }
            </Form>
          </div>
        ) }
        { showWebUsage && (
          <div className="session-usages-card-element">
            <div className="session-usage-label">
              Web session usage threshold (%)
            </div>
            <Form
              onFinish={ ( values ) => onFinish( values, true ) }
              form={formWeb}
              className="session-usages-card-new"
              colon={false}
              onValuesChange={ handleOnValuesChange } 
            >
              <Form.List name="webSessionUsageNotificationPercentage" className="loool">
                {(fields, { add, remove }, { errors }) => (
                  <>
                    {fields.map((field) => (
                      <FormItem key={field.name} className='web-usage-threshold'>
                        <FormItem
                          {...field}
                          validateTrigger={['onChange', 'onBlur']}
                          rules={validateRule}
                          >
                          <Input
                            suffix="%"
                            maxLength={10}
                            onKeyPress={(event) => {
                              if (!/[0-9]/.test(event.key)) {
                                event.preventDefault();
                              }
                            }}
                            placeholder="Enter percentage"
                          />
                        </FormItem>
                        <Button
                          className="dynamic-delete-button"
                          icon={<DeleteOutlined />}
                          onClick={() => {
                            remove(field.name);
                          }}
                        />
                      </FormItem>
                    ))}
                    {fields.length <= 4 ? (
                      <FormItem>
                        <Button
                          onClick={() => handleValidationOnAdd( add, true  )}
                          className="btn-add"
                          icon={<PlusOutlined />}
                        >
                          Add threshold
                        </Button>
                      </FormItem>
                    ) : null}
                    <Form.ErrorList errors={errors} />
                  </>
                )}
                
              </Form.List>
              { showWebSaveButton && (
                <Button
                  size="small"
                  loading={ webLoading }
                  type="primary"
                  htmlType="submit"
                  className="save-btn"
                >
                  Save
                </Button>
              ) }
            </Form>
          </div>
        ) }
      </div>
    </SessionUsageCard>
  );
};

export default SessionUsageAlert;
