import React, { useMemo, memo } from 'react';
import { DownOutlined } from '@ant-design/icons';
import { Dropdown, Menu, Space } from 'antd';
import styled from 'styled-components';

import TextTruncated from 'components/common/TextTruncated';
import { useFetchAllAppListById } from '../../useSettingPage';

const MenuItem = Menu.Item;

const MenuWrap = styled(Menu)`
  max-height: 280px;
  overflow-y: auto;
  scrollbar-width: thin;
  .ant-dropdown-menu-item:hover,
  .ant-dropdown-menu-submenu-title:hover {
    background-color: transparent;
  }
`;

const StyledDropDown = styled(Dropdown)`
  .ant-dropdown-menu {
    border-radius: 10px;
  }
`;

const DropdownTitleWrap = styled.div`
  color: #5d97ff;
  font-size: 12px;
  cursor: pointer;
`;

const DropdownItemWrap = styled.div`
  display: flex;
  cursor: default;
  justify-content: space-between;
`;

const DropdownItem = styled.div`
  width: 200px;
  font-size: 12px;
  color: #161e35;
  padding: 8px;
`;

const DropDownItemInner = styled(DropdownItem)`
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: nowrap;

`;

const DropdownItemLevel = styled(DropdownItem)`
  width: 142px;
  height: 36px;
  border-radius: 30px;
  background: #f5f5f5;
  margin-left: 5px;
  text-align: center;
`;

const TeamAppList = ({ apps, orgId }) => {
  const menu = (
    <MenuWrap>
      {apps &&
        apps.map((appItem) => (
          <MenuItem key={appItem.id}>
            <DropdownItemWrap>
              <DropDownItemInner>
                <TextTruncated value={appItem?.name}/></DropDownItemInner>
              <DropdownItemLevel>{appItem?.roleText}</DropdownItemLevel>
            </DropdownItemWrap>
          </MenuItem>
        ))}
    </MenuWrap>
  );

  const { data: appList } = useFetchAllAppListById(orgId);

  const totalAppList = useMemo(() => appList?.length, [appList]);
  const assignAppList = useMemo(() => apps?.length, [apps]);

  return (
    <StyledDropDown overlay={menu} trigger='click'>
      <DropdownTitleWrap>
        {`${totalAppList !== assignAppList ? `${assignAppList}` : 'All'} app${
          assignAppList > 1 || assignAppList === totalAppList ? 's' : ''
        }`}
        <DownOutlined />
      </DropdownTitleWrap>
    </StyledDropDown>
  );
};

export default memo(TeamAppList);
