const ButtonsWrapper = styled.div`
  width: 100%;
  display: flex;
  justify-content: flex-end;
  margin-top: 32px;
  gap: 16px;
`

const BillingInformationModal = ( { 
  form, popupOpen, setPopupOpen, setBillingAddress, billingAddressIsLoading, billingInfo, setFormDefaultValues,
} ) => {
  const [ countrySearchVal, setCountrySearchVal ] = React.useState( '' )
  const [ stateSearchVal, setStateSearchVal ] = React.useState( '' )
  
  const selectedCountry = Form.useWatch( 'country', form )
  const containerRef = React.useRef()
  const {
    currentOrgReducer: { organizationName },
    profileReducer: { email }
  } = useSelector( ( state ) => state )

  const countryOptions = React.useMemo( () => {
    return Country.getAllCountries()
      .filter( ( { name } ) => name.toLowerCase().includes( countrySearchVal.toLowerCase() ) )
      .map( ( { name, isoCode } ) => ( {
        label: name,
        value: isoCode
    } ) )
  }, [ countrySearchVal ] )

  const stateOptions = React.useMemo( () => {
    if ( !selectedCountry ) {
      return []
    }
    
    return State.getStatesOfCountry( selectedCountry )
      .filter( ( { name } ) => name.toLowerCase().includes( stateSearchVal.toLowerCase() ) )
      .map( ( { name } ) => ( {
        label: name,
        value: name
    } ) )
  }, [ selectedCountry, stateSearchVal ] )

  const handleCountryChange = () => {
    const setFieldsValue = form?.setFieldsValue
    if ( setFieldsValue ) {
      setFieldsValue( { state: undefined } )
    }
  }
  
  const handleSubmit = React.useCallback( ( values ) => {
    if ( values.address === billingInfo?.address?.address &&
      values.city === billingInfo?.address?.city &&
      values.country === billingInfo?.address?.country &&
      values.firstName === billingInfo?.address?.first_name &&
      values.lastName === billingInfo?.address?.last_name &&
      values.state === billingInfo?.address?.state &&
      values.vatNumber === ( billingInfo?.vat_number || '' ) &&
      values.zip === billingInfo?.address?.zip ) {
      setPopupOpen( false )
      return
    }

    const {
      firstName,
      lastName,
      country,
      state,
      zip,
      city,
      address,
      vatNumber: vatNumberRaw
    } = values

    const vatNumber = vatNumberRaw?.length ? vatNumberRaw : null

    setBillingAddress( {
      "address": {
          "company": organizationName,
          "email": email,
          "first_name": firstName,
          "last_name": lastName,
          "address": address,
          "city": city,
          "state": state,
          "zip": zip,
          "country": country
      },
      "vat_number": vatNumber
    } )
  }, [ organizationName, email, setPopupOpen, setBillingAddress, billingInfo ] )

  const handleCancel = React.useCallback( () => {
    setPopupOpen( false )
    setTimeout( () => {
      setCountrySearchVal( '' )
      setStateSearchVal( '' )
      setFormDefaultValues()
    }, 100 )
  }, [ setPopupOpen, setFormDefaultValues ] )

	return (
		<Modal
      visible={ popupOpen }
      footer={ null }
      onCancel={ handleCancel }
      closable={ false }
      className="ant-modal-delete-nocode-event"
      wrapClassName="ant-modal-delete-nocode-event-wrapper"
      width={ 570 }
    >
      <StylesProvider>
        <Form 
          form={ form }
          onFinish={ handleSubmit }
          disabled={ billingAddressIsLoading }
          onValuesChange={ ( changedValues ) => {
            const fieldName = Object.keys( changedValues )[ 0 ]
            form.setFields( [ { name: fieldName, errors: [] } ] )
          } }
        >
          <BillingInformationModalContainer
            ref={ containerRef }
          >
              <Title>
                Update billing information
              </Title>
              <SubTitle>
                This information will appear on all your receipts. For your security, do not include any confidential or financial information.
              </SubTitle>
              <Row>
                <Form.Item
                  label="First name"
                  name="firstName"
                  rules={ [ { required: true, message: 'Please input your first name' } ] }
                >
                  <Input aria-label="First name" placeholder="Enter first name" />
                </Form.Item>
                <Form.Item
                  label="Last name"
                  name="lastName"
                  rules={ [ { required: true, message: 'Please input your last name' } ] }
                >
                  <Input aria-label="Last name" placeholder="Enter last name" />
                </Form.Item>
              </Row>
              <Row>
                <Form.Item
                  label="Country"
                  name="country"
                  rules={ [ { required: true, message: 'Please input your country' } ] }
                >
                  <UFCSelect
                    getPopupContainer={ () => containerRef?.current }
                    renderOptions={ countryOptions }
                    onChange={ handleCountryChange }
                    value={ selectedCountry }
                    placeholder="Select country"
                    searchProps={ { onChange: ( { target } ) => setCountrySearchVal( target.value ) } }
                    disabled={ billingAddressIsLoading }
                  />
                </Form.Item>
              </Row>
              <Row>
              <Form.Item
                  label="State"
                  name="state"
                  rules={ [ { 
                    required: !!stateOptions?.length, 
                    message: 'Please input your state' 
                  } ] }
                >
                  <UFCSelect 
                    getPopupContainer={ () => containerRef?.current }
                    renderOptions={ stateOptions }
                    disabled={ !stateOptions?.length || billingAddressIsLoading }
                    placeholder="Select state"
                    searchProps={ { onChange: ( { target } ) => setStateSearchVal( target.value ) } }
                  />
                </Form.Item>
                <Form.Item
                  label="Postal code"
                  name="zip"
                  rules={ [ { required: true, message: 'Please input your postal code' } ] }
                >
                  <Input aria-label="Postal code" placeholder="Enter postal code" />
                </Form.Item>
              </Row>
              <Row>
                <Form.Item
                  label="City"
                  name="city"
                  rules={ [ { required: true, message: 'Please input city' } ] }
                >
                  <Input aria-label="City" placeholder="Enter city" />
                </Form.Item>
              </Row>
              <Row>
                <Form.Item
                  label="Address line 1"
                  name="address"
                  rules={ [ { required: true, message: 'Please input address' } ] }
                >
                  <Input aria-label="Address" placeholder="Enter address" />
                </Form.Item>
              </Row>
              <Row>
                <Form.Item
                  label="VAT number (optional)"
                  name="vatNumber"
                >
                  <Input aria-label="VAT number" placeholder="Enter VAT" />
                </Form.Item>
              </Row>
              <ButtonsWrapper>
                <ButtonNew
                  width="medium"
                  variant="ghost"
                  onClick={ handleCancel }
                  disabled={ !!billingAddressIsLoading }
                  type="button"
                >
                  Cancel
                </ButtonNew>
                <ButtonNew
                  width="medium"
                  type="submit"
                  disabled={ !!billingAddressIsLoading }
                >
                  Submit
                </ButtonNew>
              </ButtonsWrapper>
          </BillingInformationModalContainer>
        </Form>
      </StylesProvider>
    </Modal>
	)
}

export default BillingInformationModal