const IssueConfiguration: React.FC<TIssueConfig> = (props) => {
  const [form] = Form.useForm();
  const teamsFormContainerRef = useRef<HTMLDivElement>(null);
  const slackFormContainerRef = useRef<HTMLDivElement>(null);
  const oldTeamURLPattern = /^https:\/\/[A-Za-z0-9-]+\.webhook\.office\.com\/.*$/;

  const { appId } = props;
  const { saveIssueConfig, testNotification, issueConfig } =
    useIssueNotification();
  const {
    checkOptions: checkboxOptions,
    slack,
    microsoft,
    enabledIssueType,
  } = issueConfig;
  const { webhookUrl: slackWebhookUrl, channelName, isEnabled: isSlackChecked } = slack;
  const { webhookUrl: teamsWebhookUrl, isEnabled: isTeamsChecked } = microsoft;

  const { currentOrgReducer } = useSelector((state: RootStateOrAny) => state);
  const [, forceUpdate] = useState({});
  const planFeature = currentOrgReducer?.planFeature;
  const disableSaveButton =
    checkboxOptions instanceof Array && checkboxOptions.length < 1;
  const issueAnalytics = planFeature?.issueAnalytics;
  const [notificationNotAvailable, setNotificationNotAvailable] =
    useState(false);
  // const [notificationTypeNotAvailable, setNotificationTypeNotAvailable] = useState(false);
  const issueType = Form.useWatch('issueNotificationType', form) as string[];
  const notification = Form.useWatch('notification', form) as string[];
  const teamsWebhookUrlValue = Form.useWatch('teamsWebhookUrl', form) as string;
  const slackWebhookUrlValue = Form.useWatch('slackWebhookUrl', form) as string;
  const channelNameValue = Form.useWatch('channelname', form) as string;

  const isFieldInvalid = (fieldName: string) => form.getFieldError(fieldName).length > 0;

  const checkFormDataChange = useCallback(() => {
    const values = form.getFieldsValue();
    if (isFieldInvalid('channelname')) return true;
    const formData = {
      notification: values.notification?.sort(),
      slack: {
        webhookUrl: values.slackWebhookUrl,
        channelName: values.channelname,
        isEnabled: values.issueNotificationType?.includes('slack') || false,
      },
      microsoft: {
        webhookUrl: values.teamsWebhookUrl,
        isEnabled: values.issueNotificationType?.includes('microsoft') || false,
      },
    };
    const currentData = {
      notification: checkboxOptions?.sort(),
      slack: {
        webhookUrl: slackWebhookUrl,
        channelName,
        isEnabled: isSlackChecked,
      },
      microsoft: {
        webhookUrl: teamsWebhookUrl,
        isEnabled: isTeamsChecked,
      },
    };
    return isEqual(formData, currentData);
  }, [
    form,
    checkboxOptions,
    slackWebhookUrl,
    channelName,
    isSlackChecked,
    teamsWebhookUrl,
    isTeamsChecked,
    notification
  ]);

  useEffect(() => {
    form.setFieldsValue({
      notification: checkboxOptions,
      slackWebhookUrl,
      teamsWebhookUrl,
      channelname: channelName,
      issueNotificationType: !issueAnalytics ? [] : enabledIssueType || [],
    });
    checkFormDataChange();
  }, [issueConfig]);

  useEffect(() => {
    setNotificationNotAvailable(disableSaveButton);
  }, [disableSaveButton]);

  useEffect(() => {
    forceUpdate({});
  }, []);

  const onFinish = () => {
    form.validateFields().then((values) => {
      const channel = values.channelname;
      const slkWebhookUrl = values.slackWebhookUrl || '';
      const tmsWebhookUrl = values.teamsWebhookUrl || '';
      const payload = {
        appid: appId,
        notificationType: issueType,
        slack: {
          webhookUrl: slkWebhookUrl,
          channelName: channel,
          isEnabled: issueType.includes('slack'),
        },
        microsoft: {
          webhookUrl: tmsWebhookUrl,
          isEnabled: issueType.includes('microsoft'),
        },
        notification: values.notification,
      }
      saveIssueConfig.mutate(payload);
    });
  };

  const onTestNotificationClick = (type: 'slack' | 'microsoft') => {
    const values = form.getFieldsValue();
    const channel = values.channelname;
    const payload = {
      appid: appId,
      notificationType: type,
      ...(type === 'slack' && {
        slack: {
          webhookUrl: values.slackWebhookUrl,
          channelName: channel,
          isEnabled: issueType.includes('slack'),
        },
      }),
      ...(type === 'microsoft' && {
        microsoft: {
          webhookUrl: values.teamsWebhookUrl,
          isEnabled: issueType.includes('microsoft'),
        },
      }),
      notification: values.notification,
    };
    testNotification.mutate(payload);
  };

  const onIssueCheckboxChange = (checkedValues: CheckboxValueType[]) => {
    if (checkedValues.length < 1) {
      setNotificationNotAvailable(true);
    } else {
      setNotificationNotAvailable(false);
    }
  };

  // const onNotificationTypeCheckboxChange = (checkedValues: CheckboxValueType[]) => {
  //   if (checkedValues.length < 1) {
  //     setNotificationTypeNotAvailable(true);
  //   } else {
  //     setNotificationTypeNotAvailable(false);
  //   }
  // };

  const slackChannelNameValidator = (value: string, callback: any) => {
    // Replace spaces with dashes
    const transformedValue = value.replace(/\s+/g, '-');

    // Check for special characters (except underscore and dash)
    if (/[^a-zA-Z0-9_-]/.test(transformedValue)) {
      callback('Channel names can’t contain spaces or punctuation. Use dashes to separate words.');
      return;
    }

    // Update the form field value and clear any previous errors
    form.setFieldsValue({
      channelname: transformedValue,
    });

    // Call the callback without arguments to indicate successful validation
    callback();
  };

  function validateAndTransform(input: string) {
    // Replace spaces with dashes
    const transformedValue = input.replace(/\s+/g, '-');

    // Check for special characters (except underscore and dash)
    if (/[^a-zA-Z0-9_-]/.test(transformedValue)) {
      form.setFields([
        {
          name: 'channelname',
          value: transformedValue,
          errors: ['Channel names can’t contain spaces or punctuation. Use dashes to separate words.'],
          touched: true,
        },
      ]);
      return;
    }

    form.setFieldsValue({
      channelname: transformedValue,
    });
  }

  const issueDocumentTextFeatureFlag = (
      <span>
        Get notified on tech issues of your apps. Learn more on the issue
        notifications{' '}
        <a
          href={SlackUrls.KNOWLEDGEBASEURL}
          target="_blank"
          rel="noopener noreferrer"
        >
          here
        </a>
      </span>
    )
  const extraInfo = useCallback(
    (type: string) => (
        <HelpLink
          href={
            type === 'slack'
              ? SlackUrls.SLACKWEBHOOKURL
              : TeamsUrls.TEAMSWEBHOOKURL
          }
          target="_blank"
          rel="noopener noreferrer"
        >
          <InfoHelpIcon />
        </HelpLink>
    ),
    []
  );
  return (
    <ConfigWrapper>
      <div className="config-form-wrapper">
        {!issueAnalytics && (
          <div className="mb-10">
            <Alert message={apiPlanError} type="error" showIcon />
          </div>
        )}

        <InfoBox
          type="info"
          marginBottom={ 18 }
          content={issueDocumentTextFeatureFlag}
        />
        <div className={cs({ 'disabled-overlay': !issueAnalytics })}>
          <Row>
            <div className="main-form-container">
              <Form
                form={form}
                initialValues={{
                  issueNotificationType: issueType,
                  notification: checkboxOptions,
                  slackWebhookUrl: slackWebhookUrl || '',
                  teamsWebhookUrl: teamsWebhookUrl || '',
                  channelname: channelName?.split('#')[1] || '',
                }}
                onFinish={onFinish}
              >
                {/* Select issue type start */}
                <div className="issue-notification-title">
                  <strong>Select an issue type</strong>
                </div>
                <Form.Item
                  name="notification"
                  className="main-checkbox-label"
                  rules={[{ required: false }]}
                >
                  <Checkbox.Group
                    className="checkbox-label"
                    style={{ width: '100%' }}
                    onChange={onIssueCheckboxChange}
                  >
                    <Checkbox disabled={!issueAnalytics} value="Crash">
                      Crash
                    </Checkbox>
                    <Checkbox disabled={!issueAnalytics} value="UI Freeze">
                      UI freeze
                    </Checkbox>
                    <Checkbox
                      disabled={!issueAnalytics}
                      value="Handled Exception"
                    >
                      Exception
                    </Checkbox>
                  </Checkbox.Group>
                </Form.Item>
                {/* Select issue type end */}

                {/* slack/microsoft teams radio select */}
                <div className="issue-notification-title">
                  <strong>Configure the platform for issue notification</strong>
                </div>

                <ConfigurationContainer>
                  <div className="issue-checkbox-group-container">
                    <Form.Item
                      name="issueNotificationType"
                      className="radio-label"
                      rules={[
                        {
                          required: false,
                          message: 'Please select a notification platform',
                        },
                      ]}
                    >
                      <Checkbox.Group
                        disabled={!issueAnalytics}
                        // onChange={onNotificationTypeCheckboxChange}
                      >
                        <span className="checkbox-container" style={{height: slackFormContainerRef.current?.offsetHeight}}>
                          <Checkbox value="slack">Slack</Checkbox>
                        </span>
                        <span className="checkbox-container" style={{height: teamsFormContainerRef.current?.offsetHeight}}>
                          <Checkbox value="microsoft">Microsoft Teams</Checkbox>
                        </span>
                      </Checkbox.Group>
                    </Form.Item>
                  </div>

                  <div className="issue-form-container">
                    {/* Slack form inputs start */}
                    <div ref={slackFormContainerRef} className="form-container">
                      <Form.Item
                        label={
                          <div className="label-container">
                            <span>Slack webhook URL</span>
                            {extraInfo('slack')}
                          </div>
                        }
                        name="slackWebhookUrl"
                        className="main-checkbox-label"
                        rules={[
                          {
                            required: issueType?.includes('slack') || false,
                            message: 'Please enter webhook URL!',
                          },
                        ]}
                      >
                        <Input disabled={!issueAnalytics} />
                      </Form.Item>
                      <Form.Item
                        label={
                          <div className="label-container">
                            <span>Slack channel name</span>
                          </div>
                        }
                        name="channelname"
                        className="main-checkbox-label mt-16"
                        rules={[
                          {
                            required: issueType?.includes('slack') || false,
                            message: 'Please enter channel name!',
                          },
                          {
                            validator: (_, value, callback) => {
                              slackChannelNameValidator(value, callback);
                            }
                          }
                        ]}
                      >
                        <Input
                          onChange={(e) => {
                            const { value } = e.target;
                            validateAndTransform(value)
                          }}
                          disabled={!issueAnalytics} />
                      </Form.Item>

                      <SendNotificationButton
                        disabled={
                          !issueAnalytics ||
                          !channelNameValue ||
                          !slackWebhookUrlValue ||
                          testNotification.isLoading ||
                          isFieldInvalid('channelname')
                        }
                        onClick={(e) => {
                          e.preventDefault();
                          onTestNotificationClick('slack');
                        }}
                      >
                        <SendIcon /> Send test notification
                      </SendNotificationButton>
                    </div>
                    {/* Slack form inputs end */}

                    {/* Microsoft teams form inputs start */}
                    <div ref={teamsFormContainerRef} className="form-container">
                      <Form.Item
                        label={
                          <div className="label-container">
                            <span>Teams webhook URL</span>
                            {extraInfo('teams')}
                          </div>
                        }
                        name="teamsWebhookUrl"
                        className="main-checkbox-label"
                        rules={[
                          {
                            required: issueType?.includes('microsoft') || false,
                            message: 'Please enter webhook URL!',
                          },
                        ]}
                      >
                        <Input disabled={!issueAnalytics} />
                      </Form.Item>

                      <SendNotificationButton
                        disabled={
                          !issueAnalytics ||
                          !teamsWebhookUrlValue ||
                          testNotification.isLoading
                        }
                        onClick={(e) => {
                          e.preventDefault();
                          onTestNotificationClick('microsoft');
                        }}
                      >
                        <SendIcon /> Send test notification
                      </SendNotificationButton>
                      {teamsWebhookUrl && oldTeamURLPattern.test(teamsWebhookUrl) && (
                       <TeamsDepreciationAlert/>
                    )}
                    </div>
                    {/* Microsoft teams form inputs end */}
                  </div>
                </ConfigurationContainer>

                <div className="btn-wrapper">
                  <Button
                    disabled={
                      !issueAnalytics ||
                      notificationNotAvailable ||
                      checkFormDataChange() ||
                      saveIssueConfig.isLoading
                    }
                    type="primary"
                    htmlType="submit"
                    loading={saveIssueConfig.isLoading}
                  >
                    Save
                  </Button>
                </div>
              </Form>
            </div>
          </Row>
        </div>
      </div>
    </ConfigWrapper>
  );
};

export default IssueConfiguration;
