import React, { useMemo, useState, useCallback } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import styled from 'styled-components';
import { Switch, Tooltip, message } from 'antd';
import { QuestionCircleOutlined } from '@ant-design/icons';
import { DashboardTable, StylesProvider } from 'uxcam-frontend-components';
import { useMutation, useQueryClient } from 'react-query';
import { theme } from 'theme';
import { getAppDropdown, getCurrentApp } from 'redux/actions/appdropdown';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { trackToggleTara } from 'components/features/aiSessions/components/utils';
import { useFetchAIOverview, toggleAIForApp, useFetchAIUsageOverview } from '../../useSettingPage';
import ProfileImageOrText from '../../ProfileImageOrText';

interface AppUsageSectionProps {
  $isLoaded: boolean;
}

const AppUsageSection = styled.div<AppUsageSectionProps>`
  padding: 20px;
  border: 1px solid #E8E8EB;
  border-radius: 8px;

  ${({ $isLoaded }) => $isLoaded && `
    > div:last-of-type > div {
      min-height: initial;
    }
  `}
`;

const AppUsageHeader = styled.div`
  margin-bottom: 16px;
`;

const AppUsageTitle = styled.h4`
  font-size: ${theme.fontSize(1.6)};
  font-weight: 500;
  color: ${theme.colors.primaryMidnight.toString()};
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 4px;
`;

const AppUsageDescription = styled.p`
  font-size: ${theme.fontSize(1.3)};
  color: ${ theme.colors.surface300.toString() };
  margin: 0;
  line-height: 1.5;
`;

const AppNameCell = styled.div`
  display: flex;
  align-items: center;
  gap: 12px;
`;

const AppName = styled.span`
  font-size: ${theme.fontSize(1.4)};
  color: ${theme.colors.primaryMidnight.toString()};
`;

interface App {
  _id: string; // eslint-disable-line no-underscore-dangle
  name: string;
  dailyLimit: number;
  isAIEnabled: boolean;
}

interface AppTableRow {
  key: string;
  appId: string;
  app: string;
  appName: string;
  appPicture: string;
  autoAnalysis: boolean;
  tooltip: string;
}

interface ToggleMutationVariables {
  orgId: string;
  appId: string;
  isAIEnabled: boolean;
}

interface ToggleMutationResponse {
  message?: string;
}

interface AppNameCellProps {
  row: {
    original: AppTableRow;
  };
}

const AppNameCellComponent: React.FC<AppNameCellProps> = ({ row }) => {
  const record = row.original;
  const [imageError, setImageError] = useState(false);

  // Determine if we should show the picture
  // Only show if appPicture exists and hasn't errored
  const shouldShowPicture = record.appPicture && !imageError;

  return (
    <AppNameCell>
      <ProfileImageOrText
        picture={shouldShowPicture ? record.appPicture : ''}
        nameInfo={record.appName}
        size={32}
        shape="square"
        className=""
      />
      <AppName>{record.appName}</AppName>
      {/* Hidden image to detect load errors */}
      {record.appPicture && !imageError && (
        <img
          src={record.appPicture}
          alt=""
          style={{ display: 'none' }}
          onError={() => setImageError(true)}
        />
      )}
    </AppNameCell>
  );
};

interface AutoAnalysisCellProps {
  getValue: () => boolean;
  row: {
    original: AppTableRow;
  };
  togglingAppId: string | null;
  onToggle: (appId: string, currentValue: boolean) => void;
  isAdmin: boolean;
}

const AutoAnalysisCell: React.FC<AutoAnalysisCellProps> = ({ getValue, row, togglingAppId, onToggle, isAdmin }) => {
  const autoAnalysis = getValue();
  const record = row.original;
  const isToggling = togglingAppId === record.appId;
  const isDisabled = isToggling || !isAdmin;

  const tooltipTitle = !isAdmin
    ? "You don't have permission to change this setting. Ask an organization manager or owner to enable it."
    : record.tooltip;

  return (
    <Tooltip title={tooltipTitle} placement="left">
      <Switch
        checked={autoAnalysis}
        size="small"
        loading={isToggling}
        disabled={isDisabled}
        onChange={() => onToggle(record.appId, autoAnalysis)}
        style={{ backgroundColor: autoAnalysis ? '#5D97FF' : '#d9d9d9' }}
      />
    </Tooltip>
  );
};

const AppUsage: React.FC = () => {
  const {
    currentOrgReducer: { orgId },
    currentAppReducer: { _id: currentAppId },
    applicationReducer,
  } = useSelector((state: any) => state);
  const dispatch = useDispatch();
  const queryClient = useQueryClient();
  const [togglingAppId, setTogglingAppId] = useState<string | null>(null);

  const isAdmin = useMemo(() => applicationReducer?.find((app: any) => app.orgId === orgId)?.roleText === 'Manager' || false, [applicationReducer, orgId])
  const restrictionContext: any = useRestrictionContext();
  const planFeatureAiSessions = !!restrictionContext?.planFeatureAiSessions;

  const { data: aiOverview, isFetching } = useFetchAIOverview(orgId, planFeatureAiSessions);
  const { data: aiUsageData } = useFetchAIUsageOverview(orgId, planFeatureAiSessions);

  const toggleMutation = useMutation<
    ToggleMutationResponse,
    unknown,
    ToggleMutationVariables
  >(toggleAIForApp, {
    onMutate: (variables) => {
      setTogglingAppId(variables.appId);
    },
    onSuccess: async (data) => {
      queryClient.invalidateQueries(`ai_overview_${orgId}`);
      const updatedOrgList = await (dispatch(getAppDropdown()) as any);
      dispatch(getCurrentApp(currentAppId, updatedOrgList));
      message.success(data?.message || 'AI settings updated successfully');
      setTogglingAppId(null);
    },
    onError: () => {
      setTogglingAppId(null);
    },
  });

  const handleToggleAI = useCallback((appId: string, currentValue: boolean): void => {
    dispatch(trackToggleTara({
      taraSetting: !currentValue ? 'on' : 'off',
      isAdmin,
      currentAutoanalysisLimit: aiUsageData?.monthly_auto_analysis_tara_credit || 0,
      currentCreditsLimit: aiUsageData?.monthly_tara_credit || 0,
    }));

    toggleMutation.mutate({
      orgId,
      appId,
      isAIEnabled: !currentValue,
    });
  }, [toggleMutation, orgId, isAdmin, aiUsageData]);

  // Transform API data to table format
  const appData = useMemo(() => {
    if (!aiOverview?.apps) return [];

    return aiOverview.apps.map((app: App): AppTableRow => {
      // Find app picture from applicationReducer
      // eslint-disable-next-line no-underscore-dangle
      const appInfo = applicationReducer?.find((a: any) => a._id === app._id);

      return {
        key: app._id, // eslint-disable-line no-underscore-dangle
        appId: app._id, // eslint-disable-line no-underscore-dangle
        app: app.name,
        appName: app.name,
        appPicture: appInfo?.appImageSrc || '',
        autoAnalysis: app.isAIEnabled,
        tooltip: app.isAIEnabled
          ? 'Disabling Tara for this app will stop automatic session analysis.'
          : 'Enabling Tara for this app will start automatic session analysis.'
      };
    });
  }, [aiOverview, applicationReducer]);

  const renderAppNameCell = useCallback((props: any) => (
    <AppNameCellComponent row={props.row} />
  ), []);

  const renderAutoAnalysisCell = useCallback((props: any) => (
    <AutoAnalysisCell
      getValue={props.getValue}
      row={props.row}
      togglingAppId={togglingAppId}
      onToggle={handleToggleAI}
      isAdmin={isAdmin}
    />
  ), [togglingAppId, handleToggleAI, isAdmin]);

  const columns = useMemo(() => [
    {
      accessorKey: 'app',
      header: 'Apps',
      size: 400,
      cell: renderAppNameCell,
    },
    {
      accessorKey: 'autoAnalysis',
      header: 'Tara AI',
      size: 200,
      cell: renderAutoAnalysisCell,
    },
  ], [renderAppNameCell, renderAutoAnalysisCell]);

  return (
    <AppUsageSection $isLoaded={!isFetching}>
      <AppUsageHeader>
        <AppUsageTitle>
          Apps using Tara
        </AppUsageTitle>
        <AppUsageDescription>
          When enabled, Tara automatically watches a sample of random sessions daily (at no credit cost) to ensure unbiased insights are ready when you ask questions.
        </AppUsageDescription>
      </AppUsageHeader>

      <StylesProvider>
        <DashboardTable
          columns={columns}
          data={appData}
          resizeMode="onChange"
          isLoading={isFetching}
        />
      </StylesProvider>
    </AppUsageSection>
  );
};

export default AppUsage;
