const mapAppType = (type) => {
  if (type === 'web') {
    return 'Web App';
  }
  return 'Mobile App';
}

const UserColumn = ({ record, validatePermissionOnSingleApp }) => {
  const [nameValue, setNameValue] = useState();
  const [isEdit, setIsEdit] = useState(false);
  const [isError, setIsError] = useState(false);
  const [nameError, setNameError] = useState('');
  const queryClient = useQueryClient();

  const dispatch = useDispatch();

  const { name, _id: appID, orgId } = record;

  const queryKey = `appList_${orgId}`;

  const { refetch: updateApp, isLoading } = useUpdateApp(nameValue, appID);
  const handleUpdateApp = () => {
    updateApp().then((response) => {
      if (!response?.data?.error) {
        message.success(response?.data?.message);
        queryClient.setQueryData(queryKey, (oldData) => {
          const newData = [...oldData];
          const indexValue =
            oldData?.length && oldData.findIndex((app) => app?._id === appID);
          newData[indexValue] = response?.data?.app;
          return newData;
        });
        queryClient.invalidateQueries(`total_apps_${orgId}`);
        dispatch(getAppDropdown());

        setIsEdit(false);
        setNameValue();
      }
      if (response?.data?.error) {
        const error = response?.data?.error;
        if (!error) {
            message.error("Something went wrong while creating app.")
            return;
        }
        message.error(
              // adding error.name to catch app name related errors
            error.message || error.detail || error.name
        );
      }
    });
  };
  const AddonEdit = (
    <ButtonDiv>
      <Button
        type="primary"
        size="small"
        onClick={handleUpdateApp}
        disabled={nameError}
        loading={isLoading}
      >
        Save
      </Button>
      <Button
        size="small"
        onClick={() => {
          setIsEdit(false);
          setIsError(false);
          setNameError('');
        }}
      >
        Cancel
      </Button>
    </ButtonDiv>
  );

  const handeOnChange = (e) => {
    const inputValue = e.target.value;
    setNameError(validateInputName(inputValue));
    setNameValue(inputValue);
  };

  return (
    <UserColumnOuter>
      <ChangeIcon
        user={record}
        permission={validatePermissionOnSingleApp(AppCreateUpdate, appID)}
      />

      <UserColumnInner>
          {isEdit ? (
            <Individual>
              <Input
                className={`${nameError ? 'ant-input-status-error' : ''}`}
                placeholder="Enter app name"
                onChange={handeOnChange}
                value={nameValue}
                addonAfter={AddonEdit}
              />
              {nameError && (
                <StyledError>
                  {nameError}
                </StyledError>
              )}
            </Individual>
          ) : (
            <NameWrap>
                <TextTruncated value={name} />
                {validatePermissionOnSingleApp(AppCreateUpdate, appID) && (
                  <CircleButton
                    hasedit
                    shape="circle"
                    onClick={() => {
                      setNameValue(record?.name);
                      setIsEdit(true);
                    }}
                    className="hover-button"
                  >
                    <EditIconSvg />
                  </CircleButton>
                )}
              </NameWrap>
          )}
      </UserColumnInner>
    </UserColumnOuter>
  );
};
