const AppSection = () => {
  const queryClient = useQueryClient();
  const [appLists, setAppLists] = useState([]);
  const [userRoleOnOrg, setUserRoleOnOrg] = useState();
  const [userRoleOnApps, setUserRoleOnApps] = useState(false);

  const {
    currentOrgReducer: { orgId, planFeature },
  } = useSelector((state) => state);

  const isMriFeatureEnabled = useMemo(() => planFeature?.mriFeature, [planFeature?.mriFeature])

  const { searchAppName } = useSettingPage();

  const { isLoading, data: appList } = useFetchAppListById(orgId);
  const debouncedSearchValue = useDebounce(searchAppName, 500);

  const newProfile = queryClient.getQueryData('profileInfo');
  const definedRoles = queryClient.getQueryData('roles_permission');

  const validatePermissionOnSingleApp = useCallback(
    (permissionCode, id) =>
      newProfile &&
      authorizeSpecificAppManagerPermission(
        permissionCode,
        definedRoles,
        newProfile?.organization,
        orgId,
        id
      ),
    [newProfile, definedRoles, orgId]
  );

  const validateAppLevelPermission = useCallback(
    (permissionCode) =>
      newProfile &&
      authorizeAppManagerPermission(
        permissionCode,
        definedRoles,
        newProfile?.organization,
        orgId
      ),
    [newProfile, definedRoles, orgId]
  );

  const isWebOrg = useFeatureFlag( 'app-settings-domains' );

  const columns = [
    {
      title: ({ sortColumns }) => (
        <TableSortColumn
          title="App"
          sortColumns={sortColumns}
          dataIndex="name"
        />
      ),
      dataIndex: 'name',
      width: 250,
      defaultSortOrder: 'ascend',
      sorter: (a, b) => a?.name?.localeCompare(b?.name),
      sortDirections: ['ascend', 'descend', 'ascend'],
      render: (_, record) => (
        <UserColumn
          record={record}
          userRoleOnOrg={userRoleOnOrg}
          userRoleOnApps={userRoleOnApps}
          validatePermissionOnSingleApp={validatePermissionOnSingleApp}
        />
      ),
    },
    {
      title: ({ sortColumns }) => (
        <TableSortColumn
          title="Role"
          sortColumns={sortColumns}
          dataIndex="role"
        />
      ),
      dataIndex: 'role',
      sorter: (a, b) => a?.role?.localeCompare(b?.role),
      sortDirections: ['ascend', 'descend', 'ascend'],
      width: 200,
      render: (text) => <div>{text || '-'}</div>,
    },
    {
      title: 'App key',
      dataIndex: 'apiKey',
      width: 200,
      render: (_, record) => <AppKey value={ record?.key } fixedWidth />,
    },
    {
      title: '',
      key: `action ${v4()}`,
      width: 200,
      visible: !validateAppLevelPermission(AppLevelSetting),
      render: (_, record) => {
        const { _id: appId } = record;
        return (
          <ActionWrap>
            {validatePermissionOnSingleApp(AppLevelSetting, appId) && (
              <Tooltip title="App setting">
                <Link
                  href={{
                    pathname: '/integration',
                    query: {
                      parentType: 'settings',
                      setting: 'app_setting',
                      org: orgId,
                      app: appId,
                      app_tab: 'video_recording_setting',
                    },
                  }}
                  as={`/settings/app/${orgId}/${appId}${'/video_recording_setting'}`}
                  passHref
                >
                  <ActionCircleButton
                    shape="circle"
                    icon={<SettingIconSvg />}
                  />
                </Link>
              </Tooltip>
            )}
            {validatePermissionOnSingleApp(['app.delete'], appId) && (
              <AppDeleteModalForm appDetail={record} />
            )}
          </ActionWrap>
        );
      },
    },
  ].filter((item) => !item?.visible);

 isMriFeatureEnabled ? columns.splice(3, 0, {
    title: 'Data storage location',
    dataIndex: 'region',
    width: 200,
    render: (text) => <span>{text || '-'}</span>,
  }) : columns;

  isWebOrg ? columns.splice(1, 0,  {
    title: ({ sortColumns }) => (
      <TableSortColumn
        title="Platform"
        sortColumns={sortColumns}
        dataIndex="appType"
      />
    ),
    dataIndex: 'appType',
    sorter: (a, b) => a?.appType?.localeCompare(b?.appType),
    sortDirections: ['ascend', 'descend', 'ascend'],
    width: 200,
    render: (text) => <div>{mapAppType(text) || '-'}</div>,
  },) : columns;

  const filterAppList = useMemo(
    () =>
      appList?.length &&
      appList.filter((app) =>
        app?.name?.toLowerCase()?.includes(debouncedSearchValue)
      ),
    [debouncedSearchValue, appList]
  );

  useEffect(() => {
    setAppLists(filterAppList);
  }, [debouncedSearchValue]);

  useEffect(() => {
    appList?.length && setAppLists(appList);
  }, [appList]);

  useEffect(() => {
    if (newProfile) {
      const orgIndex = findOrgIndex(newProfile?.organization, orgId);
      setUserRoleOnOrg(newProfile?.organization[orgIndex]?.role);
      setUserRoleOnApps(
        hasManagerRoleOnApps(newProfile?.organization[orgIndex]?.apps)
      );
    }
  }, [newProfile]);

  return (
    <LoaderAdvanced
      show={isLoading}
      message={<ReactLoader type="spin" />}
      backgroundStyle={{
        backgroundColor: 'rgba(255,255,255,1)',
      }}
    >
        <TableWrap
          className="team-table"
          showSorterTooltip={false}
          columns={columns}
          rowClassName={() => 'editable-row'}
          dataSource={appLists || []}
          pagination={false}
          rowKey={(record) => record?._id}
        />
    </LoaderAdvanced>
  );
};

export default AppSection;
