import React, { useState, useMemo, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import NewWindow from 'react-new-window';
import { CopyToClipboard } from 'react-copy-to-clipboard';
import {
  CheckCircleOutlined,
  CopyOutlined,
  InfoCircleOutlined,
} from '@ant-design/icons';
import { Form, Row, Col, Input, Button, Tooltip, Alert } from 'antd';
import $ from 'jquery';

import AppApi from 'services/appApi';
import { getSSOConfiguration, clearSSOConfigurations } from 'redux/actions/sso';
import RoleBasedError from 'components/features/setting/RoleBasedError';

export const FormItemInfo = ({ title, entityUrl, acsUrl }) => (
  <div className="sso-link">
    <div className="form-item">
      <span>{title}</span>{' '}
      <Tooltip title={title}>
        <InfoCircleOutlined />
      </Tooltip>
    </div>
    <p>: {title === 'Entity ID' ? entityUrl : acsUrl}</p>
    <CopyToClipboard
      text={title === 'Entity ID' ? entityUrl : acsUrl}
      onCopy={() => {}}
    >
      <Tooltip placement="topLeft" title={`Copy ${title}`} arrowPointAtCenter>
        <Button
          size="small"
          style={{
            border: 0,
          }}
        >
          <CopyOutlined style={{ marginLeft: -4 }} />
        </Button>
      </Tooltip>
    </CopyToClipboard>
  </div>
);

const { TextArea } = Input;
const SSOConfig = () => {
  const [form] = Form.useForm();
  const dispatch = useDispatch();

  const [, forceUpdate] = useState({});
  const [showPopupWindow, setShowPopupWindow] = useState(false);
  const [ssoMessage, setssoMessage] = useState({
    success: '',
    failure: '',
  });
  const [teams, setTeam] = useState([]);
  const [memberBelongToMoreOrganisation, setmemberBelongToMoreOrganisation] =
    useState(false);

  const { sso, error } = useSelector((state) => state.ssoInfo);
  const {
    ssoUrl,
    entityId,
    certificate,
    spEntityUrl,
    spAcsUrl,
    debug,
    loginUrl,
  } = sso;

  const {
    currentOrgReducer: { orgId },
    applicationReducer: organisationList,
  } = useSelector((state) => state);

  const [loading, setLoading] = useState(false)
  const userRole = organisationList?.find((org) => org.orgId === orgId);
  const isUserAdminManager = useMemo(
    () => userRole?.isOwner || userRole?.role === 1,
    userRole
  );

  const checkTeamMember = (_) => {
    const value = teams.some(
      (item) => item.belongsToMoreThanOneOrganization && item.status === 1
    );
    setmemberBelongToMoreOrganisation(value);
  };

  const testSSOConfig = (_) => {
    setShowPopupWindow(true);
  };

  const getTeamMembers = async () => {
    try {
      const res = await AppApi.getTeamMembers(orgId);
      if (res.status === 200) {
        setTeam(res.data.data.team);
      }
    } catch (err) {
      return err;
    }
  };

  const showAnimation = () => {
    $('.test-successful').show();
    setTimeout(() => {
      $('.test-successful').hide();
    }, 3000);
  };
  const showErrorAnimation = () => {
    $('.test-failed').show();
    setTimeout(() => {
      $('.test-failed').hide();
    }, 3000);
  };

  const handleValidationErrors = (res) => {
    let msg1 = '';
    const { error: errorData } = res.data;   
    for (const x in errorData) {
      if (x === 'ssoUrl') {
        msg1 += `${errorData[`${x}`]}`;
      }
      if (x === 'entityId') {
        msg1 += `${errorData[`${x}`]}`;
      }
      if (x === 'certificate') {
        msg1 += `${errorData[`${x}`]}`;
      }
    }
    res.status === 422
      ? setssoMessage({
          ...ssoMessage,
          failure: msg1,
        })
      : setssoMessage({
          ...ssoMessage,
          failure: 'Something went wrong! Please try again.',
        });
    showErrorAnimation();
  };

  const saveUpdateConfig = async (request) => {
    setLoading(true)
    try {
      const result = await AppApi.saveOrUpdateSSOConfig(request, orgId);
      if (result.status === 200) {
        setssoMessage({
          ...ssoMessage,
          success: result.data.data.message,
        });
        showAnimation();
        dispatch(getSSOConfiguration(orgId));
        setLoading(false)
      }
    } catch (err) {
      const errorRes = err.response;
      handleValidationErrors(errorRes);
      setLoading(false);
    }
  };

  const modifySSOConfig = async () => {
    try {
      const result = await AppApi.modifySSOConfig(orgId, debug);
      if (result.status === 200) {
        setssoMessage({
          ...ssoMessage,
          success: result.data.data.message,
        });
        showAnimation();
        dispatch(getSSOConfiguration(orgId));
        !debug && dispatch(clearSSOConfigurations(spEntityUrl, spAcsUrl));
      }
    } catch (err) {
      const errorRes = err.response;
      handleValidationErrors(errorRes);
    }
  };

  const handleSubmit = async (_) => {
    const values = await form.validateFields();
    saveUpdateConfig(values);
  };

  const newWindowUnloaded = () => {
    setShowPopupWindow(false);
  };

  useEffect(() => {
    checkTeamMember();
  }, [teams]);

  useEffect(() => {
    form.setFieldsValue({
      ssoUrl,
      entityId,
      certificate,
    });
  }, [sso]);

  useEffect(() => {
    forceUpdate({});
  }, []);

  useEffect(() => {
    dispatch(getSSOConfiguration(orgId));
    getTeamMembers();
    return () => {
      dispatch(clearSSOConfigurations(spEntityUrl, spAcsUrl));
    };
  }, []);

  if (!isUserAdminManager) {
    return (
        <RoleBasedError message="The Single Sign On page is only available to the Organization owner and Organization managers." />
    );
  }

  return error ? (
    <Alert
      message="Error"
      description={error}
      type="error"
      showIcon
      style={{ margin: 20 }}
    />
  ) : (
    <>
      <div className="sso-link-wrapper">
        <Row>
          <FormItemInfo title="Entity ID" entityUrl={spEntityUrl} />
          <FormItemInfo title="ACS URL" acsUrl={spAcsUrl} />
        </Row>
      </div>
      <Row className="sso-form-wrapper">
        <Col span={12}>
          <Form
            form={form}
            onFinish={handleSubmit}
            className="sso-form"
            initialValues={{
              ssoUrl,
              entityId,
              certificate,
            }}
          >
            <Form.Item
              label="SSO URL"
              name="ssoUrl"
              rules={[
                { required: true, message: 'Please enter sso url!' },
                { min: 2 },
              ]}
            >
              <Input />
            </Form.Item>
            <Form.Item
              label="Entity ID"
              name="entityId"
              rules={[
                { required: true, message: 'Please enter entity id' },
                { min: 2 },
              ]}
            >
              <Input />
            </Form.Item>
            <Form.Item
              label="Certificate"
              name="certificate"
              rules={[
                { required: true, message: 'Please enter certificate' },
                { min: 2 },
              ]}
            >
              <TextArea autoSize={{ minRows: 3, maxRows: 5 }} />
            </Form.Item>
            <div className="btn-group">
              <Form.Item shouldUpdate>
                {() => (
                  <Button
                    type="primary"
                    htmlType="submit"
                    loading={loading}
                    disabled={
                      !debug ||
                      !form.isFieldsTouched(true) ||
                      !!form
                        .getFieldsError()
                        .filter(({ errors }) => errors.length).length
                    }
                  >
                    Save
                  </Button>
                )}
              </Form.Item>
              {debug && (
                <Form.Item shouldUpdate>
                  {() => (
                    <Button
                      type="secondary"
                      disabled={
                        !form.isFieldsTouched(true) ||
                        !!form
                          .getFieldsError()
                          .filter(({ errors }) => errors.length).length
                      }
                      onClick={() => testSSOConfig()}
                    >
                      Test Config
                    </Button>
                  )}
                </Form.Item>
              )}
              <Form.Item shouldUpdate>
                {() => (
                  <Button
                    type="secondary"
                    disabled={
                      !form.isFieldsTouched(true) ||
                      !!form
                        .getFieldsError()
                        .filter(({ errors }) => errors.length).length
                    }
                    onClick={() => modifySSOConfig()}
                  >
                    {debug ? ' Enable SSO' : 'Disable SSO'}
                  </Button>
                )}
              </Form.Item>
            </div>
          </Form>
        </Col>
        <Col span={12}>
          <div className="sso-message">
            <div className="test-successful" style={{ display: 'none' }}>
              <CheckCircleOutlined />
              <span className="info-text">{ssoMessage.success}</span>
            </div>
            <div className="test-failed" style={{ display: 'none' }}>
              <InfoCircleOutlined />
              <span>{ssoMessage.failure}</span>
            </div>
            {memberBelongToMoreOrganisation && (
              <div className="message">
                <div className="message-icon">
                  <InfoCircleOutlined />
                </div>
                <div className="message-text">
                  <p>
                    The following members of <strong>Super Org</strong> are
                    already member of at least one other organization on the
                    UXCam dashboard.
                  </p>
                  <p className="name">
                    {teams.map((item) => (
                      <>
                        {' '}
                        {item.belongsToMoreThanOneOrganization &&
                          item.status === 1 && (
                            <>
                              {' '}
                              <span>
                                {item.name} {`(${item.email})`}{' '}
                              </span>{' '}
                              <br />
                            </>
                          )}{' '}
                      </>
                    ))}
                  </p>
                  <p>
                    Single Sign On will only work if all members of your
                    organization are only members of your organization so please
                    ask them to leave the other organizations or you can also
                    remove their access from your organization before allowing
                    Single Sign On.
                  </p>
                  {/* <p>Please refer to this documentation for <a href='#'>more details</a>.</p> */}
                </div>
              </div>
            )}
          </div>
        </Col>
      </Row>
      {showPopupWindow && loginUrl !== null && (
        <NewWindow
          url={loginUrl}
          onUnload={() => newWindowUnloaded()}
          title="SSO Configuration"
          center="parent"
          features={{
            left: 200,
            top: 200,
            width: 600,
            height: 600,
            scrollbars: 'yes',
            resizable: 'yes',
          }}
        />
      )}
    </>
  );
};

export default SSOConfig;
