import React, { useState, useEffect } from 'react';
import { Upload, Button, Spin, message } from 'antd';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';
import { LoadingOutlined } from '@ant-design/icons';

import ProfileImageOrText from 'components/features/setting/ProfileImageOrText';
import { updateOrgImage } from 'components/features/setting/useSettingPage';
import { updateActiveSubscription } from 'redux/actions/subscription';
import { convertFileToBase64 } from 'Utils/helpers/commonUtils';

const UploadButton = styled(Button)`
  color: #5d97ff;
  border-color: #5d97ff;
  margin-left: 18px;
`;

const acceptType = 'image/jpeg, image/jpg, image/png';
const fileName = 'imageFile';
const fileType = 'picture';

const ProfilePhoto = ({ hasOrgPermission }) => {
  const formData = new FormData();

  const [selectedFileList, setSelectedFileList] = useState([]);
  const [loading, setLoading] = useState(false);
  const [imageSrc, setImageScr] = useState();
  const dispatch = useDispatch();

  const { currentOrgReducer: currentOrg } = useSelector((state) => state);
  const { orgId, name, organizationName } = currentOrg || {};

  const beforeUpload = (file) => {
    const { type, size } = file;
    const isJpgOrPng = acceptType.includes(type);
    const isMaxSize = size / 1024 / 1024 < 2;
    if (isJpgOrPng) {
      if (!isMaxSize) {
        message.error('Image must smaller than 2MB.');
      }
    } else {
      message.error(
        'Only files with these extensions are allowed: png, jpg, jpeg.'
      );
    }
    return isJpgOrPng && isMaxSize;
  };

  const handleImageUpload = async (options) => {
    const isValid = await beforeUpload(options?.file);
    const base64String = await convertFileToBase64(options?.file);
    formData.append(fileName, options?.file);
    const payload = {
      [fileName]: base64String,
    };
    setSelectedFileList(options);
    if (isValid) {
      setLoading(true);
      const response = await updateOrgImage(payload, orgId);
      if (response?.organization) {
        setImageScr(response?.organization?.image);
        const updateCurrentOrg = {
          ...currentOrg,
          organizationIcon: response?.organization?.image,
        };
        dispatch(updateActiveSubscription(updateCurrentOrg));
        message.success(response?.message);
        setLoading(false);
      }
      if (response?.error) {
        response?.error?.imageFile &&
          message.error(response?.error?.imageFile[0]);
      }
      setSelectedFileList({ [fileName]: [] });
      setLoading(false);
    }
  };

  useEffect(() => {
    setImageScr(currentOrg?.organizationIcon);
  }, [orgId]);

  return (
    <>
      <Spin spinning={loading} indicator={<LoadingOutlined />} size="small">
        <ProfileImageOrText
          picture={imageSrc}
          size={80}
          nameInfo={organizationName || name}
          shape="circle"
        />
      </Spin>

      <Upload
        name={fileName}
        customRequest={handleImageUpload}
        fileList={selectedFileList[fileName]?.originFileObj}
        accept={acceptType}
        listType={fileType}
        showUploadList={false}
        maxCount={1}
      >
        <UploadButton
          disabled={!hasOrgPermission(['organization.update']) || loading}
        >
          Choose image
        </UploadButton>
      </Upload>
    </>
  );
};

export default ProfilePhoto;
