import React from 'react';
import styled from 'styled-components';
import DeletionApiKey from './DeletionApiKey';

// Copied from PublicAccess rather than shared, deliberately: the two tabs must
// look identical, and a shared wrapper would let a change to one silently
// restyle the other. If they ever need to diverge, they can.
const StyledWrapper = styled.div`
  min-width: 600px;
  max-width: 55vw;

  /* Same metrics as the Data access API tab's alert (StyledAlert in
     PublicApiAccess): 12px, borderless, 4px radius, 18px clear of the first
     row. Antd sizes a message up to 16px once a description is present, which
     is what made this tab's type larger than every other tab's. Only the
     colour differs from the data-access one, and deliberately -- this is a
     warning, not an info note. */
  .ant-alert.deletion-warning {
    font-size: 12px;
    border: none;
    border-radius: 4px;
    width: 100%;
    min-height: 40px;
    height: auto;
    margin-bottom: 18px;
  }
  .ant-alert.deletion-warning .ant-alert-message {
    font-size: 12px;
    font-weight: 600;
  }
  .ant-alert.deletion-warning .ant-alert-description {
    font-size: 12px;
  }

  /* UNIFORM WIDTH. width:fit-content sized each box to its own longest line,
     so the snippets ended up different widths and the column looked ragged.
     One width now, with the content wrapping inside instead.

     The panel is not a grey slab itself -- the switchers sit on the page and
     only the code is boxed, matching the data-access panel.

     One block, not two: these were two rules on the same selector with a
     blank gap between them, left over from when the first was shared with
     .session-api. Per Ekata's review. */
  .api-form .form-item.snippet-panel {
    width: 100%;
    max-width: 820px;
    background: none;
    padding: 0;
    line-height: normal;
  }
  /* ONE SWITCHER PER ROW. Antd's Segmented is inline-block, so the operation
     and language switchers sat on the same line and read as a single strip of
     six tabs -- "Delete users … Python" -- as though picking curl were an
     alternative to picking Check status. They are two questions, so they get
     two rows. */
  .api-form .form-item.snippet-panel .ant-segmented {
    display: flex;
    width: fit-content;
  }
  /* One rhythm down the panel: switcher, endpoint, switcher, code, each 12px
     apart. The language switcher used to sit 8px below, which only looked
     deliberate while it shared a line with the operation switcher. */
  .api-form .form-item.snippet-panel .language-switch {
    margin-top: 12px;
  }

  /* Verb + URL, between the switchers, as on the data-access panel. Green
     because it is the same "this works" green as the Enabled status above;
     the URL is not a link -- these endpoints are POST only. */
  .api-form .form-item.snippet-panel .endpoint-line {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-top: 12px;
    line-height: normal;
  }
  .api-form .form-item.snippet-panel .endpoint-line .method-badge {
    flex: 0 0 auto;
    background: #f6ffed;
    border: 1px solid #b7eb8f;
    border-radius: 10px;
    color: #389e0d;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.4px;
    padding: 1px 8px;
  }
  /* In the flow at the end of the line rather than pinned: this line is one
     row tall, and a pinned button would overlap a long URL as it wraps.
     Spacing comes from the parent gap -- no margin of its own, or it sits
     12px from the URL while the badge sits 8px from it. */
  .api-form .form-item.snippet-panel .endpoint-line .endpoint-copy {
    border: 0;
    background: transparent;
    flex: 0 0 auto;
  }
  .api-form .form-item.snippet-panel .endpoint-line code {
    font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo,
      monospace;
    font-size: 12px;
    color: #161e35;
    word-break: break-all;
  }

  .api-form .form-item.snippet-panel .snippet-body {
    position: relative;
    margin-top: 12px;
    background: #f5f5f5;
    border-radius: 4px;
    padding: 12px 44px 12px 12px;
  }
  /* background and padding are reset explicitly, not left to the cascade.
     The globally imported prism-tomorrow theme styles pre[class*="language-"]
     with a #2d2d2d slab, and Prism copies the language class from the <code>
     onto its parent <pre>. This panel no longer highlights, but the reset keeps
     the surface light even if a language class lands here again. */
  .api-form .form-item.snippet-panel .snippet-body pre,
  .api-form .form-item.snippet-panel .snippet-body pre code {
    margin: 0;
    padding: 0;
    background: none;
    font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo,
      monospace;
    font-size: 12px;
    line-height: 18px;
    color: #161e35;
    white-space: pre-wrap;
    word-break: break-word;
  }
  /* Pinned rather than in the flow, so the button does not move as the
     snippet changes height between languages. */
  .api-form .form-item.snippet-panel .snippet-copy {
    position: absolute;
    top: 8px;
    right: 8px;
    border: 0;
    background: transparent;
  }
  .api-form .form-item.call-the-api,
  .api-form.call-the-api {
    align-items: flex-start;
  }

  .api-wrapper {
    min-height: 200px;
  }

  .api-form {
    display: flex;
    align-items: flex-start;
  }
  .api-form .form-item {
    margin-right: 10px;
    margin-bottom: 10px;
    line-height: 33px;
  }
  /* Every row is label + content, and a label that wraps drags its row out of
     line with the ones above. 150px clears the longest currently rendered
     ("Deletion Key" and "Last changed", both with room to spare) and matches
     the Data access API tab, so the two read as one page rather than two.

     150px is stated once here. There was a second width:125px on this
     selector further up with the same specificity, so it never applied -- and
     the comment justifying it argued for a width the page did not use. Per
     Ekata's review. */
  .api-form .form-item.form-label {
    width: 150px;
    flex: 0 0 150px;
  }
  .api-form .form-item .ant-input {
    min-width: 300px;
    height: 40px;
    border-radius: 4px;
    border-color: #dddddd;
  }

  /* Primary action, the same blue as "Generate API Key" on the Data access
     API tab. Scoped away from .ant-btn-dangerous so Revoke does not inherit
     it -- a destructive action must not look like the primary one. */
  .api-footer {
    margin-left: 160px;
  }
  .api-footer .ant-btn.ant-btn-default:not(.ant-btn-dangerous) {
    background: #5d97ff;
    border: none;
    color: #ffffff;
    border-radius: 4px;
    height: 40px;
    padding: 0 20px;
    margin-bottom: 24px;
  }
  .api-footer .ant-btn.ant-btn-default:not(.ant-btn-dangerous):hover {
    background: #4a86f0;
    color: #ffffff;
  }
  .api-footer .ant-btn.ant-btn-dangerous {
    border-radius: 4px;
    height: 40px;
    padding: 0 20px;
    margin-bottom: 24px;
  }
`;

const DataDeletionApi = ({ appId }) => (
  <StyledWrapper>
    <DeletionApiKey appId={appId} />
  </StyledWrapper>
);

export default DataDeletionApi;
