import { useRouter } from 'next/router';
import { useCallback, useEffect, useRef } from 'react';

const throwFakeErrorToFoolNextRouter = () => {
  // eslint-disable-next-line no-throw-literal
  throw 'Route change canceled due to unsaved form changes. by useNavigationChange triggered Please disregard this error.';
};

const useNavigationChange = ({ shouldStopNavigation, onNavigate }) => {
  const router = useRouter();
  const currentPath = router.asPath;
  const nextPath = useRef('');

  const killRouterEvent = useCallback(() => {
    router.events.emit('routeChangeError');
     throwFakeErrorToFoolNextRouter()
  }, [router]);

  const onRouteChangeStart = useCallback(
    (url) => { 
      if (shouldStopNavigation && url !== currentPath) {
        onNavigate(url);
        nextPath.current = currentPath;
        killRouterEvent();
      }
    },
    [shouldStopNavigation, killRouterEvent, onNavigate, currentPath]
  );

  useEffect(() => {
    router.events.on('routeChangeStart', onRouteChangeStart);
    return () => {
      router.events.off('routeChangeStart', onRouteChangeStart);
    };
  }, [
    router.events,
    currentPath,
    killRouterEvent,
    onNavigate,
    shouldStopNavigation,
    onRouteChangeStart,
  ]);

  const navigate = () => {
    router.push(nextPath.current);
  };

  return navigate;
};

export default useNavigationChange;
