import React, { useMemo } from 'react';
import { useSelector } from 'react-redux';
import styled from 'styled-components';
import { useQueryClient } from 'react-query';
import { Popconfirm, Button } from 'antd';
import { CreditCardOutlined, RetweetOutlined } from '@ant-design/icons';
import { theme } from 'theme';

import {
  useRetryPayment,
  useFetchPaymentInfo,
} from 'components/features/setting/useSettingPage';
import ChargebeeButton from '../Chargebee';

const PlanDetailWrapper = styled.div`
  border: 1px solid #c0cad9;
  border-radius: 5px;
  height: auto;
  padding: 20px;
  margin-bottom: 20px;
`;

const PaymentPlanWrap = styled.div`
  font-weight: 500;
  font-size: 16px;
  display: flex;
  line-height: normal;
  justify-content: space-between;

  &:not( :first-of-type ) {
    margin-top: 10px;
  }
`;

const PaymentPlanLeft = styled.div`
  flex: 50%;
  h3 {
    font-size: ${ theme.fontSize( 1.8 ) };
    line-height: ${ theme.fontSize( 2.8 ) };
    color: ${ theme.colors.primaryMidnight.toString() };
    font-weight: 500;
  }
`;

const PaymentPlanRight = styled.div`
  justify-content: flex-end;
  display: flex;
`;

const PaymentPlanLeftTotal = styled(PaymentPlanLeft)`
  font-size: 14px;
  color: #161e35;
  font-weight: 500;
  svg {
    margin-right: 4px;
  }
`;

const PaymentPlanRightTotal = styled(PaymentPlanRight)`
  font-size: 14px;
  color: #161e35;
  font-weight: 500;
`;

const PlanExpire = styled.div`
  border: 1px solid #f4584c;
  display:flex;
  align-items:center;
  margin-right: 8px;
  padding:6px;
  font-weight: 400;
  font-size: 14px;
  border-radius: 4px;
  p {
    margin-bottom: 0;
    color: #f4584c;
  }
`;

const ButtonStyled = styled(Button)`
  border-radius: 4px;
  color: #5d97ff;
  border-color: #5d97ff;
  font-weight: 400;
  font-size: 14px;
  line-height: 16px;
  margin: 8px 0;
`;
const RetryPayment = styled.div`
  display: flex;
  justify-content: flex-end;
`;

const pastDeuInfo =
  'We are unable to process your payment. Please update your payment method.';

const PaymentInfo = () => {
  const queryClient = useQueryClient();
  const {
    currentOrgReducer: { orgId },
  } = useSelector((state) => state);

  const { isLoading: retryPaymentLoading, refetch } = useRetryPayment(orgId);
  const { data: creditCardData, refetch: refetchCardInfo } =
    useFetchPaymentInfo(orgId);

  const currentSubscriptionKey = useMemo(
    () => `currentSubscription${orgId}`,
    [orgId]
  );
  const paymentHistoryKey = useMemo(() => `payhistory ${orgId} ${1}`, [orgId]);
  const manageCardUrl = useMemo(
    () => `subscription/manage-payments/organization/${orgId}`,
    [orgId]
  );
  const currentSubscription = queryClient.getQueryData(currentSubscriptionKey);
  const { method } = currentSubscription || {};

  const handleRetryPayment = () => {
    refetch();
    queryClient.invalidateQueries(currentSubscriptionKey);
    queryClient.invalidateQueries(paymentHistoryKey);
  };

  const currentSubscriptionStatus =
    currentSubscription?.subscription?.status?.toLowerCase();

  return (
    (creditCardData?.cardType || method?.cardType) && (
      <PlanDetailWrapper>
        <PaymentPlanWrap>
          <PaymentPlanLeft>
            <h3>Payment methods</h3>
          </PaymentPlanLeft>
          <PaymentPlanRight>
            {creditCardData?.cardType && (
              <ChargebeeButton
                cardChangeUrl={manageCardUrl}
                refetchCardInfo={refetchCardInfo}
              />
            )}
          </PaymentPlanRight>
        </PaymentPlanWrap>
        {currentSubscription?.method?.expired && !creditCardData?.cardType && (
          <PlanExpire>
            <p>
              Your card - {currentSubscription?.method?.cardType} (
              {currentSubscription?.method?.maskedNumber}) is expired. Please
              update your card.
            </p>
          </PlanExpire>
        )}

        {currentSubscriptionStatus === 'past due' && (
          <PaymentPlanWrap>
            <PlanExpire>
              <p>{pastDeuInfo}</p>
            </PlanExpire>
            <RetryPayment>
              <Popconfirm
                title="Are you sure to retry the payment?"
                onConfirm={handleRetryPayment}
                okText="Yes"
                cancelText="No"
                overlayClassName="payment-confirm-box"
              >
                <ButtonStyled loading={retryPaymentLoading}>
                  Retry payment <RetweetOutlined />
                </ButtonStyled>
              </Popconfirm>{' '}
            </RetryPayment>
          </PaymentPlanWrap>
        )}
        {creditCardData?.expired && (
          <PlanExpire>
            <p>
              Your card - {creditCardData?.cardType?.toUpperCase()} (
              {creditCardData?.maskedNumber}) is expired. Please update your
              card.
            </p>
          </PlanExpire>
        )}

        <PaymentPlanWrap>
          {method?.maskedNumber && !creditCardData?.cardType && (
            <>
              <PaymentPlanLeftTotal>
                <CreditCardOutlined />
                {method?.cardType}
              </PaymentPlanLeftTotal>
              <PaymentPlanRightTotal>
                {' '}
                {method?.maskedNumber || 'N/A'}
              </PaymentPlanRightTotal>
            </>
          )}
          {creditCardData?.cardType && (
            <>
              <PaymentPlanLeftTotal>
                <CreditCardOutlined />
                {creditCardData?.cardType?.toUpperCase()}
              </PaymentPlanLeftTotal>
              <PaymentPlanRightTotal>
                {' '}
                {creditCardData?.maskedNumber || 'N/A'}
              </PaymentPlanRightTotal>
            </>
          )}
        </PaymentPlanWrap>
      </PlanDetailWrapper>
    )
  );
};

export default PaymentInfo;
