import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { useQueryClient } from 'react-query';
import styled from 'styled-components';
import { Button, Modal, message } from 'antd';
import { ExclamationCircleFilled, CalendarOutlined } from '@ant-design/icons';
import { trackPageViews } from 'redux/actions/trackingReport';
import { useFetchTeamList } from 'components/features/setting/useSettingPage';
import SubscriptionApi from 'services/subscriptionApi';

const CancelButton = styled(Button)`
  background-color: #f4584c !important;
  border-color: #f4584c !important;
  color: #fff !important;

  &:hover,
  &:focus {
    background-color: #e0463a !important;
    border-color: #e0463a !important;
    color: #fff !important;
  }

  &[disabled],
  &[disabled]:hover,
  &[disabled]:focus {
    background-color: #fbb0a9 !important;
    border-color: #fbb0a9 !important;
    color: #fff !important;
  }
`;

const StyledModal = styled(Modal)`
  .ant-modal-content {
    border-radius: 12px;
  }
  .ant-modal-body {
    padding: 32px 32px 8px;
    text-align: center;
  }
  .ant-modal-footer {
    border-top: none;
    padding: 16px 32px 28px;
    display: flex;
    gap: 12px;
  }
  .ant-modal-footer button {
    flex: 1;
    height: 40px;
    margin: 0;
    border-radius: 8px;
    font-weight: 600;
  }
`;

const IconCircle = styled.div`
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: #fdeeec;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;

  .anticon {
    font-size: 26px;
    color: #f4584c;
  }
`;

const ModalTitle = styled.h3`
  font-size: 18px;
  font-weight: 600;
  color: #161e35;
  margin: 0 0 8px;
`;

const ModalText = styled.p`
  font-size: 14px;
  line-height: 1.5;
  color: #5b6b85;
  margin: 0 0 16px;
`;

const AccessInfo = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: #f5f7fa;
  border-radius: 8px;
  padding: 10px 14px;
  margin: 0 0 16px;
  font-size: 13px;
  color: #161e35;

  .anticon {
    color: #8a99b1;
  }

  strong {
    font-weight: 600;
  }
`;

const CancelSubscription = ({ orgId, queryKey, isOwner }) => {
  const dispatch = useDispatch();
  const queryClient = useQueryClient();
  const [modalOpen, setModalOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  // Owner email is only needed to tell non-owners who to contact, so the team
  // list is fetched only for non-owners.
  const { data: teamList } = useFetchTeamList(orgId, !isOwner);

  const currentSubscription = queryClient.getQueryData(queryKey);
  const isActive =
    currentSubscription?.subscription?.status?.toLowerCase() === 'active';
  const isCancelScheduled =
    currentSubscription?.payment?.renewalStatus === 'cancel';
  const termEndDate =
    currentSubscription?.payment?.billingEndDate ||
    currentSubscription?.payment?.nextBillingDate;

  const handleCancel = async () => {
    setLoading(true);
    try {
      const res = await SubscriptionApi.cancelSelfServeSubscription(orgId);
      message.success(
        res?.data?.message ||
          'Your subscription has been scheduled for cancellation at the end of your current term.'
      );
      setModalOpen(false);
      dispatch(
        trackPageViews(null, {
          eventName: 'wa_cancel_subscription',
          track_type: 'event',
          eventProperty: { org_id: orgId },
        })
      );
      await queryClient.invalidateQueries(queryKey);
    } catch (error) {
      const status = error?.response?.status;
      const apiMsg = error?.response?.data?.error?.message;
      if (status === 403) {
        message.error(
          apiMsg || 'You do not have permission to perform this action.'
        );
      } else if (status === 409) {
        message.error(
          apiMsg ||
            'Cannot cancel a subscription that is Cancelled or Expired already'
        );
        await queryClient.invalidateQueries(queryKey);
      } else {
        message.error(apiMsg || 'Something went wrong. Please try again later.');
      }
      setModalOpen(false);
    } finally {
      setLoading(false);
    }
  };

  // Self-serve cancellation is only offered while the subscription is active
  // and not already scheduled for cancellation.
  if (!isActive || isCancelScheduled) {
    return null;
  }

  // The owner sees the cancellation confirmation; non-owners get the owner's
  // email so the popup can point them to the right person.
  const ownerEmail =
    !isOwner && Array.isArray(teamList)
      ? teamList.find((member) => member?.isOwner)?.email
      : undefined;

  return (
    <>
      <CancelButton
        type="primary"
        loading={loading}
        disabled={loading}
        onClick={() => setModalOpen(true)}
      >
        Cancel subscription
      </CancelButton>
      {isOwner ? (
        <StyledModal
          visible={modalOpen}
          title={null}
          width={420}
          centered
          okText="Cancel subscription"
          okButtonProps={{
            style: {
              backgroundColor: '#f4584c',
              borderColor: '#f4584c',
              color: '#fff',
            },
          }}
          cancelText="Keep subscription"
          confirmLoading={loading}
          onOk={handleCancel}
          onCancel={() => setModalOpen(false)}
        >
          <IconCircle>
            <ExclamationCircleFilled />
          </IconCircle>
          <ModalTitle>Cancel your subscription?</ModalTitle>
          <ModalText>
            We&apos;ll schedule your subscription to cancel at the end of your
            current term — you keep full access until then.
          </ModalText>
          {termEndDate && (
            <AccessInfo>
              <CalendarOutlined />
              <span>
                Access continues until <strong>{termEndDate}</strong>
              </span>
            </AccessInfo>
          )}
          <ModalText>
            After that, your plan won&apos;t renew automatically and
            you&apos;ll need to re-subscribe to continue.
          </ModalText>
        </StyledModal>
      ) : (
        <StyledModal
          visible={modalOpen}
          title={null}
          width={420}
          centered
          footer={[
            <Button
              key="ok"
              type="primary"
              onClick={() => setModalOpen(false)}
            >
              Got it
            </Button>,
          ]}
          onCancel={() => setModalOpen(false)}
        >
          <IconCircle>
            <ExclamationCircleFilled />
          </IconCircle>
          <ModalTitle>Only the owner can cancel</ModalTitle>
          <ModalText>
            Only the organization owner can cancel this subscription.{' '}
            {ownerEmail
              ? `Please reach out to ${ownerEmail} to make changes to your plan.`
              : 'Please reach out to your organization owner to make changes to your plan.'}
          </ModalText>
        </StyledModal>
      )}
    </>
  );
};

export default CancelSubscription;
