import { Tooltip } from 'antd';
import styled from 'styled-components';
import React, { memo, useCallback } from 'react';
import { Cell, createColumnHelper, Row } from '@tanstack/react-table';

import { Column } from 'components/features/issues/IssueDashboard/IssueTable/types';
import {
    gesturesValueToStringTypeAdjusted,
    gesturesViewTypeIntToStringAdjusted,
} from 'components/common/NoCodeEvents/NoCodeEventsPopups/ManageNoCodeEventPopup';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { renderAnyOrUndefined } from 'components/common/NoCodeEvents/NoCodeEventsPopups/helpers';

import { INocodeEvent } from 'types/nocodeEvents';

import IconPencil from 'public/static/icon-pencil.svg';
import IconDuplicate from 'public/static/icon-duplicate.svg';
import IconBin from 'public/static/icon-bin-with-lid.svg';

import headers from './nocodeTable.json';

interface NocodeColumn {
    name: string,
    eventType: string,
    screenName: string,
    gestureType: number,
    viewType: number,
    elementId: string,
    createdBy: string,
    createdAt: Date,
    action: never,
}

const columnHelper = createColumnHelper<NocodeColumn>();

const CellWrapper = styled.span`
  span{
    max-width: 90%;
  }
`

const Actions = styled.div`
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;

  button:last-of-type {
    color: #f4594c;
  }
`;

const Button = styled.button`
	border: none;
	outline: none;
	background: transparent;
	cursor: pointer;
	margin: 0;
	padding: 0;
	height: 24px;
	width: 24px;
	display: flex;
	justify-content: center;
	align-items: center;
`

const CellComponent: React.FC<{ cell: Cell<NocodeColumn, never>, row: Row<NocodeColumn> }> = memo(({ cell, row }) => {
  const { getValue } = cell;
  const { original } = row;

  const {
    setCurrentAction,
    setManagePopupOpen,
    setDeletePopupOpen,
    setScreenEventModalOpen,
    setDeleteScreenEventPopupOpen,
    setDuplicateEventModalOpen,
  } = useNoCodeEventsContext();

  const handleDuplicate = useCallback(
    (event: INocodeEvent) => {
      if (event.eventType === 'Screen') { 
        setCurrentAction({
          name: event.name,
          type: "smart_screenvisit_event",
          description: event.description || '',
          id: event.nceId as unknown as string,
          eventType: event.eventType,
          createdByName: event.createdByName,
          createdOn: event.createdOn,
          props: {
            activityName: event.screenName,
          },
        });
      } else {
        setCurrentAction({
          name: event.name,
          type: 'smart_gesture_event',
          description: event.description || '',
          id: event.nceId as unknown as string,
          screenName: event.screenName,
          eventType: event.eventType,
          createdByName: event.createdByName,
          createdOn: event.createdOn,
          props: {
            category: event.category,
            gestureType:
              event.gestureType !== undefined
                ? gesturesValueToStringTypeAdjusted[event.gestureType]
                : undefined,
            idString: event.elementId,
            viewName: event.viewName,
            viewType:
              event.viewType !== undefined
                ? gesturesViewTypeIntToStringAdjusted[event.viewType]
                : undefined,
            viewTypeId: event.viewTypeId,
          },
        });
      }
      setDuplicateEventModalOpen(true)
    },
    [setCurrentAction, setDuplicateEventModalOpen]
  );

  const handleDelete = useCallback(
    (event: INocodeEvent) => {
      if (event.eventType === 'Screen') { 
        setCurrentAction({
          name: event.name,
          type: "smart_screenvisit_event",
          description: event.description || '',
          id: event.nceId as unknown as string,
          eventType: event.eventType,
          createdByName: event.createdByName,
          createdOn: event.createdOn,
          props: {
            activityName: event.screenName,
          },
        });
        setDeleteScreenEventPopupOpen(true);
      } else {
        setCurrentAction({
          name: event.name,
          type: 'smart_gesture_event',
          description: event.description || '',
          id: event.nceId as unknown as string,
          screenName: event.screenName,
          eventType: event.eventType,
          createdByName: event.createdByName,
          createdOn: event.createdOn,
          props: {
            category: event.category,
            gestureType:
              event.gestureType !== undefined
                ? gesturesValueToStringTypeAdjusted[event.gestureType]
                : undefined,
            idString: event.elementId,
            viewName: event.viewName,
            viewType:
              event.viewType !== undefined
                ? gesturesViewTypeIntToStringAdjusted[event.viewType]
                : undefined,
            viewTypeId: event.viewTypeId,
          },
        });
        setDeletePopupOpen(true);
      }
    },
    [setCurrentAction, setDeletePopupOpen, setDeleteScreenEventPopupOpen]
  );

  const handleEdit = useCallback(
    (event: INocodeEvent) => {
      if (event.eventType === 'Screen') {
        setCurrentAction({
          name: event.name,
          type: "smart_screenvisit_event",
          description: event.description || '',
          id: event.nceId as unknown as string,
          eventType: event.eventType,
          createdByName: event.createdByName,
          createdOn: event.createdOn,
          props: {
            activityName: event.screenName,
          },
        });
        setScreenEventModalOpen(true);
      } else {
        setCurrentAction({
          name: event.name,
          type: 'smart_gesture_event',
          description: event.description || '',
          id: event.nceId as unknown as string,
          screenName: event.screenName,
          eventType: event.eventType,
          createdByName: event.createdByName,
          createdOn: event.createdOn,
          props: {
            category: event.category,
            gestureType:
              event.gestureType !== undefined
                ? gesturesValueToStringTypeAdjusted[event.gestureType]
                : undefined,
            idString: event.elementId,
            viewName: event.viewName,
            viewType:
              event.viewType !== undefined
                ? gesturesViewTypeIntToStringAdjusted[event.viewType]
                : undefined,
            viewTypeId: event.viewTypeId,
          },
        });
        setManagePopupOpen(true);
      }
    },
    [setCurrentAction, setManagePopupOpen, setScreenEventModalOpen]
  );

  if (cell.column.id === 'action') {
    return (
      <Actions>
        <Tooltip title="Edit event">
          <Button
            type="button"
            onClick={(e)=>{
              e.stopPropagation()
              handleEdit(original as unknown as INocodeEvent)}
            }
          >
            <IconPencil />
          </Button>
        </Tooltip>
        <Tooltip title="Duplicate event">
          <Button
            type="button"
            onClick={(e)=>{
              e.stopPropagation()
              handleDuplicate(original as unknown as INocodeEvent)}
            }
          >
            <IconDuplicate />
          </Button>
        </Tooltip>
        <Tooltip title="Delete event">
          <Button
            type="button"
            onClick={(e) => {
              e.stopPropagation()
              handleDelete(original as unknown as INocodeEvent)}
            }
          >
            <IconBin />
          </Button>
        </Tooltip>
      </Actions>
    );
  }
  return <CellWrapper>{renderAnyOrUndefined(getValue())}</CellWrapper>
})

export default function useNocodeColumns(){
    const columns = React.useMemo(() => headers?.map((header: Column) => {
        const {isVisible, title, attribute, isSortable} = header;
        return isVisible ? 
        columnHelper.accessor(attribute as keyof NocodeColumn, {
            header: () => title,
            cell: CellComponent,
            enableSorting: isSortable,
        }) : null;
        })
        
    , []);

    return columns
}