import React, { useState, useMemo, useCallback, useEffect } from 'react';

import { v4 } from 'uuid';
import styled from 'styled-components';
import { useSelector } from 'react-redux';
import { useQueryClient } from 'react-query';
import { Button, message, Table, Tooltip } from 'antd';

import ReactLoader from 'components/common/reactLoading';
import LoaderAdvanced from 'components/common/LoaderAdvanced';
import {
  useFetchTeamList,
  useResendInvitation,
} from 'components/features/setting/useSettingPage';
import UserImageInfo from 'components/features/setting/ProfileImageOrText';
import TableSortColumn from 'components/features/setting/TableSortColumn';
import {
  findOrgIndex,
  handleLowerCase,
  authorizedOrgAppTeamPermission,
  authorizeAppManagerPermission,
  authorizeOrgManagerPermission,
} from 'components/features/setting/commonUtils';
import useDebounce from 'hooks/useDebounce';
import isArray from 'lodash/isArray';
import TeamAppList from './TeamAppList';
import { useSettingPage } from '../context';
import TeammateDeleteButton from './TeammateDeleteButton';
import TeammateModalForm from './TeammateModalForm';
import { ResendIconSvg } from '../SvgIcon';
import { AppListContent } from './TeamExtraContent';

const TableWrap = styled(Table)`
  .ant-table-thead > tr > th {
    background: none;
    &::before {
      display: none;
    }
  }
  td.ant-table-column-sort {
    background: none;
  }
  .ant-table-thead th.ant-table-column-has-sorters:hover {
    background: none;
  }

  .ant-table-column-sorter {
    visibility: collapse;
  }

  .ant-table-tbody > tr.ant-table-row-selected:hover > td {
    background: #e6f7ff;
  }
  .ant-table-tbody > tr.ant-table-row-selected > td {
    background: transparent;
  }
`;

const UserColumnOuter = styled.div`
  display: flex;
  align-items: center;
`;

const UserColumnInner = styled.div`
  display: flex;
  flex-direction: column;
  margin-left: 10px;
`;

const StatusWrap = styled.div`
  display: flex;
  align-items: center;
  font-size: 12px;
  border-radius: 20px;
  padding: 0 8px;
  background: ${({ isexpired }) => 
    isexpired === 'expired' ? '#ff4d4f' : 'rgba(93, 151, 255, 0.2)'
  };
  height: auto;
  color: #5d97ff;
  color: ${({ isexpired }) => 
    isexpired === 'expired' ? '#fff' : '5d97ff'
  };
  line-height: 0;
  margin-left: 10px;
  min-width: 63px;
  max-height: 25px;
`;
const MFAWrapperStatus = styled(StatusWrap)`
  background: rgba(39, 174, 96, 0.2);
  min-width: 90px;
  max-height: 25px;
  color: #27ae60;
`;

const ActionWrap = styled.div`
  display: flex;
  justify-content: flex-end;
`;

const CircleButton = styled(Button)`
  height: 41px;
  width: 42px;
  margin: 0 8px;
  color: #5d97ff;
  border-color: #dee8ff;
  svg {
    margin: 4px 6px;
  }
`;

const TextWrap = styled.div`
  color: #161e35;
`;

const NameStatusWrap = styled.div`
  display: flex;
  flex-direction: row;
`;

const NameWrap = styled(TextWrap)`
  font-weight: 500;
  font-size: 14px;
`;

const EmailWrap = styled(TextWrap)`
  font-weight: 400;
  font-size: 12px;
`;

const UserColumn = ({ record }) => {
  const { picture, name, email, invitationStatus, mfaEnabled } = record;
  return (
    <UserColumnOuter>
      <UserImageInfo
        picture={picture}
        nameInfo={name ? name.trim() : email.trim()}
      />
      <UserColumnInner>
        <NameStatusWrap>
          <NameWrap>{name || 'Unknown'}</NameWrap>
          {invitationStatus &&
          invitationStatus !== 'Accepted' &&
          invitationStatus !== 'Active' ? (
            <StatusWrap
              isexpired={invitationStatus === 'Expired' ? 'expired' : 'pending'}
            >
              {invitationStatus}
            </StatusWrap>
          ) : null}
          {mfaEnabled && <MFAWrapperStatus>MFA enabled</MFAWrapperStatus>}
        </NameStatusWrap>
        <EmailWrap>{email}</EmailWrap>
      </UserColumnInner>
    </UserColumnOuter>
  );
};

const TeamSection = () => {
  const queryClient = useQueryClient();
  const [selectedRowKeys, setSelectedRowKeys] = useState([]);
  const [email, setEmail] = useState();
  const { setSelectedTeamList, searchValue, selectedApp } = useSettingPage();
  const [teammatesList, setTeammatesList] = useState([]);
  const [orgApps, setOrgApps] = useState([]);
  const debouncedSearchValue = useDebounce(searchValue, 500);

  const newProfile = queryClient.getQueryData('profileInfo');
  const definedRoles = queryClient.getQueryData('roles_permission');

  const {
    currentOrgReducer: { orgId },
  } = useSelector((state) => state);

  const { isLoading, data: teamDataList, refetch } = useFetchTeamList(orgId);

  const { refetch: resendInvite, isLoading: resendLoading } =
    useResendInvitation(email, orgId);

  const hasInclude = (string, value) => string && string.includes(value);

  const rowSelection = {
    selectedRowKeys,
    onChange: (keys, selectedRows) => {
      setSelectedRowKeys(keys);
      setSelectedTeamList(selectedRows);
    },
    getCheckboxProps: (record) => ({
      disabled: newProfile?.email === record?.email || handleLowerCase(record?.organizationRole) === 'owner',
      name: record?.organizationRole,
    }),
  };

  const filterTeammates = useMemo(
    () =>
      isArray(teamDataList) && teamDataList?.length &&
      teamDataList.filter((teamValue) => {
        const lowercaseName = handleLowerCase(teamValue?.name);
        const lowercaseEmail = handleLowerCase(teamValue?.email);
        if (debouncedSearchValue || selectedApp) {
          if (debouncedSearchValue && selectedApp) {
            return (
              (hasInclude(lowercaseName, debouncedSearchValue) ||
                hasInclude(lowercaseEmail, debouncedSearchValue)) &&
              teamValue?.apps?.find((app) => app.id === selectedApp)
            );
          }
          if (debouncedSearchValue) {
            return (
              hasInclude(lowercaseName, debouncedSearchValue) ||
              hasInclude(lowercaseEmail, debouncedSearchValue)
            );
          }

          if (selectedApp) {
            return teamValue?.apps?.find((app) => app.id === selectedApp);
          }
        }
        return teamValue;
      }),
    [debouncedSearchValue, selectedApp]
  );

  const validatePermission = useCallback(
    (permissionCode) =>
      newProfile &&
      authorizeAppManagerPermission(
        permissionCode,
        definedRoles,
        newProfile?.organization,
        orgId
      ),
    [newProfile, orgId, definedRoles]
  );

  const validateTeamPermission = useCallback(
    (permissionCode, accessLevel) =>
      newProfile &&
      authorizedOrgAppTeamPermission(
        permissionCode,
        definedRoles,
        newProfile?.organization,
        orgId,
        accessLevel
      ),
    [newProfile, definedRoles, orgId]
  );
  const validateOrgManagerPermission = useCallback(
    (permissionCode) =>
      newProfile &&
      authorizeOrgManagerPermission(
        permissionCode,
        definedRoles,
        newProfile?.organization,
        orgId
      ),
    [newProfile, orgId, definedRoles]
  );

  const columns = [
    {
      title: ({ sortColumns }) => (
        <TableSortColumn
          title="Teammates"
          sortColumns={sortColumns}
          dataIndex="users"
        />
      ),
      dataIndex: 'users',
      width: 200,
      sorter: (a, b) => a?.name?.localeCompare(b?.name),
      sortDirections: ['ascend', 'descend', 'ascend'],
      render: (_, record) => <UserColumn record={record} />,
    },
    {
      title: ({ sortColumns }) => (
        <TableSortColumn
          title="Access level"
          sortColumns={sortColumns}
          dataIndex="accessLevel"
        />
      ),
      dataIndex: 'accessLevel',
      sorter: (a, b) => a?.accessLevel?.localeCompare(b?.accessLevel),
      sortDirections: ['ascend', 'descend', 'ascend'],
      width: 200,
    },
    {
      title: ({ sortColumns }) => (
        <TableSortColumn
          title="Role"
          sortColumns={sortColumns}
          dataIndex="organizationRole"
        />
      ),
      dataIndex: 'organizationRole',
      defaultSortOrder: 'descend',
      sorter: (a, b) => a?.organizationRole?.localeCompare(b?.organizationRole),
      sortDirections: ['ascend', 'descend', 'ascend'],
      width: 200,
      render: (text) => <div>{text || '-'}</div>,
    },
    {
      title: () => <AppListContent />,
      dataIndex: 'apps',
      width: 200,
      render: (_, record) => <TeamAppList apps={record?.apps} orgId={orgId} />,
    },
    {
      title: '',
      key: `action ${v4()}`,
      visible: !validatePermission([
        'organization.team.create',
        'organization.team.update',
        'organization.team.delete',
        'app.team.create',
        'app.team.update',
        'app.team.delete',
      ]),
      width: 200,
      render: (_, record) => {
        const {
          invitationStatus,
          email: recordEmail,
          name,
          accessLevel,
        } = record;

        const isOwnerRow =
          handleLowerCase(record?.organizationRole) === 'owner';
        const isLoginUserOwner =
          teamDataList?.find((team) => team?.email === newProfile?.email)
            ?.organizationRole === 'Owner';
        const isSelfLoginUser = newProfile?.email === recordEmail;
        
        return (
          <ActionWrap>
            {validateTeamPermission(
              [
                'organization.team.create',
                'app.team.create',
                'organization.team.update',
              ],
              accessLevel
            ) && (
              <>
                {invitationStatus &&
                  invitationStatus !== 'Accepted' &&
                  invitationStatus !== 'Active' && (
                    <Tooltip title="Resend invitation">
                      <CircleButton
                        shape="circle"
                        icon={<ResendIconSvg />}
                        disabled={resendLoading}
                        onClick={() => setEmail(recordEmail)}
                      />
                    </Tooltip>
                  )}
              </>
            )}

            {validateTeamPermission(
              ['organization.team.update', 'app.team.update'],
              accessLevel
            ) && (
              <>
                {!isOwnerRow && (
                  <TeammateModalForm
                    selectedTeammate={record}
                    hasTransferOwnership={isLoginUserOwner}
                    refetch={refetch}
                  />
                )}
              </>
            )}

            {(validateTeamPermission(
              ['organization.team.delete', 'app.team.delete'],
              accessLevel
            ) &&
              !isOwnerRow) && !isSelfLoginUser && (
                <TeammateDeleteButton
                  name={name}
                  email={recordEmail}
                  type="single"
                  currentAppList={orgApps}
                  accessApps={record?.apps}
                  accessLevel={accessLevel}
                />
              )}
          </ActionWrap>
        );
      },
    },
  ].filter((item) => !item?.visible);

  useEffect(() => {
    if (newProfile) {
      const orgIndex = findOrgIndex(newProfile?.organization, orgId);
      setOrgApps(newProfile?.organization[orgIndex]?.apps);
    }
  }, [newProfile]);

  useEffect(() => {
    setTeammatesList(filterTeammates);
  }, [selectedApp, debouncedSearchValue]);

  useEffect(() => {
    isArray(teamDataList) && teamDataList?.length && setTeammatesList(teamDataList);
  }, [teamDataList]);

  useEffect(() => {
    orgId && refetch();
  }, [orgId]);

  useEffect(() => {
    email &&
      resendInvite().then((res) => {
        res?.data?.message && message.success(res?.data?.message);
        res?.error?.message &&
          message.error(res?.error?.message || 'Unable to resend invitation');
        setEmail();
      });
  }, [email]);

  return (
    <LoaderAdvanced
      show={isLoading}
      message={<ReactLoader type="spin" />}
      backgroundStyle={{
        backgroundColor: 'rgba(255,255,255,1)',
      }}
    >
      <>
        <TableWrap
          showSorterTooltip={false}
          className="team-table"
          rowSelection={
            validateOrgManagerPermission(['organization.team.delete'])
              ? rowSelection
              : ''
          }
          columns={columns}
          dataSource={teammatesList || []}
          pagination={false}
          rowKey={(record) => record?.email}
        />
      </>
    </LoaderAdvanced>
  );
};

export default TeamSection;
