import React, { useMemo } from 'react';

import { Form, Checkbox } from 'antd';
import { Spinner } from 'uxcam-frontend-components';

import { useAiFilterSettings } from 'components/shared/GlobalFilter/components/MegaFilterDropdownV2/AiFilter/hooks/useAiSettings';

import { MainContainer, ToggleCard } from './styles';

const FilterAI = () => {
    const [form] = Form.useForm();
    const {getAiFilterSettings, updateAiFilterSettings} = useAiFilterSettings();

    const { data: aiFilterData, isLoading } = getAiFilterSettings;

    
    const aiFilterSettings = useMemo(() => aiFilterData?.data?.data?.aiFilter, [aiFilterData]);

    const formInitialValues = useMemo(() => ({
        'ai-filter': aiFilterSettings,
    }), [aiFilterSettings]);

    const handleAiFilterCheck = (value: boolean) => {
        updateAiFilterSettings.mutate({
            aiFilter: value,
        });
    }

    if (isLoading) {
        return <Spinner />;
    }

    return (
            <MainContainer
                form={form}
                initialValues={formInitialValues}
                onFieldsChange={(changedFields) => {
                    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                    // @ts-expect-error
                    const aiFilterCheckbox = changedFields.find((field)=> field.name[0] === 'ai-filter');
                    aiFilterCheckbox?.touched && handleAiFilterCheck(aiFilterCheckbox.value);
                }}
            >
                <ToggleCard>
                    <span className="header">
                        <span className='title'>UXCAM AI</span>
                    </span>
                    <div className='content'>
                        <div className='item-wrapper'>
                            <Form.Item
                                name="ai-filter"
                                valuePropName="checked"
                                noStyle
                            >
                                <Checkbox
                                    disabled={isLoading || updateAiFilterSettings.isLoading}
                                />
                            </Form.Item>
                            <div className='label-content'>
                                <span className='title'>Smart filters</span>
                                <span>Let your team try UXCam&apos;s Smart filters for accurate and efficient analysis.</span>
                            </div>
                        </div>
                    </div>
                </ToggleCard>
            </MainContainer>
    )
}

export default FilterAI